window.__LEX={"G2100":"<h1>euaresteo</h1>\n<p>Strong n° 2100 <i>Prononciation [yoo-ar-es-teh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être agréable à quelqu'un</li>\n<li>prendre plaisir à une chose</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐαρεστέω-ῶ</b> <span>[ᾰ]</span><br><b>      1</b> être agréable à, plaire à, <i>dat</i>. DS. <i>14, 4 ;</i> SPT. <i>Gen. 5, 22 ;</i><br><b>      2</b> se plaire à, se complaire dans, <i>dat</i>. DH. <i>11, 60 ;</i> PLUT. <i>M. 121</i> f ; <i>abs</i>. LYSIPP. <i>fr. 1 ;</i><br><b><i>Moy.</i></b> se complaire dans, être content de, <i>dat</i>. DS. <i>14, 4 ; 17, 113</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. 3 sg</i>. εὐηρεστεῖτο, DS. <i>20, 78</i>.<br><span><b>Étym</b>. εὐάρεστος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευαρεστεω - εὐαρεστέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (3)</li>\n</ul>\n</td></tr>\n</table>","G2101":"<h1>euarestos</h1>\n<p>Strong n° 2101 <i>Prononciation [yoo-ar'-es-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>très plaisant, acceptable, agréable, qui plaît, agrée de</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐ·άρεστος, ος, ον</b> <span>[ᾰ]</span> qui plaît, agréable : τινι, SPT. <i>Sap. 4, 10 ;</i> NT. <i>2Cor. 5, 9 ;</i> παρά τινι, SPT. <i>Sap. 9, 10 ;</i> πρός τινα, CLÉM. <i>882,</i> à qqn ; τὸ εὐάρεστον, NT. <i>Rom. 12, 2, c</i>. εὐαρέστησις.<br><span><b>Étym</b>. εὖ, ἀρέσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευαρεστος - εὐάρεστος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 7 livres bibliques (NT)\n<ul>\n<li>Romains (3)</li>\n<li>2 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2102":"<h1>euarestos</h1>\n<p>Strong n° 2102 <i>Prononciation [yoo-ar-es'-toce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>d'une manière qui plaise, acceptable, agréable, de manière à être agréable</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐαρέστως</b> <span>[ᾰ]</span> <i>adv</i>., d’une façon agréable, NT. <i>Hebr. 12, 28 ;</i> εὐαρεστοτέρως ἔχειν, XÉN. <i>Mem. 3, 5, 5,</i> se rendre plus agréable.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευαρεστως - εὐαρέστως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2103":"<h1>Euboulos</h1>\n<p>Strong n° 2103 <i>Prononciation [yoo'-boo-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Eubulus = « prudent, avisé »\n<ol><li>Chrétien romain</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Εὔ·ϐουλος, ου (ὁ)</b> Euboulos (Eubule) <i>h</i>. THC. <i>8, 23 ;</i> XÉN. <i>Hell. 1, 1, 22, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. épq</i>. Εὐϐούλοιο, ANTH. <i>7, 452 ; avec crase</i> τωὐϐούλοιο, THCR. <i>Idyl. 2, 66</i>.<br><span><b>Étym</b>. <i>v</i>. εὔϐουλος.</span><br><br>\n<b>εὔ·ϐουλος, ος, ον</b>, de bon conseil, HDT. <i>8, 110 ;</i> THC. <i>1, 84 ;</i> SOPH. <i>O.C. 9, 47 ;</i> EUR. <i>Rhes. 105, etc. ; particul. ép. de Thémis,</i> PD. <i>O. 13, 8</i>.<br><span><b><span class=\"arrow\"></span></b> <i>• Cp</i>. -ότερος, AR. <i>Pax 689</i> PLAT. <i>Sis. 391</i> c. <i>• Sup</i>. -ότατος, AND. <i>18, 18</i>.<br><span><b>Étym</b>. εὖ, βουλή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ευβουλος - Εὔβουλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2104":"<h1>eugenes</h1>\n<p>Strong n° 2104 <i>Prononciation [yoog-en'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>bien né, de race noble</li>\n<li>à l'esprit noble</li>\n<li>d'un bon naturel, d'une nature aimable</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐ·γενής, ής, ές :<br>   I</b> bien né, <i>càd. :</i><br><b>      1</b> de bonne naissance, de noble origine, de bonne race, ESCHL. <i>Pers. 704 ;</i> SOPH. <i>O.C. 728 ; c. titre d’honneur, au</i> <i>• Sup</i>. εὐγενέστατος, très noble, BAS. <i>4, 1040</i> c, CHRYS. <i>3, 606 a edd. Migne ; en parl. d’animaux (cheval,</i> THGN. <i>184 ;</i> SOPH. <i>El. 25 ; lion,</i> ESCHL. <i>Ag. 1259, chien,</i> PLAT. <i>Rsp. 375</i> a) ; <i>de plantes,</i> EL. <i>V.H. 2, 14 ; p. anal. en parl. de pays,</i> PLUT. <i>Cato mi. 25 ; de la vigueur des organes du corps,</i> TH. <i>H.P. 5, 1, 7 ; de la beauté du corps, de la noblesse des traits,</i> SOPH. <i>fr. 713 ;</i> EUR. <i>Hel. 10 ; en parl. du style,</i> EL. <i>N.A. fin ;</i><br><b>      2</b> <i>au mor. (d’ord. en ce sens</i> γενναῖος) de nobles sentiments, généreux, ESCHL. <i>Sept. 409 ;</i> SOPH. <i>Ant. 38, Ph. 874 ;</i> EUR. <i>Tr. 1035 ;</i> PLAT. <i>Def. 413</i> b ;<br><b>   II</b> qui est la marque d’une noble origine : τὸ ἐστίχθαι εὐγενές, HDT. <i>5, 6,</i> être tatoué est un signe de noblesse.<br><span>•<i> Cp</i>. εὐγενέστερος, ARSTT. <i>Plant. 1, 1 et 2</i>. <i>• Sup</i>. εὐγενέστατος, SOPH. (PLUT. <i>M. 282</i> b) ; XÉN. <i>Hell. 4, 1, 7 ;</i> TH. <i>H.P. 5, 1, 7, etc</i>.<br><span><b>Étym</b>. εὖ, γένος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευγενης - εὐγενής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2105":"<h1>eudia</h1>\n<p>Strong n° 2105 <i>Prononciation [yoo-dee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un ciel serein, beau temps</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐδία, ας (ἡ) :<br>      1</b> temps serein, beau temps, <i>p. opp. à</i> χειμών, PD. <i>I. 6, 38 ;</i> ARSTT. <i>H.A. 5, 19, 3 ;</i> εὐδίας, ARSTT. <i>H.A. 8, 12, 10 ;</i> ἐν εὐδίᾳ, XÉN. <i>Hell. 2, 4, 14 ;</i> ἐν εὐδίαις, PLAT. <i>Leg. 961</i> f ; ἐν ταῖς γαλήναις καὶ εὐδίαις, ARSTT. <i>H.A. 4, 8 ;</i> εὐδιῶν οὐσῶν, ARSTT. <i>H.A. 9, 40, 36,</i> par un beau temps ; <i>particul</i>. calme de la mer, <i>joint à</i> γαλήνη, PLUT. <i>M. 126</i> c, <i>662</i> c ;<br><b>      2</b> <i>fig</i>. calme, sérénité (de l’âme, de l’esprit, <i>etc</i>.), PD. <i>O. 1, 98, etc. ;</i> ESCHL. <i>Sept. 795 ;</i> XÉN. <i>An. 5, 8, 19 ; p. anal</i>. σαρκὸς εὔδ. PLUT. <i>M. 126</i> c, bon état de la chair.<br><span><b>Étym</b>. εὔδιος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευδια - εὐδία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G2106":"<h1>eudokeo</h1>\n<p>Strong n° 2106 <i>Prononciation [yoo-dok-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qui semble bon à quelqu'un, il est de son bon plaisir, trouver bon, juger bon, approuver\n<ol type=\"a\">\n<li>penser que ceci est bon, choisir, déterminer, décider</li>\n<li>faire volontiers</li>\n<li>être prêt à, préférer, choisir plutôt</li>\n</ol>\n</li>\n<li>prendre plaisir à, être favorablement incliné envers quelqu'un agréer, se complaire en</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐδοκέω-ῶ :<br>      1</b> juger bon, approuver, être satisfait : τινι, POL. <i>2, 38, 7 ; 3, 8, 7 ;</i> ἔν τινι, SPT. <i>4Reg. 22, 20 ;</i> NT. <i>2Cor. 12, 10 ; cf. Matthäi 3, 17 ; avec l’acc</i>. τι, SPT. <i>Ps. 67, 16 ; Lev. 26, 34,</i> être content de qqe ch., se complaire dans qqe ch. ; <i>avec un rég. de pers. au dat</i>. εὐδ. τινι, DS. <i>17, 47 ; avec</i> ἐπί <i>et le dat</i>. SPT. <i>Jer. 2, 19 ; avec</i> εἰς <i>et l’acc</i>. NT. <i>Matth. 12, 18,</i> acquiescer au désir de qqn ; <i>avec une prop. inf</i>. POL. <i>1, 8, 4, etc. ; <i>ou</i> un part</i>. POL. <i>2, 38, 4 ; avec un inf</i>. POL. <i>5, 93, 7 ;</i> SPT. <i>Sir. 25, 16,</i> juger bon de, être satisfait de <i>ou</i> que, consentir ;<br><b>      2</b> <i>impers</i>. εὐδοκεῖ τινι, POL. <i>20, 5, 10,</i> il semble bon à qqn, on approuve ;<br><b><i>Moy.</i></b> être content de : τινι, POL. <i>3, 31, 6 ; 27, 3, 5 ;</i> ἐπί τινι, POL. <i>1, 8, 4,</i> de qqe ch., se complaire en qqe ch.<br><span><b>Étym</b>. εὖ, δοκέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευδοκεω - εὐδοκέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n21 fois dans 21 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (2)</li>\n<li>Galates (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Hébreux (3)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2107":"<h1>eudokia</h1>\n<p>Strong n° 2107 <i>Prononciation [yoo-dok-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>volonté, choix\n<ol type=\"a\">\n<li>bonne volonté, bienveillante intention, bienveillance, bonne grâce</li>\n</ol>\n</li>\n<li>délices, plaisir, satisfaction, bon plaisir</li>\n<li>désir, vœu, souhait</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐδοκία, ας (ἡ)</b> bonne volonté, SPT. <i>Ps. 5, 13, etc. ;</i> NT. <i>Luc. 2, 14 ; 2Cor. 5, 8, etc</i>.<br><span><b>Étym</b>. εὐδοκέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευδοκια - εὐδοκία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (2)</li>\n<li>Romains (1)</li>\n<li>Ephésiens (2)</li>\n<li>Philippiens (2)</li>\n<li>2 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G2108":"<h1>euergesia</h1>\n<p>Strong n° 2108 <i>Prononciation [yoo-erg-es-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une bonne action, un bienfait, bienfaisance envers quelqu'un action de faire du bien, bons offices</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐεργεσία, ας (ἡ) :<br>      1</b> bonne action, action honnête, <i>p. opp. à</i> κακοεργία, OD. <i>22, 374 ;</i> XÉN. <i>Cyr. 8, 7, 13 ;</i><br><b>      2</b> bienfaisance, bienfait, service, OD. <i>22, 235 ;</i> HDT. <i>3, 47 et 67 ; 5, 11 ;</i> ATT. ; εὐεργεσίαν (<i>ion</i>. εὐεργεσίην) ποιέειν, HDT. <i>4, 165 ;</i> προέσθαι, XÉN. <i>An. 7, 7, 47 ;</i> προσφέρειν, PLAT. <i>Gorg. 513</i> e ; καταθέσθαι ἔς τινα, THC. <i>1, 128 ; ou</i> πρός τινα, DÉM. <i>193, 22,</i> rendre un service, accorder <i>ou</i> conférer un bienfait à qqn ; ἀντ' εὐεργεσίας, SIM. <i>fr. 150, 4 ;</i> THCR. <i>Idyl. 17, 116,</i> en échange d’un service, d’un bienfait ; <i>p. suite,</i> titre de bienfaiteur (avec les privilèges attachés à ce titre dans les villes grecques) THC. <i>1, 129 ;</i> DÉM. <i>475, 11</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. εὐεργεσίη, OD. HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. εὐεργέτης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευεργεσια - εὐεργεσία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2109":"<h1>euergeteo</h1>\n<p>Strong n° 2109 <i>Prononciation [yoo-erg-et-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>faire le bien, accorder des bienfaits, se montrer bienfaisant</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐεργετέω-ῶ</b> <span>(<i>impf</i>. εὐεργέτουν <i>et</i> εὐηργέτουν, <i>f</i>. εὐεργετήσω, <i>ao</i>. εὐεργέτησα, <i>pf</i>. εὐεργέτηκα <i>et</i> εὐηργέτηκα)</span> faire du bien : τινα, ESCHL. <i>Eum. 725,</i> à qqn ; εὐεργεσίαν εὐ. τινα, PLAT. <i>Ap. 36</i> c, faire du bien à qqn ; εὐ. τινά τι, PLAT. <i>Rsp. 345</i> a, rendre qqe service à qqn ; μεγάλως <i>ou</i> μεγάλα, XÉN. <i>Cyr. 8, 2, 10 et 12,</i> rendre de grands services ; <i>d’où au pass</i>. recevoir des bienfaits : εὐεργεσίαν εὐεργετηθείς, PLAT. <i>Gorg. 520</i> c, qui a reçu qqe bienfait ; μείζονα εὐεργετημένος, XÉN. <i>Mem. 2, 2, 3,</i> qui a reçu de plus grands bienfaits ; ὑπό τινος, PLAT. <i>Crit. 43</i> a, de qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Impf</i>. εὐεργέτουν, XÉN. <i>Ap. 26 ; Ages. 4, 4 (var</i>. εὐηργ-). <i>Ao</i>. εὐεργέτησα, ISOCR. <i>52</i> b ; <i>ou</i> εὐηργέτησα, AR. <i>Pl. 835 ;</i> LYS. <i>115, 22. Pf</i>. εὐεργέτηκα, PLAT. <i>Rsp. 615</i> b ; DÉM. <i>467, 13 ; ou</i> εὐηργέτηκα, LYCURG. <i>167, 38 ; deux fois sans augm. dans les inscr. att. :</i> εὐεργέτηκεν, CIA. <i>2, 271, 4 (302 av. J.C.), et</i> εὐεργετήκασι, CIA. <i>2, 283, 10 (env. 300 av. J.C.) ; v. Meisterh. p. 136, 14. Pass. ao. part</i>. εὐεργετηθείς (<i>v. ci-dessus) ; pf</i>. εὐεργέτημαι, XÉN. <i>Mem. 2, 2, 3 (var</i>. εὐηργ-) ; PLAT. <i>Crit. 43</i> a.<br><span><b>Étym</b>. εὐεργέτης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευεργετεω - εὐεργετέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2110":"<h1>euergetes</h1>\n<p>Strong n° 2110 <i>Prononciation [yoo-erg-et'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>bienfaiteur</li>\n<li>un titre d'honneur, décerné à celui qui a rendu des services dans sa région, et aux princes, équivalent à Soter, Pater Patriae (Père de la Patrie)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐεργέτης, ου (ὁ) :<br>   I</b> <i>adj</i>. bienfaisant, PD. <i>O. 2, 104 ;</i><br><b>   II</b> <i>subst</i>. bienfaiteur, SOPH. <i>Ant. 284 ; avec un gén</i>. PD. <i>I. 53 ;</i> EUR. <i>Rhes. 151 ;</i> PLAT. <i>Crat. 403</i> e ; <i>qqf. avec un dat</i>. HDT. <i>6, 30,</i> EUR. <i>H.f. 1252 ; particul. titre de bienfaiteur décerné dans les villes grecques,</i> HDT. <i>8, 85 ;</i> XÉN. <i>Hell. 6, 1, 4 ;</i> PLAT. <i>Gorg. 506</i> c.<br><span><b><span class=\"arrow\"></span></b> <i>Acc. sg. dor</i>. εὐεργέταν <span>[ᾱ]</span> PD. <i>ll. cc</i>.<br><span><b>Étym</b>. εὐεργετέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευεργετης - εὐεργέτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2111":"<h1>euthetos</h1>\n<p>Strong n° 2111 <i>Prononciation [yoo'-thet-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>bien placé, approprié\n<ol type=\"a\">\n<li>convenable, propre à</li>\n<li>utile</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὔ·θετος, ος, ον</b>, bien disposé, bien arrangé, HPC. <i>Off. 744 ; d’où</i> qui s’adapte bien, convenable (instrument, vêtement) ESCHL. <i>Sept. 642, etc. ; en parl. de pers</i>. εὔθ. τινι, N. DAM. (STOB. <i>Fl. 1, 331</i>) ; πρός τι, POL. <i>25, 5, 6 ;</i> κατά τι, DS. <i>Exc. 598, 34,</i> propre à qqe ch.<br><span>•<i> Cp</i>. -ώτερος, HPC.<br><span><b>Étym</b>. εὖ, τίθημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευθετος - εὔθετος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2112":"<h1>eutheos</h1>\n<p>Strong n° 2112 <i>Prononciation [yoo-theh'-oce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>directement, immédiatement, sur-le-champ, tout de suite</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐθέως</b>, <i>adv</i>., aussitôt, tout de suite, ATT. ; ἐπεὶ εὐθέως, XÉN. <i>Hell. 3, 2, 4,</i> aussitôt que ; οἷον εὐθέως, POL. <i>6, 52, 1,</i> bref, pour prendre un exemple.<br><span><b>Étym</b>. εὐθύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευθεως - εὐθέως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n80 fois dans 80 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (15)</li>\n<li>Marc (40)</li>\n<li>Luc (8)</li>\n<li>Jean (4)</li>\n<li>Actes (9)</li>\n<li>Galates (1)</li>\n<li>Jacques (1)</li>\n<li>3 Jean (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2113":"<h1>euthudromeo</h1>\n<p>Strong n° 2113 <i>Prononciation [yoo-thoo-drom-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>prendre un trajet direct, aller en ligne droite, filer tout droit</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐθυδρομέω-ῶ</b>, courir en droite ligne, PHIL. <i>1, 131, 327 ;</i> NT. <i>Ap. 16, 11</i>.<br><span><b>Étym</b>. εὐθυδρόμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευθυδρομεω - εὐθυδρομέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G2114":"<h1>euthumeo</h1>\n<p>Strong n° 2114 <i>Prononciation [yoo-thoo-meh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rassurer, réjouir, rendre gai\n<ol type=\"a\">\n<li>esprit bien disposé, rassuré</li>\n</ol>\n</li>\n<li>être joyeux, être réjoui, prendre courage</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐθυμέω-ῶ</b> <span>[ῡ]</span><br><b>   I <i>intr</i>.<br>      1</b> avoir bon courage, PLUT. <i>M. 465</i> c ; se réjouir, EUR. <i>Cycl. 530 ;</i><br><b>      2</b> avoir bonne volonté, être bienveillant, THCR. <i>Idyl. 15, 143 ;</i><br><b>   II <i>tr.</i></b> donner bon courage à, encourager, rassurer, <i>acc</i>. ESCHL. <i>fr. 281, 4 ; cf</i>. DÉMOCR. (STOB. <i>Fl. 83, 25) ; d’où au pass</i>. avoir bon courage, XÉN. <i>Cyr. 4, 1, 19 ;</i> ARSTT. <i>Rhet. 2, 2, 20</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Part. éol</i>. εὐθυμήσαις, THCR. <i>Idyl. l. c</i>.<br><span><b>Étym</b>. εὔθυμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευ-θυμεω - εὐθυμέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2115":"<h1>euthumos</h1>\n<p>Strong n° 2115 <i>Prononciation [yoo'-thoo-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>bien disposé, aimable</li>\n<li>de bonne humeur, d'un bon courage, plein de confiance</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὔ·θυμος, ος, ον</b> <span>[ῡ]</span><br><b>      1</b> qui a bon cœur, généreux, OD. <i>14, 63 ;</i><br><b>      2</b> qui a bon courage, plein de confiance, d’ardeur, PD. <i>O. 5, 52 ;</i> XÉN. <i>Cyr. 6, 4, 13 ;</i> PLAT. <i>Leg. 797</i> b ; <i>en parl. de chevaux,</i> XÉN. <i>Eq. 11, 12 ;</i> τὸ εὔθυμον, <i>c</i>. εὐθυμία, PLUT. <i>M. 1106</i> c ; DC. <i>42, 1</i>.<br><span>•<i> Cp</i>. -ότερος, XÉN. <i>Cyr. 6, 4, 13 ;</i> ARSTT. <i>Probl. 104 ;</i> HDN <i>6, 6, 13</i>.<br><span><b>Étym</b>. εὖ, θυμός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευ-θυμος - εὔθυμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G2116":"<h1>euthuno</h1>\n<p>Strong n° 2116 <i>Prononciation [yoo-thoo'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre droit, niveler, aplanir</li>\n<li>mener ou conduire droitement, garder le droit chemin\n<ol type=\"a\">\n<li>du timonier ou homme de barre d'un navire</li>\n<li>d'un conducteur de char</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐθύνω</b> <span>[ῡ]</span> <span>(<i>impf</i>. ηὔθυνον, <i>f</i>. εὐθυνῶ <span>[ῠ]</span>, <i>ao</i>. ηὔθυνα, <i>pf. inus</i>.)</span><br><b>   I <i>tr</i>.<br>      1</b> diriger : ἡνίας, AR. <i>Av. 1738,</i> des rênes ; ἅρματα, ISOCR. <i>9</i> a, des chars ; ἀγέλας, XÉN. <i>Cyr. 1, 1, 2,</i> conduire des troupeaux ; πόδα, EUR. <i>Her. 728,</i> diriger ses pas ; <i>fig</i>. στρατόν, ESCHL. <i>Pers. 773,</i> conduire une armée ; πόλιν, SOPH. <i>Ant. 178,</i> gouverner une cité ; οὖρον, PD. <i>O. 13, 38,</i> maintenir le souffle (de l’heureuse fortune de qqn) ; δίκας λαοῖς, PD. <i>P. 4, 153,</i> rendre la justice avec droiture aux peuples ;<br><b>      2</b> redresser, corriger, PLAT. <i>Prot. 325</i> d, <i>etc. ;</i> δίκας σκολιάς, SOL. <i>3, 36,</i> des jugements tortueux ; <i>d’où</i> censurer, blâmer, <i>en gén</i>. PLUT. <i>Nic. 1 ;</i><br><b>      3</b> <i>particul. à Athènes,</i> vérifier les comptes <i>ou</i> la gestion des magistrats, PLAT. <i>Pol. 299</i> a ; ARSTT. <i>Rhet. 2, 9 ; d’où</i> traduire en justice : τινὰ κλοπῆς, PLUT. <i>Cic. 9,</i> qqn pour vol ; τινὰ παρά τινι, LUC. <i>J. voc. 2,</i> qqn devant un magistrat ; <i>au pass</i>. τῶν ἀδικημάτων εὐθ. THC. <i>1, 95,</i> être traduit en justice pour ses méfaits ;<br><b>   II <i>intr.</i></b> être vérificateur des comptes (<i>v</i>. εὔθυνος) PLAT. <i>Leg. 946</i> c.<br><span><b>Étym</b>. εὔθυνος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευθυνω - εὐθύνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2117":"<h1>euthus</h1>\n<p>Strong n° 2117 <i>Prononciation [yoo-thoos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>droit, de niveau, aplani</li>\n<li>droit, juste, vrai, sincère</li>\n<li>directement, immédiatement, sur-le-champ</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>εὐ·θύς, εῖα, ύ</b>, droit, direct :<br><b>   I</b> <i>au propre,</i> PD. <i>O. 6, 177, etc. ; p. opp. à</i> στρογγύλος, PLAT. <i>Parm. 137</i> e, <i>Men. 75</i> a ; <i>à</i> καμπύλος, PLAT. <i>Rsp. 602</i> c ; <i>à</i> περιφερής, PLAT. <i>Parm. 137</i> e, <i>Phil. 51</i> c ; <i>à</i> πλάγιος, D. PHAL. <i>104 ;</i> ὁδὸς εὐθ. THC. <i>2, 100 ;</i> XÉN. <i>Cyr. 1, 3, 4,</i> route en ligne droite ; <i>subst</i>. ἡ εὐθεῖα :<br><b>      1</b> (<i>s.-e</i>. ὁδός) la droite voie : κατ' εὐθεῖαν, ARSTT. <i>Mund. 4 ;</i> ἐπὶ τὴν εὐθεῖαν, POL. <i>3, 113, 2 ;</i> ἐπ' εὐθείας, POL. <i>3, 113, 3 ;</i> DS. <i>19, 38 ;</i> GEOP. <i>5, 11, 3 ; 7, 15, 2 ;</i> ἀπ' εὐθείας, PLUT. <i>Fab. 3,</i> en droite ligne, directement ;<br><b>      2</b> (<i>s.-e</i>. γραμμή) ARSTT. <i>Cæl. 2, 4, 2,</i> ligne droite ; ἐπὶ τὴν αὐτὴν εὐθεῖαν, POL. <i>3, 113, 2 ;</i> ἐπὶ τῆς αὐτῆς εὐθείας, POL. <i>3, 113, 3,</i> sur la même ligne droite ;<br><b>      3</b> (<i>s.-e</i>. πτῶσις) D. THR. <i>632, 10 ; 635, 5 ;</i> DRAC. <i>18, 5 ;</i> DYSC. <i>Pron. 268</i> c, <i>289</i> b ; <i>Synt. 12, 18 ; 14, 15,</i> le cas direct, <i>càd</i>. le nominatif ;<br><b>   II</b> <i>fig. :</i><br><b>      1</b> sans détour, franc, PD. <i>N. 10, 22 ;</i> TYRT. <i>2, 8 ;</i> EUR. <i>Hipp. 492 ;</i> τὸ εὐθύ τε καὶ τὸ ἐλεύθερον, PLAT. <i>Theæt. 173</i> a, la droiture et l’indépendance ; ἀπὸ τοῦ εὐθέος, THC. <i>3, 43 ;</i> ἐκ τοῦ εὐθέος, THC. <i>1, 34 ; p. opp. à</i> δι' αἰνιγμάτων, PAUS. <i>8, 8, 3 ;</i> δι' εὐθείας, PLUT. <i>M. 408</i> e ; <i>ou</i> ἀπ' εὐθείας, PLUT. <i>M. 57</i> a, <i>etc</i>. sans détour, ouvertement, franchement ;<br><b>      2</b> régulier, correct, juste, SOL. (ARSTD. <i>t. 2, 397</i>) ; PD. <i>N. 10, 12 ;</i> ESCHL. (GAL. <i>9, 385</i>).<br><span>•<i> Cp</i>. -ύτερος, XÉN. <i>Cyr. 1, 3, 4 ;</i> ARSTT. <i>Probl. 5, 11</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span><br><br>\n➁ <b>εὐ·θύς, <i>adv</i>., :<br>      1</b> <i>en parl. du lieu,</i> directement, droit, <i>abs</i>. PD. <i>O. 8, 41 ;</i> εὐ. ἐπὶ τὴν γέφυραν, THC. <i>4, 118 (traité</i>) ; εὐ. πρός, <i>acc</i>. XÉN. <i>Cyr. 2, 4, 24 ; ou simpl</i>. εὐθύς <i>avec le gén</i>. τὴν εὐθὺς Ἄργους ὁδόν, EUR. <i>Hipp. 1197,</i> la route qui conduit directement à Argos ;<br><b>      2</b> <i>en parl. du temps,</i> tout de suite, aussitôt, PD. <i>O. 8, 41 ;</i> SOPH. <i>Aj. 317, etc. ;</i> τάχα δ' εὐ. PD. <i>P. 4, 147 ;</i> εὐ. κατὰ τάχος, THC. <i>6, 101 ;</i> εὐ. ἐξ ἀρχῆς, XÉN. <i>Cyr. 7, 2, 16 ;</i> ISOCR. <i>50</i> d ; ἐξ ἀρχῆς εὐθύς, ARSTT. <i>Pol. 3, 16, 9 ;</i> εὐθ. ἀπ' ἀρχῆς, AR. <i>Pax 84 ; à côté de</i> παραχρῆμα, DÉM. <i>81, 12,</i> tout de suite, tout d’abord, sur-le-champ ; εὐθὺς ἐκ παιδός, PLAT. <i>Rsp. 519</i> a ; εὐθ. ἐκ παιδίου, XÉN. <i>Cyr. 1, 6, 20,</i> tout de suite au sortir de l’enfance, dès la plus tendre enfance ; <i>avec un part. :</i> εὐθὺς νέοι ὄντες, THC. <i>2, 39,</i> dès la jeunesse ; <i>cf</i>. XÉN. <i>An. 2, 6, 18 ; 4, 7, 2 ;</i> DÉM. <i>662, 10 ; avec une conj</i>. εὐ. ὡς, ESCHL. <i>Pers. 361,</i> aussitôt que ; <i>entre l’art. et le subst</i>. ἡ εὐ. φυγή, HDN <i>8, 1, 10,</i> fuite soudaine ; <i>dans certaines loc. adv. :</i> οἷον εὐθύς, PLUT. <i>M. 436</i> a, précisément (<i>litt</i>. directement), par exemple ; ὥσπερ ζῷον εὐθύς, ARSTT. <i>Pol. 3, 4, 6,</i> par exemple un animal.<br><span><b>Étym</b>. <i>cf</i>. εὐθύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευθυς - εὐθύς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n15 fois dans 15 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (3)</li>\n<li>Luc (2)</li>\n<li>Jean (2)</li>\n<li>Actes (3)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2118":"<h1>euthutes</h1>\n<p>Strong n° 2118 <i>Prononciation [yoo-thoo'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>rectitude, justice, droiture</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐθύτης, ητος (ἡ)</b> <span>[ῠ]</span><br><b>      1</b> direction en ligne droite, ARSTT. <i>Categ. 8, 20, etc. ;</i><br><b>      2</b> droiture, justice, SPT. <i>Jos. 24, 14</i>.<br><span><b>Étym</b>. εὐθύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευθυτης - εὐθύτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2119":"<h1>eukaireo</h1>\n<p>Strong n° 2119 <i>Prononciation [yoo-kahee-reh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>avoir l'occasion, l'opportunité</li>\n<li>avoir le loisir</li>\n<li>faire quelque chose</li>\n<li>donner son temps à une chose</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐκαιρέω-ῶ</b> <span>(<i>impf</i>. ηὐκαίρουν, <i>f</i>. εὐκαιρήσω)</span><br><b>      1</b> avoir du bon temps, du loisir, POL. <i>20, 9, 4 ;</i> NT. <i>Marc. 6, 31 ; Ap. 17, 21 ; 1Cor. 16, 12 ; avec un inf</i>. PLUT. <i>M. 223</i> d ; LUC. <i>Am. 33,</i> avoir le temps de, <i>etc. ;</i> τινι, CHION. <i>Ep. 16 ;</i> εἴς τι, NT. <i>Ap. 17, 21,</i> consacrer son loisir à qqe ch. ;<br><b>      2</b> être dans une bonne situation, <i>particul</i>. dans une bonne situation de fortune, de bien-être, <i>etc</i>. POL. <i>4, 6, 10 ; 15, 21, 2, etc. ;</i><br><b><i>Moy.</i></b> être riche <i>ou</i> dans l’aisance, POSIDON. (ATH. <i>275</i> a).<br><span><b>Étym</b>. εὔκαιρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευκαιρεω - εὐκαιρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2120":"<h1>eukairia</h1>\n<p>Strong n° 2120 <i>Prononciation [yoo-kahee-ree'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>temps favorable, opportunité, occasion, bon moment</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐκαιρία, ας (ἡ) :<br>   I</b> opportunité, <i>càd. :</i><br><b>      1</b> moment favorable, PLAT. <i>Phædr. 272</i> a ; ISOCR. <i>239</i> f ; NT. <i>Matth. 26, 16 ;</i><br><b>      2</b> situation favorable (d’une ville) POL. <i>16, 29, 3 ;</i> DS. <i>Exc. p. 499, 39 ; au plur</i>. DS. <i>5, 82 ;</i><br><b>      3</b> convenance, PLUT. <i>M. 16</i> b, <i>736</i> f ;<br><b>   II</b> loisir, HPC. <i>1281, 13 ;</i><br><b>   III</b> bonne situation de fortune, richesse, POL. <i>1, 59, 7, etc. ; d’où</i> abondance, <i>en gén</i>. TH. <i>C.P. 3, 23, 4 ;</i> DS. <i>1, 52</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. εὐκαιρίη, HPC. <i>l. c</i>.<br><span><b>Étym</b>. εὔκαιρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευκαιρια - εὐκαιρία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2121":"<h1>eukairos</h1>\n<p>Strong n° 2121 <i>Prononciation [yoo'-kahee-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>temps favorable, opportun, qui vient à point</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὔ·καιρος, ος, ον :<br>   I</b> opportun, <i>càd. :</i><br><b>      1</b> en temps opportun, SOPH. <i>O.C. 32 ;</i> HDN <i>1, 9, 6 ;</i> ARISTÉN. <i>1, 2 ;</i> τὸ εὔκαιρον, DH. <i>Din. 7,</i> le moment opportun ;<br><b>      2</b> favorablement situé, POL. <i>4, 38, 1 ;</i> DS. <i>1, 63 ;</i><br><b>   II</b> en bonne situation de fortune, riche, POL. <i>13, 9, 1</i>.<br><span>•<i> Cp</i>. εὐκαιρότερος, CIC. <i>Att. 4, 7, 1 ;</i> <i>• Sup</i>. εὐκαιρότατος, POL. <i>4, 38, 1</i>.<br><span><b>Étym</b>. εὖ, καιρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευκαιρος - εὔκαιρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2122":"<h1>eukairos</h1>\n<p>Strong n° 2122 <i>Prononciation [yoo-kah'-ee-roce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>favorablement, opportunément, en temps opportun</li>\n<li>quand l'occasion se présente, au bon moment</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐκαίρως</b>, <i>adv. :</i><br><b>      1</b> à propos, HPC. <i>Ep. 1285 ;</i> ISOCR. <i>111</i> b, <i>223</i> e ; ARSTT. <i>H.A. 7, 1, 18 ;</i> PLUT. <i>M. 1071</i> e ;<br><b>      2</b> à loisir : οὐκ εὐκ. ἔχειν, POL. <i>5, 26, 10,</i> n’avoir pas de loisir.<br><span>•<i> Cp</i>. -ότερον, PLAT. <i>Phæd. 78</i> a ; <i>sup</i>. -ότατα, POL. <i>5, 63, 13</i>.<br><span><b>Étym</b>. εὔκαιρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευκαιρως - εὐκαίρως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2123":"<h1>eukopoteros</h1>\n<p>Strong n° 2123 <i>Prononciation [yoo-kop-o'-ter-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>d'un travail plus facile</li>\n<li>aisé</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>εὐκόπως</b>, <i>adv</i>., avec facilité, AR. <i>fr. 615 ;</i> DS. <i>3, 24 ;</i> HÉRON <i>Bel. 130 ;</i> HÉRON <i>Spir. 161, Aut. 255</i>.<br><span>•<i> Cp</i>. -ώτερον, ANTIP. (STOB. <i>Fl. 67, 25, t. 3, p. 14, l. 32</i>).<br><span><b>Étym</b>. εὔκοπος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευκοπωτερος - εὔκοπωτερος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Luc (3)</li>\n</ul>\n</td></tr>\n</table>","G2124":"<h1>eulabeia</h1>\n<p>Strong n° 2124 <i>Prononciation [yoo-lab'-i-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prudence, circonspection, discrétion\n<ol type=\"a\">\n<li>action d'éviter</li>\n<li>une fuite raisonnable</li>\n</ol>\n</li>\n<li>révérence, vénération\n<ol type=\"a\">\n<li>révérence envers Dieu, crainte pieuse, piété</li>\n</ol>\n</li>\n<li>crainte anxieuse</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐλάϐεια, ας (ἡ)</b> <span>[λᾰ]</span><br><b>      1</b> précaution, circonspection, DÉM. <i>425, 5 ;</i> ARSTT. <i>Pol. 2, 8, 22 ;</i> εὐλ. τινος, PLAT. <i>Leg. 815</i> a, action de se prémunir contre qqe ch. ; δι' εὐλαϐείας ἔχειν τινά, DH. <i>5, 38,</i> prendre ses précautions contre qqn ; εὐλάϐειαν ἔχειν μή, PLAT. <i>Prot. 321</i> a, prendre garde que… ne ;<br><b>      2</b> <i>p. suite,</i> timidité, crainte, PLUT. <i>Fab. 1 ; p. opp. à</i> φόϐος, en un sens moins fort, PLUT. <i>M. 449 ; ttef. joint à</i> φόϐος, DÉM. <i>625, 13 ; particul</i>. crainte des dieux, PLUT. <i>M. 432</i> e ; NT. <i>Hebr. 5, 7 ; 12, 28 ; d’où</i> piété, <i>en gén</i>. DS. <i>13, 12 ;</i> PLUT. <i>Num. 22, Cam. 21 ;</i> titre d’honneur (ta Piété, votre Piété, <i>etc</i>.) BAS. <i>4, 385</i> c ; NAZ. <i>3, 193 b edd. Migne</i>.<br><span><b>Étym</b>. εὐλαϐής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευλαβεια - εὐλάβεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – toujours utilisé dans un sens mauvais\n<br><br> – généralement utilisé dans un bon sens\n<br><br> – utilisé dans un bon ou mauvais sens</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G2125":"<h1>eulabeomai</h1>\n<p>Strong n° 2125 <i>Prononciation [yoo-lab-eh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>agir avec précaution, avec circonspection</li>\n<li>prendre garde, craindre</li>\n<li>révérer, se tenir dans la crainte de</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐλαϐέομαι-οῦμαι</b> <span>[λᾰ]</span> <span>(<i>impf</i>. εὐλαϐούμην <i>et</i> ηὐλαϐούμην, <i>f</i>. εὐλαϐήσομαι <i>et</i> εὐλαϐηθήσομαι, <i>ao</i>. εὐλαϐήθην, <i>pf. inus</i>.)</span> prendre garde à, <i>d’où :</i><br><b>      1</b> prendre garde, se précautionner : περί τι, PLAT. <i>Leg. 927</i> c, <i>Ion 537</i> a ; περί τινος, PLAT. <i>Leg. 691</i> b ; DS. <i>4, 73 ;</i> ἀμφί τινι, LUC. <i>Gall. 21,</i> au sujet de qqe ch. ; <i>avec l’acc</i>. εὐ. τὸν κύνα, AR. <i>Lys. 1215,</i> prendre garde au chien ; τὰς μυίας, ARSTT. <i>H.A. 9, 5, 7,</i> aux mouches ; πενίαν, PLAT. <i>Rsp. 372</i> c : τὸν φθόνον, DÉM. <i>327, 13,</i> prendre ses précautions contre la pauvreté, contre l’envie ; <i>avec l’inf</i>. EUR. <i>Or. 791 ;</i> PLAT. <i>Rsp. 608</i> a, <i>Phædr. 101</i> c ; <i>avec</i> μή <i>et l’inf</i>. EUR. <i>Or. 1059 ; cf</i>. PLAT. <i>Charm. 155</i> d ; <i>avec</i> μή <i>et un mode subord. (sbj. ou opt</i>.) SOPH. <i>Tr. 1129 ; cf</i>. EUR. <i>Hipp. 100 ;</i> AR. <i>Eq. 253 ;</i> PLAT. <i>Phæd. 89</i> c ; <i>avec</i> ὅπως μή <i>et le fut. de l’ind</i>. PLAT. <i>Phæd. 91</i> c, prendre garde que <i>ou</i> de ;<br><b>      2</b> saisir à propos, profiter de, <i>acc</i>. EUR. <i>Or. 699 ;</i><br><b>      3</b> prendre soin de, honorer, révérer, <i>acc</i>. PLAT. <i>Leg. 879</i> e ; PLUT. <i>Per. 7 ; particul</i>. avoir la crainte de Dieu, SPT. <i>Nah. 1, 7 ; Zach. 2, 13</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. impér. poét. 2 sg</i>. εὐλαϐεῦ, CYDIAS <i>fr. 1 Bgk. Impf</i>. ηὐλαϐεῖτο, EUR. <i>Or. 748, 1059 (var</i>. εὐλ.) ; <i>3 pl</i>. εὐλαϐοῦντο, ESCHN. <i>4, 26. Fut. pass. au sens moy</i>. εὐλαϐηθήσομαι, ARSTT. <i>M. mor. 1, 30 ;</i> DL. <i>7, 116</i>.<br><span><b>Étym</b>. εὐλαϐής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευλαβεομαι - εὐλαβέομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2126":"<h1>eulabes</h1>\n<p>Strong n° 2126 <i>Prononciation [yoo-lab-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se tenir dans le bien\n<ol type=\"a\">\n<li>soigneusement et sûrement</li>\n<li>prudemment</li>\n</ol>\n</li>\n<li>craignant Dieu, pieux, religieux</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐ·λαϐής, ής, ές</b> <span>[ᾰ]</span><br><b>   I</b> <i>act. :</i><br><b>      1</b> qui prend ses précautions, qui se tient sur ses gardes : ἀπό τινος, SPT. <i>Lev. 15, 31,</i> contre qqn <i>ou</i> qqe ch. ; <i>abs</i>. circonspect : τὸ εὐλαϐές, PLAT. <i>Pol. 311</i> b, la circonspection, la prudence ; <i>en mauv. part</i>. timide, craintif, timoré, PLUT. <i>Fab. 17 ;</i><br><b>      2</b> <i>particul</i>. qui a la crainte de Dieu, pieux, religieux, NT. <i>Luc. 2, 25 ; Ap. 2, 5, etc. ;</i><br><b>   II</b> <i>pass. :</i><br><b>      1</b> accompli avec prudence, PLAT. <i>Leg. 736</i> d ;<br><b>      2</b> dont il est facile de se garder, LUC. <i>Tim. 29</i>.<br><span>•<i> Sup</i>. -έστατος, SYN. <i>Ep. 67</i>.<br><span><b>Étym</b>. εὖ, λαμϐάνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευλαβης - εὐλαβής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G2127":"<h1>eulogeo</h1>\n<p>Strong n° 2127 <i>Prononciation [yoo-log-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>louer, célébrer par des louanges</li>\n<li>invoquer des bénédictions</li>\n<li>consacrer une chose par des prières solennelles\n<ol type=\"a\">\n<li>demander la bénédiction de Dieu pour une chose</li>\n<li>prier Dieu pour le bénir</li>\n<li>prononcer une bénédiction de consécration</li>\n</ol>\n</li>\n<li>de Dieu\n<ol type=\"a\">\n<li>faire prospérer, rendre heureux, accorder des bénédictions</li>\n<li>favorisé par Dieu, béni</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐλογέω-ῶ :<br>   I</b> parler avec bienveillance, <i>d’où :</i><br><b>      1</b> dire du bien de, louer, célébrer ; τινα, ESCHL. <i>Ag. 580 ;</i> SOPH. <i>Ph. 1314, etc</i>. qqn ; δίκαια εὐλ. τινα, AR. <i>Ach. 372,</i> faire de qqn un juste éloge ; <i>au pass</i>. être loué, SOPH. <i>O.C. 720 ;</i><br><b>      2</b> <i>p. ext</i>. témoigner de la considération à, honorer : τινα, EUR. <i>Suppl. 927,</i> qqn ;<br><b>      3</b> bénir, SPT. <i>Gen. 14, 19 ; avec le dat</i>. SPT. <i>1Esdr. 4, 58 ; avec l’acc</i>. SPT. <i>Gen. 2, 3 ;</i> NT. <i>Marc. 11, 9 ; Luc. 2, 28 ; Jac. 3, 9 ; Matth. 5, 44 ; au pass</i>. NT. <i>Matth. 25, 34 ; Luc. 1, 42 ;</i><br><b>   II</b> <i>p. antiphrase,</i> prononcer une imprécation, SPT. <i>3Reg. 20, 10</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. 3 sg</i>. εὐλόγησεν, SPT. <i>Gen. 2, 3 ; opt. 3 pl</i>. εὐλογήσαισαν, SPT. <i>Tob. 3, 11. Fut. moy</i>. εὐλογήσομαι, <i>au sens pass</i>. ISOCR. <i>190</i> a ; <i>fut. pass</i>. εὐλογηθήσομαι, SPT. <i>Gen. 22, 18 ; ao</i>. εὐλογήθην, PHIL. <i>Ep. 4</i>.<br><span><b>Étym</b>. εὔλογος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευλογεω - εὐλογέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n43 fois dans 40 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Marc (6)</li>\n<li>Luc (13)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (3)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n<li>Hébreux (7)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2128":"<h1>eulogetos</h1>\n<p>Strong n° 2128 <i>Prononciation [yoo-log-ay-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>béni (se dit pour Dieu), loué, dont on dit du bien</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐλογητός, ή, όν</b>, béni, PHIL. <i>1, 453 ;</i> SPT. <i>Ex. 18, 10 ;</i> NT. <i>Luc. 1, 68 ; Rom. 1, 25</i>.<br><span><b>Étym</b>. εὐλογέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευλογητος - εὐλογητός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 6 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Romains (2)</li>\n<li>2 Corinthiens (2)</li>\n<li>Ephésiens (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2129":"<h1>eulogia</h1>\n<p>Strong n° 2129 <i>Prononciation [yoo-log-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>louange, panégyrique : de Christ ou Dieu</li>\n<li>discours flatteur, langage ampoulé\n<ol type=\"a\">\n<li>dans un mauvais sens, langage adapté artificiellement pour captiver l'auditeur: belles paroles, discours flatteur</li>\n</ol>\n</li>\n<li>une invocation de bénédictions</li>\n<li>consécration</li>\n<li>une bénédiction concrète, un bienfait</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐλογία, ας (ἡ)</b> bon langage, <i>d’où :</i><br><b>   I</b> langage agréable, beau langage, PLAT. <i>Rsp. 400</i> d ; LUC. <i>Lex. 1 ;</i><br><b>   II</b> langage honnête et raisonnable, CIC. <i>Att. 13, 22, 4 ;</i><br><b>   III</b> langage bienveillant, <i>d’où :</i><br><b>      1</b> louange, éloge, PD. <i>N. 4, 8 ;</i> EUR. <i>H.f. 356 ;</i> THC. <i>2, 42 ; au plur</i>. PLAT. <i>Ax. 365</i> a ;<br><b>      2</b> bénédiction, SPT. <i>Gen. 49, 25 ; Esaï. 65, 8 ; Ezech. 34, 26 ;</i> NT. <i>Hebr. 12, 17, etc. ;</i><br><b>      3</b> <i>p. suite,</i> bienfait, SPT. <i>Gen. 33, 11 ; Jos. 15, 19 ; Judith 1, 15 ; 1Reg. 25, 21 ;</i> NT. <i>Hebr. 6, 7, etc. ; d’où</i> aumône, NT. <i>2Cor. 9, 5</i>.<br><span><b>Étym</b>. εὔλογος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευλογια - εὐλογία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 14 versets de 9 livres bibliques (NT)\n<ul>\n<li>Romains (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (4)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G2130":"<h1>eumetadotos</h1>\n<p>Strong n° 2130 <i>Prononciation [yoo-met-ad'-ot-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prêt ou disponible pour partager</li>\n<li>libéral, libéralité, qui partage volontiers ce qu'il a</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐ·μετάδοτος, ος, ον</b>, qui partage volontiers ce qu’il a, NT. <i>1Tim. 6, 18 ;</i> τὸ εὐμετάδοτον, M. ANT. <i>1, 14,</i> libéralité.<br><span><b>Étym</b>. εὖ, μεταδίδωμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευμεταδοτος - εὐμετάδοτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2131":"<h1>Eunike</h1>\n<p>Strong n° 2131 <i>Prononciation [yoo-nee'-kay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Eunice = « bénie par la victoire »\n<ol><li>la mère de Timothée</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>εὐ·νίκητος, ος, ον</b> <span>[ῑ]</span> aisé à vaincre, GAL. <i>2, 207, au</i> <i>• Sup</i>. -ότατος.<br><span><b>Étym</b>. εὖ, νικάω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ευνικη - Εὐνίκη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2132":"<h1>eunoeo</h1>\n<p>Strong n° 2132 <i>Prononciation [yoo-no-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>désirer du bien</li>\n<li>être bien disposé, d'un esprit pacifique</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐνοέω-οῶ</b>, être bienveillant, HDT. <i>9, 79 ;</i> τινι, HDT. <i>7, 237 ;</i> SOPH. <i>Aj. 689 ;</i> LYS. <i>131, 1,</i> pour qqn ; <i>au pass</i>. être traité avec bienveillance, MÉN. (STOB. <i>Fl. 1, 125</i>) ; PHALAR. <i>Ep. 4, p. 10</i>.<br><span><b>Étym</b>. εὔνοος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευνοεω - εὐνοέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G2133":"<h1>eunoia</h1>\n<p>Strong n° 2133 <i>Prononciation [yoo'-noy-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>avec bonne volonté, avec bonté, bienveillance, bonnes dispositions</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὔνοια, ας (ἡ)</b> <span>[ᾰ]</span><br><b>   I</b> bienveillance :<br><b>      1</b> en bonne part : ἐπ' εὐνοίᾳ, ESCHL. <i>Sept. 1007 ;</i> δι'εὔνοιαν, PLAT. <i>Prot. 337</i> b ; δι' εὐνοίας, THC. <i>2, 40 ;</i> κατ' εὔνοιαν, HDT. <i>6, 108 ;</i> THC. <i>4, 46 ; 6, 92 ;</i> EUR. <i>Suppl. 940 ;</i> PLAT. <i>Ep. 421</i> a ; εὐνοίας ἕνεκα, DÉM. <i>243, 19,</i> par bienveillance ; εὐνοίᾳ, SOPH. <i>Ph. 1322 ;</i> εὐνοίῃ, HDT. <i>7, 239 ;</i> μετ' εὐνοίας, PLAT. <i>Phædr. 241</i> c ; DÉM. <i>317, 29,</i> avec bienveillance ; <i>avec le gén. de la pers. ou de l’objet à qui s’adresse la bienveillance :</i> εὐνοίας ἕνεκα τῶν Ἑλλήνων, XÉN. <i>An. 4, 7, 20,</i> par bienveillance pour les Grecs ; ἐπ' εὐνοίᾳ χθονός, ESCHL. <i>Sept. 1007,</i> par amour pour la terre natale ; <i>ou avec une prép. :</i> εὔν. πρός τινα, PLAT. <i>Rsp. 470</i> a ; LUC. <i>Scyth. 10 ;</i> εἴς τινα, XÉN. <i>Cyr. 1, 5, 13 ;</i> EUR. <i>Hel. 1425 ;</i> DÉM. <i>243, 19,</i> bienveillance pour qqn, à l’égard de qqn ; <i>souv. avec un pron. possessif marquant l’objet de la bienveillance :</i> εὐνοίᾳ τῇ σῇ, PLAT. <i>Gorg. 486</i> a par bienveillance pour toi ; <i>au pl</i>. sentiments de bienveillance, ESCHL. <i>Suppl. 489, Sept. 450 ;</i> ISOCR. <i>299</i> c ; DS. <i>15, 9 ;</i><br><b>      2</b> <i>en mauv. part, càd</i>. indulgence, <i>d’où</i> partialité : κατ' εὔνοιαν κρίνειν, LYS. <i>188 fin ;</i> ANT. <i>124, 9,</i> juger avec indulgence, avec partialité ;<br><b>      3</b> marque de bienveillance, présent, gratification, DÉM. <i>432, 2 ; au pl</i>. DÉM. <i>96, 9</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. -οίη, ης, HDT. <i>7, 239 ; épq</i>. -οΐη, ANTH. <i>App. 318</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευνοια - εὔνοια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2134":"<h1>eunouchizo</h1>\n<p>Strong n° 2134 <i>Prononciation [yoo-noo-khid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>châtrer, castrer un homme</li>\n<li>métaph. se rendre soi-même eunuque, c.à.d par abstinence, comme un eunuque s'abstient du mariage</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐνουχίζω</b>, rendre eunuque, mutiler, LUC. <i>Cron. 12 ;</i> ATH. <i>515</i> c ; <i>au pass</i>. DC. <i>68, 2</i>.<br><span><b>Étym</b>. εὐνοῦχος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευνουχιζω - εὐνουχίζω</font>\n<br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2)</li>\n</ul>\n</td></tr>\n</table>","G2135":"<h1>eunouchos</h1>\n<p>Strong n° 2135 <i>Prononciation [yoo-noo'-khos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le gardien du lit, l'intendant de la chambre à coucher, le chambellan\n<ol type=\"a\">\n<li>dans les palais orientaux, où le monarque avait de nombreuses épouses, l'eunuque était l'intendant du harem</li>\n<li>un homme émasculé, un eunuque\n<ol>\n<li>cet homme pouvait avoir un rôle très important, comme par exemple l'eunuque Ethiopien mentionné dans <a class=\"ref\" data-r=\"ACT8.27-39\">Actes 8.27-39</a></li>\n</ol>\n</li>\n<li>celui qui a une incapacité naturelle\n<ol>\n<li>au mariage</li>\n<li>à avoir des enfants</li>\n</ol>\n</li>\n<li>celui qui s'abstient volontairement du mariage</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐνοῦχος, ου (ὁ) :<br>   I</b> eunuque (<i>litt</i>. gardien de la couche, <i>càd</i>. gardien des femmes) <i>en Orient, puis en Grèce,</i> HDT. <i>1, 117, etc. ;</i> XÉN. <i>Cyr. 7, 5, 60 ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> <i>en parl. de fruits,</i> sans graine <i>ou</i> sans noyau, stérile, ARSTT. (ATH. <i>652</i> a) ;<br><b>      2</b> <i>nom de la salade, chez les Pythagoriciens,</i> ATH. <i>69</i> e ;<br><b>   III</b> <i>adj</i>. εὐνοῦχα ὄμματα, SOPH. <i>fr. 880,</i> yeux privés de sommeil.<br><span><b>Étym</b>. εὐνή, ἔχω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευνουχος - εὐνοῦχος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 6 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Actes (5)</li>\n</ul>\n</td></tr>\n</table>","G2136":"<h1>Euodia</h1>\n<p>Strong n° 2136 <i>Prononciation [yoo-od-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Evodie (Angl. Euodias) = « parfumé »\n<ol><li>une femme Chrétienne à Philippes</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐοδία, ας (ἡ)</b> bonne route, bon voyage, ESCHL. <i>fr. 34, cité dans</i> AR. <i>Ran. 1528</i>.<br><span><b>Étym</b>. εὔοδος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ευοδια - Εὐοδία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2137":"<h1>euodoo</h1>\n<p>Strong n° 2137 <i>Prononciation [yoo-od-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>concevoir un voyage prospère et diligent, mener par une voie directe et facile</li>\n<li>accorder un succès, faire prospérer, d'où réussir</li>\n<li>prospérer, être heureux</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐοδόω-ῶ</b> <span>(<i>ao</i>. εὐώδωσα)</span><br><b>   I <i>tr.</i></b> accorder un heureux voyage, conduire heureusement, <i>acc</i>. SPT. <i>3Reg. 22, 12 ; en gén</i>. diriger heureusement ; <i>acc</i>. SPT. <i>Sap. 11, 1 ; d’où au pass</i>. faire un heureux voyage, NT. <i>Rom. 1, 10 ; p. anal. en parl. d’événements,</i> avoir une heureuse issue, HDT. <i>6, 73 ; d’où</i> réaliser un gain, amasser des ressources, NT. <i>1Cor. 16, 2 ; cf</i>. NT. <i>Ap. 11, 29 ;</i><br><b>   II</b> <i>intr. c. au pass</i>. PHIL. <i>1, 514</i>.<br><span><b>Étym</b>. εὔοδος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευοδοω - εὐοδόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>3 Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G2138":"<h1>eupeithes</h1>\n<p>Strong n° 2138 <i>Prononciation [yoo-pi-thace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>obéissant facilement, complaisant, accommodant, docile</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐ·πειθής, ής, ές :<br>      1</b> <i>pass</i>. qui se laisse facilement persuader, docile, obéissant : τινι, ESCHL. <i>Eum. 829 ;</i> XÉN. <i>Mem. 3, 4, 8 ;</i> PLAT. <i>Phædr. 254</i> a, à qqn ; τοῖς νόμοις, PLAT. <i>Leg. 715</i> e ; τῶν νόμων, PLAT. <i>Leg. 632</i> b, aux lois ; <i>avec une prép</i>. πρός τι, PLAT. <i>Leg. 718</i> c ; εἴς τι, PLAT. <i>Phædr. 271</i> d, qui se laisse amener à qqe ch., docile à qqe ch. ; <i>en parl. d’un État,</i> XÉN. <i>Vect. 4, 51 ; d’animaux,</i> XÉN. <i>Mem. 4, 2, 23 ; Conv. 2, 10, etc. ; en parl. de choses,</i> souple (voix) ARSTT. <i>Aud. 29,</i> facile à travailler (bois) GAL. <i>6, 41 ;</i> facile à digérer (nourriture) PLUT. <i>M. 669 ;</i><br><b>      2</b> <i>act</i>. qui persuade facilement, persuasif, ESCHL. <i>Ag. 274, Ch. 259, Suppl. 623 ;</i> EUR. <i>Andr. 819 ;</i> OPP. <i>C. 1, 313</i>.<br><span>•<i> Cp</i>. -έστερος, EUR. <i>l. c. ;</i> XÉN. <i>Vect. 4, 51</i>. <i>• Sup</i>. -έστατος, PLAT. <i>Leg. 715</i> c, <i>718</i> c.<br><span><b>Étym</b>. εὖ, πείθω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευπειθης - εὐπειθής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2139":"<h1>euperistatos</h1>\n<p>Strong n° 2139 <i>Prononciation [yoo-per-is'-tat-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>entourer avec habileté c.à.d assiéger</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐ·περίστατος, ος, ον</b> <span>[ᾰ]</span> qui circonvient facilement, NT. <i>Hebr. 12, 1</i>.<br><span><b>Étym</b>. εὖ, περιΐστημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευπεριστατος - εὐπερίστατος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2140":"<h1>eupoiia</h1>\n<p>Strong n° 2140 <i>Prononciation [yoo-poy-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>bonnes œuvres, bienfaisance</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐποιΐα, ας (ἡ) :<br>      1</b> bienfaisance, LUC. <i>Im. 21 ;</i> DL. <i>10, 10 ;</i><br><b>      2</b> <i>au pl</i>. bienfaits, HIÉROCL. (STOB. <i>Fl. 84, 20, t. 3, p. 127, l. 6</i>).<br><span><b>Étym</b>. εὐποιός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευποιια - εὐποιΐα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2141":"<h1>euporeo</h1>\n<p>Strong n° 02141 <i>Prononciation [yoo-por-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être bien fourni, avoir les moyens</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐπορέω-ῶ</b> <span>(<i>f</i>. -ήσω, <i>ao</i>. εὐπόρησα, <i>pf</i>. εὐπόρηκα)</span><br><b>   I <i>intr.</i></b> avoir le passage facile, <i>d’où :</i><br><b>      1</b> n’avoir aucun embarras, être dans l’abondance, abonder en ressources, abonder : σίτων, XÉN. <i>Hell. 1, 6, 19,</i> en provisions de bouche ; χρημάτων, LYC. <i>154, 15,</i> en ressources d’argent ; εὐπορῶ ὅ τι λέγω, PLAT. <i>Ion 532</i> c, j’ai beaucoup à dire ; εὐπ. ἔν τινι, ANT. <i>137, 12 ; rar</i>. τινι, POL. <i>1, 17, 2,</i> avoir abondamment de qqe ch. ;<br><b>      2</b> <i>p. suite,</i> avoir le moyen de, être en état de, pouvoir, <i>abs</i>. THC. <i>6, 34 ;</i> PLAT. <i>Leg. 791</i> d ; οὐκ εὐπ. ὅπῃ, PLAT. <i>Conv. 219</i> e, ne pas savoir comment (faire) ; <i>avec l’inf</i>. PLAT. <i>Phædr. 235</i> a, <i>Leg. 754</i> a ; ARSTT. <i>Top. 1, 5, 3 ;</i><br><b>      3</b> <i>avec un gén</i>. parvenir à, atteindre, obtenir, acquérir : ἵππων, XÉN. <i>Hell. 1, 1, 10,</i> se procurer des chevaux ; τῆς ἀληθείας, ARSTT. <i>Metaph. 2, 1, fin,</i> parvenir à la vérité ; <i>abs</i>. prospérer, réussir, XÉN. <i>Mem. 2, 7, 4 ;</i> PLAT. <i>Leg. 634</i> b ; ARSTT. <i>Pol. 3, 8, 7 ;</i><br><b>      4</b> <i>t. de phil</i>. n’avoir aucun doute, avoir la claire perception de qqe ch., <i>p. opp. à</i> ἀπορέω, ARSTT. <i>Metaph. 2, 1, 2 ; avec</i> περί <i>et le gén</i>. ARSTT. <i>P.A. 1, 5, 2 ;</i><br><b>   II <i>tr.</i></b> procurer, fournir : ἀργύριον, IS. <i>64, 15,</i> de l’argent ; ἀποδείξεις, DS. <i>2, 31,</i> des preuves ; εὐπ. τί τινι, DÉM. <i>671, 13 ; 894, 19,</i> fournir qqe ch. à qqn ;<br><b><i>Moy.</i></b> être dans l’abondance, abonder en, <i>gén</i>. ARSTT. <i>Œc. 2, 2, 4 ; dat</i>. POL. <i>5, 43, 8 ; abs</i>. THPP. (ATH. <i>275</i> c).<br><span><b><span class=\"arrow\"></span></b> <i>Pf</i>. εὐπόρηκα, PLAT. <i>Hipp. ma. 297</i> e ; <i>mais</i> ηὐπόρηκα, PLUT. <i>M. 403</i> f.<br><span><b>Étym</b>. εὔπορος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευπορεω - εὐπορέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2142":"<h1>euporia</h1>\n<p>Strong n° 2142 <i>Prononciation [yoo-por-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>richesse, moyens, fortune</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐπορία, ας (ἡ) :<br>      1</b> facilité pour faire qqe ch., faculté de, <i>inf</i>. EMPÉD. <i>347 Mullach ;</i> THC. <i>4, 52 ; abs</i>. XÉN. <i>An. 7, 6, 37 ; d’où en gén</i>. facilité, aisance, commodité, THC. <i>3, 82 ;</i> PLAT. <i>Prot. 321</i> e ;<br><b>      2</b> <i>p. ext</i>. abondance : χρημάτων, XÉN. <i>Hell. 4, 8, 28 ;</i> ἀγαθῶν, ARSTT. <i>Metaph. 13, 4, 8,</i> de ressources en argent, de biens ; <i>abs</i>. abondance de ressources, XÉN. <i>Cyr. 3, 3, 7 ; p. opp. à</i> ἀπορία, ARSTT. <i>Pol. 3, 8, 4 ; au plur</i>. ISOCR. <i>Antid. 253 ;</i> DÉM. <i>59, 2 ;</i> ARSTT. <i>Pol. 4, 6, 5 ;</i><br><b>      3</b> <i>t. de phil</i>. vue claire et distincte de qqe ch., absence de doute, solution facile, <i>p. opp. à</i> ἀπορία, XÉN. <i>Œc. 9, 1 ;</i> PLAT. <i>Phil. 15</i> c ; ARSTT. <i>Metaph. 2, 1, 2</i>.<br><span><b>Étym</b>. εὔπορος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευπορια - εὐπορία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2143":"<h1>euprepeia</h1>\n<p>Strong n° 2143 <i>Prononciation [yoo-prep'-i-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>bonne apparence, bien formé, beauté, grâce, prestance</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐπρέπεια, ας (ἡ) :<br>      1</b> belle <i>ou</i> noble apparence, THC. <i>6, 31 ;</i> PLUT. <i>M. 752</i> a ; <i>p. opp. à</i> ἀπρέπεια, PLAT. <i>Phædr. 274</i> d, <i>etc. ;</i><br><b>      2</b> <i>particul</i>. caractère spécieux, convenance extérieure, vraisemblance, THC. <i>3, 11 et 82 ;</i> PLAT. <i>Euthyd. 305</i> e.<br><span><b>Étym</b>. εὐπρεπής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευπρεπεια - εὐπρέπεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2144":"<h1>euprosdektos</h1>\n<p>Strong n° 2144 <i>Prononciation [yoo-pros'-dek-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>bien reçu, accepté, acceptable, facile à admettre, convenable bien accueilli</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐ·πρόσδεκτος, ος, ον</b>, facile à admettre, acceptable, PLUT. <i>M. 801</i> c ; NT. <i>Rom. 15, 16, 31, etc</i>.<br><span><b>Étym</b>. εὖ, προσδέχομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευπροσδεκτος - εὐπρόσδεκτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (2)</li>\n<li>2 Corinthiens (2)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2145":"<h1>euprosedros</h1>\n<p>Strong n° 2145 <i>Prononciation [yoo-pros'-ed-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce à quoi vous pouvez vous attendre, tenu constamment par, dévoué</li>\n<li>persévérant, ferme</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐ·πρόσεδρος, ος, ον</b>, assidu, CHRYS. <i>4, 300</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευπροσεδρος - εὐπρόσεδρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2146":"<h1>euprosopeo</h1>\n<p>Strong n° 2146 <i>Prononciation [yoo-pros-o-peh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se montrer d'une bonne manière, se faire bien voir, faire bonne figure</li>\n<li>plaire à, contenter</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐπροσωπέω-ῶ</b>, avoir un aspect agréable, <i>d’où</i> plaire, NT. <i>Gal. 6, 12</i>.<br><span><b>Étym</b>. εὐπρόσωπος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευπροσωπεω - εὐπροσωπέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G2147":"<h1>heurisko</h1>\n<p>Strong n° 2147 <i>Prononciation [hyoo-ris'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>venir sur, frapper sur, se rencontrer avec\n<ol type=\"a\">\n<li>après recherche, trouver une chose</li>\n<li>sans recherche préalable, trouver par chance</li>\n<li>ceux qui vont ou viennent d'un endroit</li>\n</ol>\n</li>\n<li>trouver par enquête, examen, recherche, observation, par la pratique et l'expérience\n<ol type=\"a\">\n<li>voir, apprendre, découvrir, comprendre</li>\n<li>être trouvé c.à.d être vu, être présent</li>\n<li>être découvert, reconnu, se montrer, montrer son caractère aux autres (aux hommes, à Dieu)</li>\n<li>prendre connaissance de, venir à connaître, venir à Dieu</li>\n</ol>\n</li>\n<li>trouver pour soi-même, acquérir, obtenir, se procurer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὑρίσκω</b> <span>(<i>impf</i>. ηὕρισκον, <i>f</i>. εὑρήσω, <i>ao.2</i> ηὗρον, <i>pf</i>. ηὕρηκα ; <i>pass. f</i>. εὑρεθήσομαι, <i>ao</i>. ηὑρέθην, <i>pf</i>. ηὕρημαι)</span> trouver, <i>càd. :</i><br><b>   I</b> rencontrer, trouver par hasard : εὐρ. χρυσοῦν δακτύλιον, LUC. <i>Demon. 17,</i> trouver un anneau d’or ;<br><b>   II</b> trouver en cherchant, <i>d’où :</i><br><b>      1</b> découvrir : τέκμωρ, OD. <i>4, 374,</i> une preuve ; πημάτων ἄρηξιν, SOPH. <i>El. 875,</i> un allégement à la douleur ; τινά, PLAT. <i>Tim. 28</i> c ; AR. <i>Pl. 104,</i> trouver, rencontrer, découvrir qqn (en cherchant) ; εὗρεν Κρονίδην ἄτερ ἥμενον ἄλλων, IL. <i>1, 498, etc</i>. elle trouva le fils de Kronos assis à l’écart loin des autres ;<br><b>      2</b> imaginer, inventer : ὀχήματα, ESCHL. <i>Pr. 468,</i> des voitures ; πρόφασιν, ANT. <i>137, 9,</i> un prétexte ; <i>cf</i>. ESCHL. <i>Pr. 59, Eum. 82 ;</i><br><b>      3</b> trouver après réflexion, reconnaître après examen, <i>avec un part. :</i> ἢν εὑρεθῇς μὴ δίκαιος ὤν, SOPH. <i>Tr. 411,</i> s’il est reconnu que tu n’as pas été juste ; <i>ou sans part. :</i> ἄνους ηὑρέθη, SOPH. <i>Aj. 763,</i> on a reconnu qu’il avait perdu la raison ; <i>avec une prop. inf</i>. HDT. <i>1, 79 ;</i> PLAT. <i>Leg. 699</i> b ; <i>avec</i> ὅπως, THC. <i>7, 67 ; ou</i> ὥστε, AR. <i>Pl. 492,</i> reconnaître que, juger que ; <i>impers</i>. εὑρέθη ὅτι, SPT. <i>1Esdr. 2, 22,</i> il a été trouvé <i>ou</i> reconnu que, <i>etc. ;</i><br><b>      4</b> trouver, rencontrer, obtenir, <i>en b. et en mauv. part :</i> εὑρ. δόξαν, PD. <i>P. 2, 64,</i> trouver <i>ou</i> obtenir de la gloire ; εὑρ. φίλους, SOPH. <i>fr. 109,</i> gagner des amis ; δεινὰ πρὸς αὐθαίμων πάθη, SOPH. <i>O.C. 1078,</i> recevoir un traitement cruel de ceux qui (nous) sont liés par le sang ; εὑρ. τινί τι, PLAT. <i>Prot. 321</i> d, obtenir qqe ch. pour qqn ; <i>particul. en parl. de ventes :</i> εὑρεῖν πολλὸν χρυσίον, HDT. <i>1, 196,</i> trouver un bon prix, <i>litt</i>. une grosse somme d’or (d’un objet qu’on vend) ; <i>cf</i>. XÉN. <i>Hell. 3, 4, 24 ; avec un suj. de chose :</i> οἰκία εὑρίσκουσα δισχιλίας (<i>s.-e</i>. δραχμάς) IS. <i>72, 39,</i> maison pour laquelle on trouve (<i>litt</i>. qui trouve) un prix de 2 000 drachmes ; ἀποδίδοσθαι τοῦ εὑρόντος, XÉN. <i>Mem. 2, 2, 5 ; ou</i> τοῦ εὑρίσκοντος, ESCHN. <i>13, 41,</i> vendre pour le prix qu’on trouve, à tout prix ;<br><b><i>Moy.</i></b> <span>(<i>f</i>. εὑρήσομαι, <i>ao.2</i> ηὑρόμην, <i>postér. ao.1</i> εὑράμην <i>ou</i> ηὑράμην, <i>pf</i>. ηὕρημαι)</span><br><b>      1</b> trouver, rencontrer : τὰ δ' ἔργα τοὺς λόγους εὑρίσκεται, SOPH. <i>El. 625, litt</i>. tes actions rencontrent mes paroles, <i>càd</i>. ta conduite (envers moi) provoque mes paroles, explique mon langage ;<br><b>      2</b> trouver, découvrir : τέκμωρ, IL. <i>16, 472,</i> une preuve ; τιν' ἑταίροισιν θανάτου λύσιν, OD. <i>9, 421,</i> un moyen de sauver de la mort ses compagnons ;<br><b>      3</b> se procurer à soi-même : κακόν, OD. <i>21, 304,</i> être cause pour soi-même d’un mal ; κλέος, PD. <i>P. 3, 114 ;</i> τιμάν, PD. <i>P. 1, 48,</i> obtenir de la gloire, un honneur ; ὠφέλειαν ἀπό τινος, THC. <i>1, 31 ;</i> τι παρά τινος, LYS. <i>130, 31,</i> obtenir assistance, qqe ch. de qqn ; εὑρ. παρά τινος <i>avec un inf</i>. HDT. <i>9, 28,</i> obtenir de qqn que, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. impf</i>. ηὕρισκον. PLAT. <i>Gorg. 514 ;</i> AR. <i>Ran. 806. Ao.1</i> εὕρησα, MAN. <i>5, 137. Ao.2 sbj. 3 sg</i>. εὕρῃσι, IL. <i>12, 302 ; inf. épq</i>. εὑρέμεναι, IL. <i>2, 343 ; éol</i>. εὕρην, SAPPH. <i>56 Bgk. Pass. f. réc</i>. εὑρήθησομαι, PORPH. <i>Antr. nymph. 4. Moy. ao</i>. εὑράμην, HÉS. <i>fr. 77 Göttling ; part</i>. εὑραμένη, A. PL. <i>4, 181</i>.<br><span><b>Étym</b>. <i>Orig. inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευρισκω - εὑρίσκω</font>\n<br><br>forme prolongée du mot primaire 'heuro' (hyoo'-ro), qui est utilisé à tous les temps sauf le présent et l'imparfait</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n180 fois dans 168 versets de 16 livres bibliques (NT)\n<ul>\n<li>Matthieu (28)</li>\n<li>Marc (11)</li>\n<li>Luc (45)</li>\n<li>Jean (19)</li>\n<li>Actes (36)</li>\n<li>Romains (5)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (6)</li>\n<li>Galates (2)</li>\n<li>Philippiens (2)</li>\n<li>2 Timothée (2)</li>\n<li>Hébreux (4)</li>\n<li>1 Pierre (2)</li>\n<li>2 Pierre (1)</li>\n<li>2 Jean (1)</li>\n<li>Apocalypse (14)</li>\n</ul>\n</td></tr>\n</table>","G2148":"<h1>Eurokludon</h1>\n<p>Strong n° 2148 <i>Prononciation [yoo-rok-loo'-dohn]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Euraquilon (Angl. Euroclydon) = « vagues et vent d'est »\n<ol>\n<li>vent du sud-est soulevant de puissantes vagues</li>\n<li>un vent causant de grosses vagues</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Εὐρ·ακύλων</b>, <i>v</i>. Εὐροκλύδων.<br><br>\n<b>εὐρο·κλύδων, ωνος (ὁ)</b> vent d’orage du nord-est, NT. <i>Ap. 27, 14, dout</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Sel. d’autres,</i> εὐρυκλύδων, violent orage, <i>ou</i> Εὐρακύλων, l’Eurus-Aquilon.<br><span><b>Étym</b>. Εὖρος, κλύδων ; <i>ou</i> Εὖρος, Aquilo.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ευροκλυδων - Εὐρακύλων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2149":"<h1>euruchoros</h1>\n<p>Strong n° 2149 <i>Prononciation [yoo-roo'-kho-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>spacieux, large, vaste</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐρύ·χωρος, ος, ον</b> <span>[ῠ]</span> au vaste emplacement, vaste, spacieux, DS. <i>19, 84</i>.<br><span>•<i> Cp</i>. -ότερος, ARSTT. <iεὐρύωψ>H.A. 10, 5.<br><span><b>Étym</b>. εὐ. χώρα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευρυχωρος - εὐρύχωρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G2150":"<h1>eusebeia</h1>\n<p>Strong n° 2150 <i>Prononciation [yoo-seb'-i-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>révérence, respect</li>\n<li>piété envers Dieu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐσέϐεια, ας (ἡ) :<br>   I</b> piété :<br><b>      1</b> respect et amour des dieux, ESCHL. <i>Sept. 344 ;</i> SOPH. <i>El. 1097 ;</i> PLAT. <i>Conv. 193</i> d ; πρὸς εὐσέϐειαν, SOPH. <i>El. 464,</i> par piété, avec piété ;<br><b>      2</b> amour <i>ou</i> respect filial, PLAT. <i>Rsp. 617</i> c ; πρός τινα, DC. <i>48, 5,</i> à l’égard de qqn ;<br><b>   II</b> réputation de piété filiale, SOPH. <i>El. 968 ;</i> XÉN. <i>Cyn. 1, 15</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att. du 1<sup>er</sup> siècle av. J.C</i>. εὐσέϐηα, CIA. <i>3, 788, 4 ; 789, 4 ; 836, 3 ; v. Meisterh. p. 37, 20</i>.<br><span><b>Étym</b>. εὐσεϐής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευσεβεια - εὐσέβεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n15 fois dans 15 versets de 5 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Timothée (8)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>2 Pierre (4)</li>\n</li>\n</ul>\n</td></tr>\n</table>","G2151":"<h1>eusebeo</h1>\n<p>Strong n° 2151 <i>Prononciation [yoo-seb-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>agir pieusement ou d'une façon révérencieuse\n<ol type=\"a\">\n<li>envers Dieu, son pays, les magistrats, ses relations, et tous ceux à qui de la considération est due</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐσεϐέω-ῶ</b>, être pieux, montrer des sentiments de piété (religieuse, filiale, <i>etc</i>.) THGN. <i>145 ;</i> SOPH. <i>Aj. 1350, Ant. 924 ;</i> εἴς τινα, SOPH. <i>Ant. 731 ;</i> περί τινα, EUR. <i>Alc. 1148 ;</i> PLAT. <i>Conv. 193</i> a ; πρός τινα, ANTH. <i>10, 107 ; ou direct. avec l’acc</i>. τινα, ESCHL. <i>Ag. 338,</i> à l’égard de qqn (des dieux, <i>etc.) ; ou avec un art. neutre,</i> εὐσ. τὰ πρὸς θεούς, SOPH. <i>Ph. 1441 ;</i> τὰ περὶ θεούς, ISOCR. <i>26</i> b, professer des sentiments de piété envers les dieux ; <i>d’où au pass. avec un sujet de chose,</i> être accompli pieusement, PLAT. <i>Ax. 364</i> c ; <i>avec un suj. de pers</i>. recevoir des témoignages de piété : ὑπό τινος, ANT. <i>123, 42,</i> de qqn.<br><span><b>Étym</b>. εὐσεϐής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευσεβεω - εὐσεβέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2152":"<h1>eusebes</h1>\n<p>Strong n° 2152 <i>Prononciation [yoo-seb-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>pieux, respectueux, fidèle</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐ·σεϐής, ής, ές :<br>   I</b> pieux, qui marque des sentiments de piété (religieuse <i>ou</i> filiale, <i>etc</i>.) :<br><b>      1</b> <i>en parl. de pers</i>. HDT. <i>2, 141 ;</i> PD. <i>O. 3, 43 ;</i> SOPH. <i>El. 589 ;</i> PLAT. <i>Ax. 371</i> c, <i>etc. ;</i> εὐσεϐὴς χεῖρα, ESCHL. <i>Ch. 141,</i> dont la main est pieuse, <i>càd</i>. qui agit pieusement ; εὐσ. πρός τινα, ESCHL. <i>Suppl. 339 ; ou</i> ἔς τινα, EUR. <i>El. 253,</i> qui marque des sentiments de piété envers qqn ;<br><b>      2</b> <i>en parl. de choses (oracle, parole, etc</i>.) EUR. <i>El. 1272 ;</i> τὸ εὐσεϐές, SOPH. <i>O.C. 1125 ;</i> EUR. <i>Tr. 42 ;</i> ANT. <i>141, 2 et 29,</i> la piété ; τὰ ἐν ἀνθρώποις εὐσεϐῆ, PHILIPP. (DÉM. <i>280, 10</i>) ce que les hommes regardent comme des marques de piété ; εὐσεϐές (ἐστι) ANTH. <i>App. 51, 42 ; ou</i> ἐν εὐσεϐεῖ (ἐστι) EUR. <i>Hel. 1277,</i> c’est un acte pieux de ;<br><b>   II</b> <i>p. ext</i>. innocent, irréprochable, <i>en gén</i>. SOPH. <i>O.C. 287, El. 589</i>.<br><span>•<i> Cp</i>. -έστερος, ESCHL. <i>Ch. 140 ;</i> PLAT. <i>Ep. 311</i> b. <i>• Sup</i>. -έστατος, PD. <i>I. 7, 43</i>.<br><span><b>Étym</b>. εὖ, σέϐομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευσεβης - εὐσεβής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (3)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2153":"<h1>eusebos</h1>\n<p>Strong n° 2153 <i>Prononciation [yoo-seb-oce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>pieusement, avec piété</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐσεϐῶς</b>, <i>adv</i>., pieusement, avec des sentiments de piété (religieuse <i>ou</i> filiale, <i>etc</i>.) PD. <i>O. 6, 79 ;</i> SOPH. <i>O.R. 1431 ;</i> XÉN. <i>Mem. 1, 3, 1 ;</i> PLAT. <i>Leg. 821</i> d, <i>Ax. 372 ;</i> DÉM. <i>407, 8</i>.<br><span>•<i> Cp</i>. εὐσεϐέστερον, XÉN. <i>Mem. 4, 3, 16 ;</i> <i>• Sup</i>. -έστατα, ISOCR. <i>47</i> b.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. εὐσεϐέως, PD. <i>l. c</i>.<br><span><b>Étym</b>. εὐσεϐής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευσεβως - εὐσεβῶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G2154":"<h1>eusemos</h1>\n<p>Strong n° 2154 <i>Prononciation [yoo'-say-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>bien marqué, clair et défini, distinct, facile à comprendre intelligible</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὔ·σημος, ος, ον :<br>      1</b> qui est bon signe, de bon augure, EUR. <i>I.A. 252 ; cf</i>. PLUT. <i>Cæs. 43 ;</i><br><b>      2</b> qui offre un signe certain, évident, clair, significatif, HPC. <i>Mochl. 851 ;</i> ESCHL. <i>Suppl. 714 ;</i> TH. <i>C.P. 6, 19, 5 ;</i> POL. <i>10, 44, 3 ;</i> PLUT. <i>M. 719</i> b, <i>etc. ; avec un part</i>. καπνῷ δ' ἁλοῦσα εὔσημος πόλις, ESCHL. <i>Ag. 818,</i> la fumée est un signe certain que la ville est prise ;<br><b>      3</b> <i>p. suite,</i> facile à reconnaître, distinct (cri) SOPH. <i>Ant. 1021 ; p. opp. à</i> ἄσημος, SOPH. <i>Ant. 1004</i>.<br><span>•<i> Cp</i>. -ότερος, TH. <i>C.P. 6, 19, 5 ;</i> <i>• Sup</i>. -ότατος, ARSTT. <i>Probl. 15, 12</i>.<br><span><b>Étym</b>. εὖ, σῆμα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευσημος - εὔσημος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2155":"<h1>eusplagchnos</h1>\n<p>Strong n° 2155 <i>Prononciation [yoo'-splangkh-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ayant de fortes entrailles</li>\n<li>compatissant, le cœur tendre, miséricordieux</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὔ·σπλαγχνος, ος, ον :<br>      1</b> qui a les entrailles saines, HPC. <i>89</i> c ;<br><b>      2</b> miséricordieux, NT. <i>Eph. 4, 32 ; 1Petr. 3, 8</i>.<br><span><b>Étym</b>. εὖ, σπλάγχνον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευσπλαγχνος - εὔσπλαγχνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2156":"<h1>euschemonos</h1>\n<p>Strong n° 2156 <i>Prononciation [yoo-skhay-mon'-ose]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>d'une manière bienséante, décemment, avec bonne tenue, convenablement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐσχημόνως</b>, <i>adv</i>., avec une bonne tenue, <i>particul</i>. avec un extérieur décent <i>ou</i> un maintien grave, XÉN. <i>Cyr. 1, 3, 8 ;</i> AR. <i>Vesp. 1210 ;</i> ARSTT. <i>Nic. 1, 10, 13</i>.<br><span>•<i> Cp</i>. -ονέστερον, PLAT. <i>Epin. 981</i> a ; DÉM. <i>1400, 10</i>.<br><span><b>Étym</b>. εὐσχήμων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευσχημονως - εὐσχημόνως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G2157":"<h1>euschemosune</h1>\n<p>Strong n° 2157 <i>Prononciation [yoo-skhay-mos-oo'-nay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>charme ou élégance d'un visage, beauté externe, le décorum, la modestie, bienséance, bonne tenue\n<ol type=\"a\">\n<li>le charme externe, beauté, grâce</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐσχημοσύνη, ης (ἡ)</b> extérieur décent, maintien grave, bonne tenue, XÉN. <i>Cyr. 5, 1, 5 ;</i> PLAT. <i>Conv. 196</i> a, <i>Rsp. 588</i> a, <i>Leg. 627</i> d ; POL. <i>10, 18, 7</i>.<br><span><b>Étym</b>. εὐσχήμων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευσχημοσυνη - εὐσχημοσύνη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2158":"<h1>euschemon</h1>\n<p>Strong n° 2158 <i>Prononciation [yoo-skhay'-mone]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>d'un beau visage\n<ol type=\"a\">\n<li>de forme élégante, gracieux, avenant</li>\n</ol>\n</li>\n<li>d'une bonne tenue\n<ol type=\"a\">\n<li>honorable, influent, riche, respectable, considéré, en vue</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐ·σχήμων, ων, ον :<br>      1</b> qui a bonne tenue, de bonne apparence, convenable, <i>en parl. de pers</i>. PLUT. <i>M. 309</i> c, <i>312</i> f, <i>etc. ; d’animaux,</i> XÉN. <i>Eq. 1, 17 ; de choses (discours, parole, etc</i>. EUR. <i>Hipp. 490 ;</i> PLAT. <i>Ep. 329</i> a ; DÉM. <i>1391, 16 ;</i> ARSTT. <i>Nic. 4, 14, etc. ; prétexte,</i> PLUT. <i>Thes. c. Rom. 5) ; en mauv. part,</i> qui montre un bon vouloir <i>ou</i> un empressement affecté : εἴς τινα, EUR. <i>Med. 584,</i> pour qqn ; πρᾶγμα οὐδαμῶς εὐσχ. λέγειν, ESCHN. <i>76, 39,</i> affaire qu’il ne serait nullement convenable de rapporter ; τὸ εὐσχ. PLAT. <i>Rsp. 401</i> c, <i>Leg. 797</i> b, <i>etc</i>. convenance (<i>lat</i>. decorum) ;<br><b>      2</b> d’un rang distingué, noble, honorable, NT. <i>Ap. 17, 2</i>.<br><span>•<i> Cp</i>. -ονέστερος, PLAT. <i>Rsp. 554</i> e. <i>• Sup</i>. -ονέστατος, XÉN. <i>Eq. 11, 12 ;</i> PLAT. <i>Ep. 361</i> b.<br><span><b>Étym</b>. εὖ, σχῆμα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευσχημως - εὐσχήμων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Actes (2)</li>\n<li>1 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G2159":"<h1>eutonos</h1>\n<p>Strong n° 2159 <i>Prononciation [yoo-ton'-oce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>avec véhémence, énergiquement, vigoureusement, avec énergie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐτόνως</b>, <i>adv</i>., avec tension, avec effort, avec vigueur, AR. <i>Pl. 1095 ;</i> XÉN. <i>Hier. 9, 6 ;</i> ARSTT. <i>Probl. 5, 39, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευτονως - εὐτόνως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2160":"<h1>eutrapelia</h1>\n<p>Strong n° 2160 <i>Prononciation [yoo-trap-el-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>plaisanterie, humour, facétie</li>\n<li>dans un mauvais sens\n<ol type=\"a\">\n<li>grossièreté, obscénité, basse plaisanterie, jeu de mots grossier, raillerie</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐτραπελία, ας (ἡ)</b> <span>[ᾰπ]</span> disposition à plaisanter agréablement, plaisanterie aimable et spirituelle, enjouement, HPC. <i>24, 3 ;</i> PLAT. <i>Rsp. 563</i> a ; DS. <i>15, 6 ;</i> PLUT. <i>Ant. 43 ; définie par</i> ARSTT. <i>Rhet. 2, 12, 16</i> πεπαιδευμένη ὕϐρις ; <i>p. opp. à</i> ἀγροικία <i>et</i> βωμολοχία, ARSTT. <i>Nic. 2, 7 ; rar. en mauv. part,</i> plaisanterie grossière, bouffonnerie, NT. <i>Eph. 5, 4</i>.<br><span><b>Étym</b>. εὐτράπελος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευτραπελια - εὐτραπελία</font></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2161":"<h1>Eutuchos</h1>\n<p>Strong n° 2161 <i>Prononciation [yoo'-too-khos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Eutychus = « heureux, fortuné »\n<ol><li>jeune homme ressuscité par Paul</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Εὔ·τυχος, ου (ὁ)</b> <span>[ῠ]</span> Eutykhos, <i>h</i>. ANTH. <i>11, 215 ; App. 221</i>.<br><span><b>Étym</b>. <i>cf</i>. εὐτυχής.</span> (ci-dessous)<br><br>\n<b>εὐ·τυχής, ής, ές</b> <span>[ῠ]</span><br><b>      1</b> <i>pass</i>. heureux, qui prospère, qui réussit, <i>différ. de</i> ὄλϐιος (heureux par la richesse) HDT. <i>1, 32 ; de</i> εὐδαίμων EUR. <i>Med. 1229 ; avec un inf</i>. εὐ. στρατηγεῖν, PLUT. <i>Ant. 34,</i> général heureux ; <i>en parl. d’événements, de choses, en gén. (sort,</i> ESCHL. <i>Pers. 709 ; action,</i> SOPH. <i>Tr. 293, etc</i>.) ; τὸ εὐτυχές, THC. <i>2, 44, c</i>. εὐτυχία ;<br><b>      2</b> <i>act</i>. qui assure le bonheur de : εὐ. ἵκοιτο, SOPH. <i>O.C. 308,</i> qu’il vienne pour le bonheur de, <i>etc</i>.<br><span>•<i> Cp</i>. -έστερος, SOPH. <i>Aj. 550 ;</i> EUR. <i>Med. 1229, Ph. 1582, Andr. 1186</i>. <i>• Sup</i>. -έστατος, EUR. <i>Ph. 1478 ;</i> PLAT. <i>Leg. 887</i> e.<br><span><b>Étym</b>. εὖ, τυχ- <i>de</i> τυγχάνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ευτυχος - Εὔτυχος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2162":"<h1>euphemia</h1>\n<p>Strong n° 2162 <i>Prononciation [yoo-fay-mee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>bonne réputation, louange</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐφημία, ας (ἡ) :<br>   I</b> parole de bon augure, <i>p. opp. à</i> δυσφημία ; <i>p. suite :</i><br><b>      1</b> action d’éviter des paroles de mauvais augure, <i>d’où</i> silence religieux, SOPH. <i>Tr. 178 ; cf</i>. EUR. <i>I.A. 1564 ;</i> PLAT. <i>Leg. 949</i> b ; εὐφημία 'στω, AR. <i>Av. 959, Th. 295,</i> silence ! silence ! (<i>avant une prière</i>) ;<br><b>      2</b> euphémisme, <i>càd. emploi d’un mot favorable au lieu d’un mot de mauvais augure (p. ex</i>. Εὐμενίδες, Εὔξεινος, <i>etc</i>.) : δι' εὐφημίαν, PLAT. <i>Leg. 736</i> a ; εὐφημίας ἕνεκα, ESCHN. <i>66 fin,</i> par euphémisme ;<br><b>   II</b> parole bienveillante, <i>d’où :</i><br><b>      1</b> bienveillance de langage, PLAT. <i>Leg. 717</i> c ; ESCHN. <i>24, 13 ;</i> DÉM. <i>14, 72, 5 ;</i><br><b>      2</b> louange, acclamation, parole d’éloge, PLAT. <i>2 Alc. 149</i> b, <i>etc. ; au pl</i>. chants en l’honneur de qqn, PD. <i>P. 10, 35 ;</i><br><b>   III</b> bonne expression, D. PHAL. <i>175</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. εὐφαμία <span>[φᾱ]</span> PD. <i>l. c</i>.<br><span><b>Étym</b>. εὔφημος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευφημια - εὐφημία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2163":"<h1>euphemos</h1>\n<p>Strong n° 2163 <i>Prononciation [yoo'-fay-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>qui sonne bien, qui est bon à dire</li>\n<li>paroles de bon présage, parler de bon augure</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὔ·φημος, ος, ον :<br>   I</b> au sens religieux :<br><b>      1</b> qui prononce des paroles <i>ou</i> pousse des cris de bon augure (<i>p. opp. à</i> δύσφημος) <i>en parl. de l’aigle,</i> ARSTT. <i>H.A. 9, 32, 3 ;</i><br><b>      2</b> <i>d’ord</i>. qui évite les paroles de mauvais augure, <i>d’où</i> qui garde un silence religieux, <i>dans les Trag</i>. SOPH. <i>O.C. 132 ;</i> εὔφημα φώνει, SOPH. <i>Aj. 362, 591 ;</i> EUR. <i>I.T. 687 ; ou</i> εὔφημος ἴσθι, SOPH. <i>fr. 426,</i> garde un religieux silence ; <i>p. ext</i>. saint, sacré (maison, chant, <i>etc</i>.) EUR. <i>Andr. 1144 ;</i> PLAT. <i>Leg. 801</i> a ;<br><b>      3</b> qui emploie un mot favorable au lieu d’un mot de mauvais augure ; <i>p. suite,</i> qui parle par euphémisme, PLAT. <i>2 Alc. 140</i> c ;<br><b>   II</b> <i>en gén. :</i><br><b>      1</b> qui prononce une parole favorable <i>ou</i> bienveillante, ESCHL. <i>Ch. 581 ; en parl. de paroles, de bruits,</i> favorable, ESCHL. <i>Suppl. 512 ;</i> EUR. <i>Tr. 1072 ; d’où, en gén</i>. favorable, propice εὔφ. ἦμαρ, ESCHL. <i>Ag. 636,</i> jour heureux ; πρὸς τὸ εὐφημότατον ἐξηγεῖσθαι, LUC. <i>Prom. 3,</i> interpréter dans le sens le plus favorable ;<br><b>      2</b> qui loue, qui célèbre, POL. <i>31, 14, 4</i>.<br><span>•<i> Sup</i>. -ότατος, PLAT. <i>2 Alc. 140</i> c ; LUC. <i>l. c</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. εὔφαμος <span>[ᾱ]</span> PD. <i>P. 4, 22, etc</i>.<br><span><b>Étym</b>. εὖ, φήμη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευφημος - εὔφημος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2164":"<h1>euphoreo</h1>\n<p>Strong n° 2164 <i>Prononciation [yoo-for-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être fertile, rapporter abondamment, fécond</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐφορέω-ῶ :<br>      1</b> porter heureusement, conduire à bon port, LUC. <i>Lex. 15 ;</i><br><b>      2</b> porter de bons fruits <i>ou</i> des fruits abondants, HPC. <i>Ep. 1274, 20 ;</i> NT. <i>Luc. 12, 16</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. 3 sg</i>. εὐφόρησεν, NT. <i>l. c</i>.<br><span><b>Étym</b>. εὔφορος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευφορεω - εὐφορέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2165":"<h1>euphraino</h1>\n<p>Strong n° 2165 <i>Prononciation [yoo-frah'-ee-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>réjouir, rendre joyeux, causer de la joie\n<ol type=\"a\">\n<li>être heureux, être gai, se réjouir, éprouver de la joie</li>\n<li>se réjouir en, avoir ses délices en une chose</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐ·φραίνω</b> <span>(<i>impf</i>. εὔφραινον, <i>f</i>. εὐφρανῶ <span>[ᾰ]</span>, <i>ao</i>. ηὔφρανα, <i>pf. inus. ; f. pass</i>. εὐφρανθήσομαι, <i>ao</i>. εὐφράνθην)</span> réjouir, charmer : τινά, IL. <i>5, 688 ;</i> OD. <i>13, 44,</i> qqn ; τινὸς ἐϋφρ. νόημα, OD. <i>20, 82 ;</i> νόον, ESCHL. <i>Ch. 742,</i> l’esprit de qqn ; τινά τι, AGATHON (ATH. <i>211</i> e) ; XÉN. <i>Mem. 2, 4, 6 ;</i> τινὰ ἐπέεσσι, IL. <i>24, 102 ;</i> τινὰ δι' ἀρετήν, PLAT. <i>Menex. 237</i> a, qqn par qqe ch., par ses paroles, par son mérite ; <i>d’où, au pass</i>. être charmé : τινι, PD. <i>P. 9, 16 ;</i> PLAT. <i>Leg. 796</i> b ; ἐπί τινι, AR. <i>Ach. 5 ;</i> XÉN. <i>Hier. 1, 16 ;</i> διά τινος, XÉN. <i>Hier. 1, 8 ; ou</i> ἀπό τινος, XÉN. <i>Hier. 4, 6,</i> par qqe ch. ; <i>avec un part</i>. être charmé de faire qqe ch. PD. <i>O. 9, 94 ;</i> SOPH. <i>Aj. 280 ; cf</i>. EUR. <i>Med. 36</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. ind. 3 pl. dor</i>. εὐφραίνοισι, PD. <i>fr. 206. Fut. épq</i>. ἐϋφρανέω <span>[ᾰ]</span> IL. <i>7, 297. Ao. ion</i>. εὔφρηνα, IL. <i>24, 102 ;</i> THCR. <i>Idyl. 12, 8 ; sbj. 2 sg. épq</i>. ἐϋφρήνῃς, IL. <i>7, 295. — Moy. fut. au sens pass. 2 sg. ion</i>. εὐφρανέεαι, HDT. <i>4, 9</i>.<br><span><b>Étym</b>. εὖ, φρήν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευφραινω - εὐφραίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 14 versets de 6 livres bibliques (NT)\n<ul>\n<li>Luc (6)</li>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G2166":"<h1>Euphrates</h1>\n<p>Strong n° 2166 <i>Prononciation [yoo-frat'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Euphrate (Angl. Euphrates) = « le fleuve bon et abondant »\n<ol>\n<li>un grand et fameux fleuve qui vient des montagnes d'Arménie, coule à travers l'Assyrie, la Syrie, la Mésopotamie et la ville de Babylone, puis se jette dans le golfe Persique</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Εὐφράτης, ου (ὁ)</b> <span>[ᾱ]</span><br><b>      1</b> l’Euphrate (<i>auj</i>. al-Furāt, Evfrátis) <i>fl. de Mésopotamie,</i> ARSTT. <i>Mir. 150 ;</i> TH. <i>H.P. 4, 8, 10 ;</i><br><b>      2</b> Euphratès, <i>h</i>. ANTH. <i>7, 162</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. Εὐφρήτης, HDT. <i>1, 180 ;</i> ANTH. <i>9, 297 ;</i> OPP. <i>C. 1, 276 ;</i> NONN. <i>D. 23, 82 ; gén. épq</i>. -αο <span>[ᾱ]</span> NONN. <i>D. 40, 392 ; ion</i>. -εω, HDT. <i>1, 191</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ευφρατης - Εὐφράτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G2167":"<h1>euphrosune</h1>\n<p>Strong n° 2167 <i>Prononciation [yoo-fros-oo'-nay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>bonne réjouissance, joie, gaieté</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐφροσύνη, ης (ἡ)</b> <span>[ῠ]</span><br><b>      1</b> joie, gaîté, plaisir, OD. <i>20, 8 ;</i> PD. <i>N. 4, 1 ; souv. au pl</i>. OD. <i>6, 156 ;</i> ESCHL. <i>Pr. 540 ;</i> XÉN. (<i>v. ci-dessous</i>) ;<br><b>      2</b> <i>particul</i>. joie dans un festin, bonne chère, OD. <i>9, 6, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Mot poét. ; en prose,</i> XÉN. <i>Cyr. 3, 3, 7 ;</i> PLAT. <i>Tim. 80</i> b ; <i>au pl</i>. XÉN. <i>Cyr. 8, 1, 32 ; Ages. 9, 4. Dor</i>. εὐφροσύνα, PD. <i>N. 4, 1 ; etc. ;</i> ANTH. <i>9, 375. Épq</i>. ἐϋφρ- OD. <i>ll. cc</i>.<br><span><b>Étym</b>. εὔφρων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευφροσυνη - εὐφροσύνη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G2168":"<h1>eucharisteo</h1>\n<p>Strong n° 2168 <i>Prononciation [yoo-khar-is-teh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être reconnaissant, ressentir de la reconnaissance</li>\n<li>rendre grâces, remercier, rendre grâce (avant le repas)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐχαριστέω-ῶ</b> <span>[ᾰ]</span><br><b>      1</b> être reconnaissant, DÉM. <i>257, 2 (décr</i>.) ; SPT. <i>Judith 8, 25 ; Sap. 18, 2 ;</i><br><b>      2</b> <i>p. suite,</i> rendre grâces, témoigner sa reconnaissance : τινι, POSIDON. (ATH. <i>213</i> e), à qqn ; ἐπί τινι, POL. <i>16, 25, 1,</i> au sujet de qqe ch. ; περί τινός τινι, DS. <i>16, 11,</i> témoigner sa reconnaissance de qqe ch. à qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Ao</i>. εὐχαρίστησα, POSIDON. <i>l. c</i>.<br><span><b>Étym</b>. εὐχάριστος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευχαριστεω - εὐχαριστέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n42 fois dans 38 versets de 15 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Luc (4)</li>\n<li>Jean (3)</li>\n<li>Actes (2)</li>\n<li>Romains (6)</li>\n<li>1 Corinthiens (8)</li>\n<li>2 Corinthiens (1)</li>\n<li>Ephésiens (3)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (3)</li>\n<li>1 Thessaloniciens (3)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>Philémon (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2169":"<h1>eucharistia</h1>\n<p>Strong n° 2169 <i>Prononciation [yoo-khar-is-tee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>reconnaissance</li>\n<li>action de grâces, remerciement</li>\n<li>la Sainte Cène est une action de grâce et de reconnaissance</li>\n<li>Le mot « eucharistie » n'est que la transcription littérale du mot grec ευχαριστια en français</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐχαριστία, ας (ἡ)</b> <span>[χᾰ]</span><br><b>   I</b> reconnaissance, HPC. <i>28, 11 ;</i> DÉM. <i>256, 19 (décr</i>.) ; POL. <i>8, 14, 8 ;</i><br><b>   II</b> <i>p. suite :</i><br><b>      1</b> action de grâces, DS. <i>17, 59 ;</i> SPT. <i>Sap. 16, 28 ;</i> NT. <i>1Cor. 14, 16, etc. ; Ap. 24, 3 ;</i><br><b>      2</b> <i>t. eccl</i>. le sacrifice de l’Eucharistie (<i>litt</i>. sacrifice d’actions de grâces) CLÉM. <i>1, 412</i> a, <i>1369</i> b ; BAS. <i>4, 188 edd. Migne ; p. ext. en parl. des espèces consacrées (pain</i> et <i>vin</i>) CLÉM. <i>1, 692 ;</i> BAS. <i>4, 188 ;</i> NAZ. <i>1, 809, 980 ;</i> NYSS. <i>1, 96, etc. ;</i> CHRYS. <i>1, 424, 583 edd. Migne</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. -ίη, HPC. <i>l. c</i>.<br><span><b>Étym</b>. εὐχάριστος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευχαριστια - εὐχαριστία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n15 fois dans 15 versets de 9 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (3)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (2)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>1 Timothée (3)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G2170":"<h1>eucharistos</h1>\n<p>Strong n° 2170 <i>Prononciation [yoo-khar'-is-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>attentif aux faveurs, reconnaissant</li>\n<li>plaisant, agréable</li>\n<li>acceptable pour les autres, libéral, bienfaisant</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐ·χάριστος, ος, ον</b> <span>[ᾰ]</span><br><b>   I</b> <i>pass</i>. agréable, <i>en parl. de pers</i>. XÉN. <i>Œc. 5, 10 ; en parl. de choses,</i> XÉN. <i>Cyr. 2, 2, 1 ;</i><br><b>   II</b> <i>act. :</i><br><b>      1</b> reconnaissant, HDT. <i>1, 90 ;</i> XÉN. <i>Cyr. 8, 3, 49 ;</i><br><b>      2</b> bienfaisant, DS. <i>18, 28</i>.<br><span>•<i> Cp</i>. -ότερος, XÉN. <i>Œc. 5, 10 ;</i> <i>• Sup</i>. -ότατος, XÉN. <i>Cyr. 8, 3, 49</i>.<br><span><b>Étym</b>. εὖ, χαρίζομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευχαριστος - εὐχάριστος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2171":"<h1>euche</h1>\n<p>Strong n° 2171 <i>Prononciation [yoo-khay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une prière à Dieu</li>\n<li>un vœu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐχή, ῆς (ἡ) :<br>   I</b> vœu, souhait :<br><b>      1</b> <i>en gén., une fois dans Hom. (d’ord</i>. εὖχος <i>et</i> εὐχωλή) OD. <i>10, 526 ;</i> HÉS. <i>Th. 419 ;</i> THGN. <i>341 ;</i> HDT. <i>1, 31 :</i> εὐχὰς εὔχεσθαι, PLAT. <i>Leg. 700</i> b, <i>ou</i> ποιήσασθαι, AR. <i>Eq. 661, etc</i>. former des vœux, adresser des prières ; εὐχὴν ἐπιτελέσαι, HDT. <i>1, 86, ou</i> ἀποδιδόναι, XÉN. <i>Mem. 2, 2, 10,</i> accomplir un vœu ; εὐχῇ χρῆσθαι, PLAT. <i>Leg. 688</i> b, obtenir l’objet de son vœu (<i>lat</i>. votis potiri) ; κατ' εὐχήν, CALL. <i>Ep. 50 ;</i> ἐξ εὐχῆς, ANTH. <i>6, 357,</i> par un vœu (<i>lat</i>. ex voto) ; εὐχῆς ἔργον, PLUT. <i>M. 14</i> c, chose digne d’être souhaitée ;<br><b>      2</b> <i>particul</i>. vœu <i>ou</i> souhait adressé à Dieu, prière à Dieu, SPT. <i>Prov. 15, 8 et 29, etc. ;</i><br><b>      3</b> <i>en mauv. part,</i> imprécation, ESCHL. <i>Sept. 819 ; cf</i>. EUR. <i>Ph. 70 ;</i><br><b>      4</b> serment, DC. ;<br><b>   II</b> <i>p. ext</i>. désir, <i>en gén., p. opp. à la réalité :</i> εὐχαῖς ὅμοια λέγειν, PLAT. <i>Rsp. 499</i> c, dire des choses sans consistance, <i>litt</i>. semblables à des désirs <i>ou</i> à des rêves sans réalité ; κατὰ τὴν παίδων εὐχήν, PLAT. <i>Soph. 249</i> b, comme un désir d’enfant ; κατ' εὐχήν, ARSTT. <i>Pol. 4, 11, 1,</i> comme on le désire.<br><span><b>Étym</b>. εὔχομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευχη - εὐχή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2172":"<h1>euchomai</h1>\n<p>Strong n° 2172 <i>Prononciation [yoo'-khom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prier Dieu</li>\n<li>désirer, prier, souhaiter</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὔχομαι</b> <span>(<i>impf</i>. ηὐχόμην <i>ou</i> εὐχόμην, <i>f</i>. εὔξομαι, <i>ao</i>. ηὐξάμην <i>ou</i> εὐξάμην, <i>pf</i>. ηὖγμαι, <i>pl.q.pf</i>. ηὔγμην <i>ou</i> εὔγμην)</span><br><b>   I</b> <i>dép</i>. former un vœu, un souhait, <i>d’où :</i><br><b>      1</b> adresser une prière, un vœu, <i>abs</i>. IL. <i>15, 371 ;</i> εὔχεσθαι τοῖς θεοῖς, THC. <i>3, 58 ;</i> SOPH. <i>Ph. 1077, etc. ;</i> εὔχεσθαι εὐχὴν <i>ou</i> εὐχὰς τοῖς θεοῖς, DÉM. <i>381, 10 ;</i> ESCHN. <i>4, 10,</i> adresser une prière <i>ou</i> des prières aux dieux ; εὐχὰς ὑπέρ τινος πρὸς τοὺς θεοὺς εὔχεσθαι, ESCHN. <i>56, 22,</i> adresser aux dieux des prières pour qqn ; εὔχεσθαι ἔπος, PD. <i>P. 3, 2 ;</i> ESCHL. <i>Suppl. 980,</i> exprimer un vœu ; εὔχεσθαι τοῖς θεοῖς τι ὑπέρ τινος, XÉN. <i>Mem. 2, 2, 10,</i> demander aux dieux qqe ch. pour qqn ; <i>avec une prop. inf</i>. OD. <i>15, 353 ; 21, 211 ;</i> HDT. <i>1, 31 ; ou avec une conj</i>. εὔ. ἵνα, DH. <i>3, 1888 Reiske ;</i> PHIL. <i>1, 296 ; 2, 454, etc. ;</i> ARR. <i>Epict. 2, 6, 12,</i> souhaiter, exprimer le vœu que, <i>etc. ; avec un inf. ao</i>. εὐχ. θάνατον φυγεῖν, IL. <i>2, 401,</i> souhaiter d’échapper à la mort ; <i>avec le rég. de la pers. que l’on prie :</i> εὐχ. τοὺς θεούς <i>avec l’inf</i>. XÉN. <i>An. 6, 1, 26 ; ou</i> εὔχ. πρὸς τοὺς θεούς <i>avec l’inf</i>. XÉN. <i>Mem. 1, 3, 2,</i> prier les dieux de, adresser une prière aux dieux pour que, <i>etc. ; avec le dat. de la pers. pour qui l’on forme un souhait :</i> τί τινι, IL. <i>7, 298 ;</i> SOPH. <i>Ph. 1019, etc</i>. souhaiter qqe ch. à qqn ; <i>us. qqf. en mauvaise part ;</i> κακόν τινι, LYS. <i>21, 21 Baiter-Sauppe ou</i> δεινὸν κατά τινος, LUC. <i>Abd. 32,</i> souhaiter du mal à qqn ;<br><b>      2</b> faire vœu de, promettre : τι, ESCHL. <i>Ag. 963 ;</i> AR. <i>Av. 1619,</i> qqe ch. ; τί τινι, SOPH. <i>O.C. 1512,</i> qqe ch. à qqn ; <i>qqf. avec</i> κατά : τοῖς θεοῖς κατά τινος (καθ' ἑκατόμϐης, PLUT. <i>Mar. 26, etc. ;</i> κατὰ νικητηρίων, DÉM. <i>Epist. 1</i>) faire vœu aux dieux de leur offrir qqe ch. (une hécatombe, un présent de victoire) ; <i>ou avec l’inf. (fut</i>. IL. <i>8, 526 ;</i> OD. <i>17, 50 ;</i> PLAT. <i>Phæd. 58</i> b ; CIA. <i>2, add. 57, b, 6, (362 av. J.C.) ; v. Meisterh. p. 200, 7 ; ao</i>. IL. <i>18, 499 ; rar. prés</i>. ESCHL. <i>Ag. 993 ;</i> SOPH. <i>Ph. 1033</i>) ;<br><b>      3</b> se flatter de, se glorifier de, SOPH. <i>Ph. 1032 ;</i> πατρὸς δ' ἐξ ἀγαθοῦ καὶ ἐγὼ γένος εὔχομαι εἶναι, IL. <i>14, 113,</i> je me flatte moi aussi, d’avoir pour père un homme de noble race ; <i>ou</i> sans <i>inf. :</i> ἐκ Κρητάων γένος εὔχομαι, OD. <i>14, 199,</i> je me flatte d’être originaire de Crète ; <i>abs</i>. se vanter, parler avec jactance, IL. <i>11, 388 ;</i><br><b>      4</b> <i>p. suite, simpl</i>. affirmer, déclarer, dire, <i>avec un inf</i>. OD. <i>5, 450 ;</i> PD. <i>O. 6, 53 ; avec un part</i>. SOPH. <i>O.C. 41 ;</i><br><b>   II</b> <i>pass</i>. être prié, <i>càd. :</i><br><b>      1</b> être demandé par une prière, PLAT. <i>Phædr. 279</i> c (<i>pf. 3 sg</i>. ηὖκται) ;<br><b>      2</b> être offert <i>ou</i> promis par un vœu, DC. <i>48, 32 (part. ao. fém</i>. εὐχθεῖσα).<br><span><b><span class=\"arrow\"></span></b> <i>Impf</i>. ηὐχόμην, ESCHL. <i>Pers. 498 ;</i> EUR. <i>Or. 355, etc. ;</i> XÉN. <i>Cyr. 3, 2, 15 ; An. 1, 4, 7, etc. ; ou</i> εὐχόμην, IL. <i>3, 275 ;</i> HDT. <i>7, 54, etc. ; ao</i>. ηὐξάμην, SOPH. <i>Ph. 1009, etc. ; poét</i>. εὐξάμην, IL. <i>8, 254 ; sbj. 2 sg. épq</i>. εὔξεαι, OD. <i>3, 45 ; opt. dor</i>. εὐξαίμαν, SOPH. <i>fr. 326 Nauck ; pl.q.pf</i>. ηὔγμην, SOPH. <i>Tr. 610</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *h₁ueg<sup>wh</sup>-, parler solennellement, <i>avec redoubl</i>. *h₁é-h₁ug<sup>wh</sup>-e-toi ; <i>cf. lat</i>. voveō.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευχομαι - εὔχομαι</font>\n<br><br>vient d'un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 5 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>Jacques (1)</li>\n<li>3 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G2173":"<h1>euchrestos</h1>\n<p>Strong n° 2173 <i>Prononciation [yoo'-khrays-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>facile à utiliser, utile</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὔ·χρηστος, ος, ον</b>, d’un bon usage, d’un usage facile <i>ou</i> commode : πρός τι, XÉN. <i>Mem. 3, 8, 5 ;</i> PLAT. <i>Leg. 777</i> b ; εἴς τι, DS. <i>5, 40,</i> pour qqe ch.<br><span>•<i> Cp</i>. -ότερος, XÉN. <i>Cyr. 5, 3, 39</i>. <i>• Sup</i>. -ότατος, XÉN. <i>Mem. 4, 1, 3 ;</i> ARSTT. <i>Pol. 7, 17</i>.<br><span><b>Étym</b>. εὖ, χράομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευχρηστος - εὔχρηστος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Timothée (2)</li>\n<li>Philémon (1)</li>\n</ul>\n</td></tr>\n</table>","G2174":"<h1>eupsucheo</h1>\n<p>Strong n° 2174 <i>Prononciation [yoo-psoo-kheh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être d'un grand courage, être d'un esprit réjoui</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐψυχέω-ῶ</b> <span>[ῡ]</span> avoir bon courage, NT. <i>Phil. 2, 19 ;</i> JOS. <i>A.J. 11, 6, 9 ;</i> εὐψύχει, ANTH. <i>App. 244,</i> bon courage ! repose en paix (have, pia anima) <i>formule d’épitaphe</i>.<br><span><b>Étym</b>. εὔψυχος¹.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευψυχεω - εὐψυχέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2175":"<h1>euodia</h1>\n<p>Strong n° 2175 <i>Prononciation [yoo-o-dee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une bonne odeur, un parfum</li>\n<li>un parfum ou une chose de bonne odeur, encens, odeur de quelque chose au doux parfum\n<ol type=\"a\">\n<li>une odeur d'obéissance, satisfaction</li>\n<li>bonne odeur, à propos de l'odeur des sacrifices et obligations anciennes qui étaient agréables à Dieu</li>\n</ol>\n</li>\n<li>métaph. une chose qui est plaisante à Dieu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐωδία, ας (ἡ) :<br>      1</b> bonne odeur, XÉN. <i>Conv. 2, 3 ;</i> PLUT. <i>M. 421</i> b ; <i>au pl</i>. PLAT. <i>Tim. 65</i> a ;<br><b>      2</b> parfum, DS. <i>1, 84 au plur</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. -ίη, HDT. <i>4, 75</i>.<br><span><b>Étym</b>. εὐωδής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευωδια - εὐωδία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2176":"<h1>euonumos</h1>\n<p>Strong n° 2176 <i>Prononciation [yoo-o'-noo-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>de bon nom et de bon présage\n<ol type=\"a\">\n<li>utilisé pour prendre des augures, et ces présages étaient par euphémisme appelés « euonumos » et en fait considérés comme malchanceux, c.à.d venant de la gauche, présage sinistre, et pour lequel un bon nom était désiré</li>\n</ol>\n</li>\n<li>gauche, du côté gauche, à main gauche</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐ·ώνυμος, ος, ον</b> <span>[ῠ]</span><br><b>   I</b> qui a un beau nom, <i>càd. :</i><br><b>      1</b> au nom respecté <i>ou</i> honoré, HÉS. <i>Th. 409 ; ou</i> glorieux, célèbre, PD. <i>O. 2, 8 ; N. 4, 19 ; 7, 85 ; 8, 47 ; P. 11, 58 ;</i><br><b>      2</b> qui a un nom de bon augure, <i>p. opp. à</i> δυσώνυμος, PLAT. <i>Leg. 754</i> e, <i>Pol. 302</i> d ; DC. <i>52, 4 ; d’où par antiphrase, pour</i> ἀριστερός <i>ou</i> σκαιός, placé à gauche, ESCHL. <i>Pr. 490 ;</i> SOPH. <i>Tr. 926 ;</i> XÉN. <i>Cyn. 10, 12 ;</i> PLAT. <i>Leg. 760</i> d, <i>etc. ;</i> ἐξ εὐωνύμου χειρός, HDT. <i>7, 109 ; ou simpl</i>. ἐξ εὐ. HDT. <i>1, 72,</i> à main gauche, à gauche ; κατὰ τὰ εὐ. XÉN. <i>Lac. 11, 10 ;</i> εἰς τὰ εὐ. ARSTT. <i>P.A. 3, 4, 19 ; ou</i> ἐπὶ τὰ εὐ. ARSTT. <i>H.A. 2, 1, 9,</i> vers la gauche, sur la gauche ; τὸ εὐώνυμον κέρας, HDT. <i>6, 111 ;</i> THC. <i>5, 67 ; ou simpl</i>. τὸ εὐώνυμον, THC. <i>3, 107 ; 4, 43, 96,</i> l’aile gauche ;<br><b>   II</b> rempli de beaux mots, LUC. <i>Lex. 1</i>.<br><span><b>Étym</b>. εὖ, ὄνομα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευωνυμος - εὐώνυμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (3)</li>\n<li>Actes (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2177":"<h1>ephallomai</h1>\n<p>Strong n° 2177 <i>Prononciation [ef-al'-lom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sauter sur, jaillir sur, s'élancer, se jeter</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐφ·άλλομαι</b> <span>(<i>f</i>. -αλοῦμαι ; <i>pour les formes ion. ou poét. v. ci-dessous</i>)</span><br><b>      1</b> sauter sur, s’élancer sur : ἵππων, IL. <i>7, 15,</i> sur son char ; τοῖς ἵπποις, PLUT. <i>M. 139</i> b, s’élancer à cheval ; ἐπὶ τὸν οὐδόν, PLAT. <i>Ion 535</i> b, sauter sur le seuil ; <i>particul</i>. se précipiter sur qqn, en signe de joie, OD. <i>24, 320 ;</i><br><b>      2</b> <i>avec idée d’hostilité :</i> τινι, IL. <i>11, 489 ; 21, 140, etc. ;</i> ἔς τινα, PD. <i>N. 6, 83,</i> s’élancer sur qqn.<br><span><b><span class=\"arrow\"></span></b> Dans HOM. <i>seul. ao.2 ion. 3 sg</i>. ἐπᾶλτο, IL. <i>21, 140 ; cf</i>. PD. <i>l. c. ; d’où part</i>. ἐπάλμενος, IL. <i>11, 421, 489 ; ou</i> ἐπιάλμενος, IL. <i>7, 15 ;</i> OD. <i>24, 320</i>.<br><span><b>Étym</b>. ἐπί, ἅλλομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εφαλλομαι - ἐφάλλομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2178":"<h1>ephapax</h1>\n<p>Strong n° 2178 <i>Prononciation [ef-ap'-ax]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tout de suite, à la fois\n<ol type=\"a\">\n<li>tout à la fois</li>\n<li>une fois pour toutes</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐφ·άπαξ</b>, <i>adv. :</i><br><b>      1</b> une fois pour toutes, EUP. <i>175 Kock ; 96, 17 Bekker, Anecdota græca, vol. 1 ;</i> NT. <i>Rom. 6, 10 ; Hebr. 7, 27 ;</i><br><b>      2</b> pour une fois, NT. <i>1Cor. 15, 6</i>.<br><span><b>Étym</b>. ἐπί, ἅπαξ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εφαπαξ - ἐφάπαξ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Hébreux (3)</li>\n</ul>\n</td></tr>\n</table>","G2179":"<h1>Ephesinos</h1>\n<p>Strong n° 2179 <i>Prononciation [ef-es-ee'-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un natif ou habitant d'Ephèse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>Ἐφέσιος, α, ον</b>, d’Éphèse. HDT. <i>1, 26, etc. ;</i> τὰ Ἐφέσια γράμματα, PLUT. <i>M. 706 d et e ;</i> M. ANT. <i>11, 26, etc</i>. lettres d’Éphèse, <i>sorte de formule magique</i>.<br><span><b>Étym</b>. Ἔφεσος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Εφεσινος - Ἐφεσῖνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2180":"<h1>Ephesios</h1>\n<p>Strong n° 2180 <i>Prononciation [ef-es'-ee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un natif ou habitant d'Ephèse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἐφέσιος, α, ον</b>, d’Éphèse. HDT. <i>1, 26, etc. ;</i> τὰ Ἐφέσια γράμματα, PLUT. <i>M. 706 d et e ;</i> M. ANT. <i>11, 26, etc</i>. lettres d’Éphèse, <i>sorte de formule magique</i>.<br><span><b>Étym</b>. Ἔφεσος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Εφεσιος - Ἐφέσιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (5)</li>\n</ul>\n</td></tr>\n</table>","G2181":"<h1>Ephesos</h1>\n<p>Strong n° 2181 <i>Prononciation [ef'-es-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Ephèse (Angl. Ephesus) = « permis »\n<ol><li>cité maritime d'Asie Mineure, capitale de Ionie, à l'embouchure du Caystre, à mi chemin entre Milet au sud et Smyrne au nord, sur l'artère principale allant de Rome à l'Orient Capitale de la province d'Asie, connue comme lieu de pèlerinage au temple d'Artémis</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἔφεσος, ου (ἡ)</b> Éphèse (<i>auj</i>. ruines près de Selçuk) <i>v. de Lydie,</i> HDT. <i>1, 92, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Εφεσος - Ἔφεσος</font>\n<br><br>probablement d'origine étrangère</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n15 fois dans 15 versets de 6 livres bibliques (NT)\n<ul>\n<li>Actes (8)</li>\n<li>1 Corinthiens (2)</li>\n<li>Ephésiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2182":"<h1>epheuretes</h1>\n<p>Strong n° 2182 <i>Prononciation [ef-yoo-ret'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un inventeur, qui imagine, qui trouve, découvre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐφευρέτης, ου (ὁ)</b> inventeur, ANACR. <i>41 ;</i> NT. <i>Rom. 1, 30</i>.<br><span><b>Étym</b>. ἐφευρίσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εφευρετης - ἐφευρετής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G2183":"<h1>ephemeria</h1>\n<p>Strong n° 2183 <i>Prononciation [ef-ay-mer-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un service limité à une série définie de jours</li>\n<li>la classe de sacrificateurs qui assurait pour une semaine les fonctions de sacrificateur. David avait divisé les sacrificateurs en vingt-quatre classes, chacune étant chargée des devoirs de la fonction pour une semaine entière, d'un sabbat à un autre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐφημερία, ας (ἡ) :<br>      1</b> service quotidien des prêtres dans le temple, <i>chez les Juifs,</i> SPT. <i>1Par. 9, 33 ; 2, 5, 11 ; etc. ; 1Esdr. 1, 2 ;</i><br><b>      2</b> ordre de succession des prêtres pour le service du temple pendant le jour, SPT. <i>1Par. 23, 6 ; Neh. 13, 30 ;</i> NT. <i>Luc. 1, 5 et 8 ;</i> JOS. <i>A.J. 12, 6, 1</i>.<br><span><b>Étym</b>. ἐφήμερος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εφημερια - ἐφημερία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G2184":"<h1>ephemeros</h1>\n<p>Strong n° 2184 <i>Prononciation [ef-ay'-mer-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>durant un jour</li>\n<li>quotidien</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐφ·ήμερος, ος, ον :<br>A <i>adj</i>.<br>   I</b> d’un jour, <i>càd. :</i><br><b>      1</b> qui dure un jour (fièvre) HPC. <i>Aph. 1251 ;</i><br><b>      2</b> qui agit le jour même (poison) PLUT. <i>Them. 31 ;</i><br><b>      3</b> qui ne dure qu’un jour, éphémère, <i>en parl. de choses (fortune,</i> EUR. <i>Her. 866 ; bonheur,</i> EUR. <i>Ph. 558 ; corps et biens,</i> THC. <i>2, 53, etc. ;</i> ARSTT. <i>Pol. 1, 2, 5</i>) ; <i>en parl. de pers</i>. PLAT. <i>Leg. 923</i> a ; ἐφήμεροι, créatures d’un jour, SIM. AM. <i>Iamb. fr. 1, 3 ;</i> ESCHL. <i>Pr. 83 ;</i> PD. <i>P. 8, 95 ;</i><br><b>   II</b> de chaque jour, quotidien, DH. <i>8, 41 ;</i> PLUT. <i>Per. 16 ;</i> LUC. <i>Pseud. 17 ;</i><br><b>B <i>subst.</i></b> τὸ ἐφ. éphémère (<i>p.-ê. ephemera longicauda</i> L.) <i>insecte,</i> ARSTT. <i>H.A. 1, 5, 16, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. ἐφάμερος <span>[ᾱ]</span> EUR. <i>Or. 976 ;</i> ANTH. <i>9, 571 ; éol</i>. ἐπάμερος <span>[ᾱ]</span> PD. <i>P. 8, 95 ; I. 6, 40</i>.<br><span><b>Étym</b>. ἐπί, ἡμέρα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εφημερος - ἐφήμερος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2185":"<h1>ephikneomai</h1>\n<p>Strong n° 2185 <i>Prononciation [ef-ik-neh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>venir à, parvenir jusqu'à, s'étendre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐφ·ικνέομαι-οῦμαι</b> <span>(<i>f</i>. -ίξομαι, <i>ao.2</i> ἐφικόμην)</span><br><b>      1</b> parvenir à, atteindre : ἅμα ἀλλήλων ἐφίκοντο, IL. <i>13, 615,</i> ils s’atteignirent en même temps l’un l’autre, <i>en parl. de deux combattants ; avec l’acc</i>. εἴ σε μοῖρ' ἐφίκοιτο, PD. <i>I. 4, 17,</i> si le sort t’a procuré ; ἐφ. πρὸς τὸν σκοπόν, LUC. <i>Nigr. 36,</i> atteindre le but ; <i>fig</i>. ἐφ. τῆς ἀρετῆς, ISOCR. <i>3</i> b ; τοῦ τριηραρχεῖν, DÉM. <i>465, 24,</i> parvenir à la vertu, au commandement d’une trirème ; <i>avec un inf</i>. devenir propre à, PLUT. <i>M. 338</i> d ; <i>avec un double acc</i>. τὸν Ἑλλήσποντον ἐκέλευε τριηκοσίας ἐπικέσθαι μάστιγι πληγάς, HDT. <i>7, 35,</i> il ordonna de parcourir l’Hellespont en frappant la mer de trois cents coups de fouet ; <i>abs</i>. τὸ φάρμακον οὐκ ἐφικνεῖτο, APP. <i>Mithr. 111,</i> le poison n’aboutissait pas ;<br><b>      2</b> s’étendre : ἐπὶ τοσαύτην γῆν, XÉN. <i>Cyr. 1, 1, 5,</i> s’étendre sur une aussi vaste contrée ; ἐφ. ὅσον ἐφικνεῖται, TH. <i>H.P. 1, 7, 1,</i> aussi loin que s’étend, <i>etc</i>.<br><span><b>Étym</b>. ἐπί, ἱκν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εφικνεομαι - ἐφικνέομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G2186":"<h1>ephistemi</h1>\n<p>Strong n° 2186 <i>Prononciation [ef-is'-tay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre sur, placer par dessus\n<ol type=\"a\">\n<li>se tenir, être présent</li>\n<li>se tenir au-dessus, survenir\n<ol>\n<li>utilisé pour des personnes survenant soudainement\n<ol type=\"a\">\n<li>un ange</li>\n<li>des rêves</li>\n</ol>\n</li>\n<li>le mal survenant sur quelqu'un</li>\n</ol>\n</li>\n<li>avoir en main\n<ol>\n<li>être prêt,</li>\n</ol>\n</li>\n<li>du temps\n<ol>\n<li>venir sur\n<ol type=\"a\">\n<li>la pluie</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐφ·ίστημι</b> ; ;<br><b>A</b> <i>tr. aux temps suiv. de l’act. (f</i>. ἐπιστήσω, <i>ao.1</i> ἐπέστησα, <i>pf</i>. ἐφέστηκα) :<br><b>   I</b> placer sur <i>ou</i> auprès, <i>d’où :</i><br><b>      1</b> poser sur, asseoir sur : τί τινι, THC. <i>2, 75 ;</i> τι ἐπί τινι, XÉN. <i>Hell. 3, 1, 7 ;</i> τι ἐπί τινος, PLAT. <i>Criti. 116</i> a ; τι ἐπί τι, DÉM. <i>1229, 29,</i> une chose sur une autre ; <i>fig</i>. ἐφ. ἀνάγκην τινί, DH. <i>1, 16,</i> imposer une nécessité à qqn ; φόϐον, STR. <i>4, 6, 3 ;</i> κατάπληξίν τινι, DS. <i>14, 62,</i> frapper qqn de frayeur, d’épouvante ; κίνδυνόν τινι, APP. <i>Hann. 55,</i> menacer qqn d’un danger ; <i>particul. en parl. de l’intelligence :</i> ἐφ. τὴν γνώμην κατά τι, ISOCR. <i>203</i> b ; τὴν διάνοιαν περί τινος, ARSTT. <i>Metaph. 1, 6, 2 ;</i> τὸν νοῦν τινι, DS. <i>12, 1 ; ou abs</i>. ἐπιστῆσαί τινι, ARSTT. <i>Mund. 1, 5 ; ou</i> περί τινος, ARSTT. <i>Gen. et corr. 1, 2, 2 ;</i> περί τι, ARSTT. <i>H.A. 1, 1, 12 ;</i> ἐπί τι, POL. <i>1, 65, 5,</i> appliquer son esprit à, fixer son attention sur qqe ch. ; <i>ou avec un rég. de pers. :</i> τινά, PLUT. <i>T. Gracch. 17,</i> fixer l’attention de qqn ; τινὰ ἐπί τι, POL. <i>2, 61, 11 ; 4, 34, 9,</i> fixer l’attention de qqn sur qqe ch. ;<br><b>      2</b> placer au-dessus de, préposer : τινὰ τέλει, ESCHL. <i>Ag. 1202,</i> préposer qqn à une charge ; τινὰ τοῖς πράγμασι, ISOCR. <i>20</i> b, mettre qqn à la tête des affaires ; στρατηγὸν τῷ στρατοπέδῳ, PLAT. <i>1 Alc. 122</i> b, confier à un général le commandement du camp ; <i>avec deux rég. de pers. :</i> ἐφ. τινι παιδαγωγούς, XÉN. <i>Lac. 2, 1,</i> donner à qqn des précepteurs ; ἐπὶ συμμάχων τινα, POL. <i>2, 65, 9,</i> préposer qqn au gouvernement des alliés : <i>avec une prop. inf</i>. τινὰ ποιεῖν τι, ISOCR. <i>147</i> b ; ARSTT. <i>Pol. 3, 16,</i> instituer qqn pour faire qqe ch., charger qqn de faire qqe ch. ;<br><b>      3</b> placer auprès de : ἱππέας ἐπ. κύκλῳ τὸ σῆμα, HDT. <i>4, 72,</i> placer des cavaliers autour du tombeau ; ὅρους ἐφ. ἐπὶ τὴν οἰκίαν, DÉM. <i>1029, 29,</i> placer des bornes auprès de la maison ;<br><b>   II</b> tenir en arrêt, arrêter : τὴν ὁδόν, DS. <i>17, 112 ;</i> τὴν πορείαν, PLUT. <i>Cim. 1,</i> interrompre le trajet, arrêter la marche ; ἐφ. τὸ στράτευμα, XÉN. <i>Cyr. 4, 2, 18,</i> arrêter l’expédition ; ἱππέας τοῦ πρόσω, ARR. <i>An. 5, 16, 1,</i> empêcher des cavaliers d’aller plus loin ; <i>abs</i>. ἐπιστήσας (<i>s.-e</i>. ἵππον) XÉN. <i>An. 1, 8, 15,</i> ayant arrêté son cheval ; <i>p. ext</i>. arrêter, instituer, établir : τινὶ ἀγῶνα, HDT. <i>1, 67, etc</i>. instituer un concours en l’honneur de qqn ;<br><b>B</b> <i>intr. aux temps suiv. <span>(ao.2</span></i> ἐπέστην, <i>pf</i>. ἐφέστηκα) et <i>au moy</i>. ἐφίσταμαι (<i>f</i>. ἐπιστήσομαι)<br><b>   I</b> se placer sur <i>ou</i> être placé sur :<br><b>      1</b> <i>au propre :</i> τινί, IL. <i>6, 373 ; 17, 609, etc. ;</i> ἐπί τινι, IL. <i>23, 201 ;</i> ἐπί τι, POL. <i>3, 46, 8,</i> sur qqe ch. (un char, un rempart, une tour, <i>etc</i>.) ; <i>abs</i>. se former à la surface, <i>en parl. de vapeurs, de pellicules sur un liquide,</i> HDT. <i>4, 2 ;</i> HPC. <i>40, 52 ;</i> ARSTT. <i>Juv. 5, 2 ;</i> DIOSC. <i>1, 96 ;</i><br><b>      2</b> <i>fig. en parl. de l’intelligence,</i> fixer son attention sur : EUR. <i>Andr. 547 ;</i> DÉM. <i>43, 20 ;</i> ἐπί τι, ISOCR. <i>213</i> d ; DÉM. <i>245, 12,</i> sur qqe ch. ;<br><b>   II</b> se tenir auprès de, <i>d’où :</i><br><b>      1</b> <i>au propre,</i> se placer près de : παρὰ τάφρῳ, IL. <i>12, 52, 199,</i> auprès d’un fossé ; ὣς πυκνοὶ ἐφέστασαν ἀλλήλοισι, IL. <i>13, 133,</i> ainsi ils se tenaient pressés les uns contre les autres ;<br><b>      2</b> venir près de, survenir : τινί, IL. <i>12, 326 ;</i> auprès de qqn, <i>en parl. des génies de la mort ;</i> ἐπὶ τὰς πύλας, HDT. <i>3, 77 ;</i> ἐπὶ τὰς θύρας, PLAT. <i>Conv. 212</i> e, se présenter aux portes ; ἐπὶ τῇ πόλι, HDT. <i>4, 203,</i> se présenter aux portes de la ville, <i>en parl. d’une armée ; en parl. de visions,</i> de songes : εὕδοντι ἐπέστη ὄνειρος, HDT. <i>1, 34,</i> pendant qu’il dormait, il lui survint un songe ; ἐπιστῆναι νυκτός, ISOCR. <i>215</i> d, survenir pendant la nuit ; ;<br><b>      3</b> <i>abs., t. de droit,</i> se présenter devant un tribunal comme accusateur, <i>etc</i>. PLAT. <i>Theæt. 172</i> e ; ESCHN. <i>65, 5 ;</i><br><b>   III</b> <i>avec idée d’hostilité,</i> se tenir contre, <i>d’où</i> lutter contre, <i>dat</i>. IL. <i>15, 703, etc. ; en parl. de malheurs,</i> se dresser sur <i>ou</i> contre, EUR. <i>Hipp. 829 ;</i><br><b>   IV</b> être placé au-dessus de :<br><b>      1</b> <i>au propre :</i> ἐφεστὼς μικρόν, HÉRON <i>Aut. 267,</i> placé un peu au-dessus ;<br><b>      2</b> <i>fig</i>. être préposé à : πύλαις, ESCHL. <i>Sept. 538 ;</i> προϐατίοις, AR. <i>Vesp. 955,</i> à la garde des portes, des troupeaux de moutons ; <i>avec une prép</i>. ἐφ. ἐπί τινι, XÉN. <i>Hier. 9, 5 ;</i> ἐπί τινος, PLAT. <i>Rsp. 460</i> b ; DÉM. <i>436, 28 ; rar. avec le gén</i>. τινος, HDT. <i>7, 117 ;</i> EUR. <i>Andr. 1058,</i> à. qqe ch. (à une surveillance, <i>etc</i>.) ; <i>d’où abs</i>. οἱ ἐφεστηκότες, XÉN. <i>Mem. 3, 5, 19, ou</i> οἱ ἐπεστεῶτες, HDT. <i>2, 148, etc. ;</i> SOPH. <i>Aj. 1072,</i> les chefs, les magistrats ;<br><b>   V</b> se tenir en suspens, faire halte, s’arrêter, XÉN. <i>An. 2, 4, 26 ;</i> PLAT. <i>Conv. 172</i> a ; POL. <i>1, 46, 11 ; 14, 7, 5 ;</i> τοῦ πλοῦ, THC. <i>2, 91,</i> suspendre sa navigation ;<br><b>C <b><i>Moy.</i></b><br>   I</b> <i>intr. au prés. et au fut. (v. ci-dessus</i> B) ;<br><b>   II</b> <i>tr. à l’ao</i>. ἐπεστησάμην : mettre sur : ἐπιστήσασθαι τέλος, PLAT. <i>Leg. 802</i> a, mettre fin ; φρουρούς, XÉN. <i>Cyr. 8, 2, 19,</i> poster des gardes.<br><span><b><span class=\"arrow\"></span></b> <i>Act. pl.q.pf. 3 sg</i>. ἐφεστάκει <span>[τᾰ]</span> <i>au sens tr</i>. POL. <i>10, 20, 5, etc. Pass. ao</i>. ἐπεστάθην, <i>c</i>. ἐπέστην, SOPH. <i>fr. 708 ;</i> EUR. <i>Hipp. 819, I.T. 1375. Dans Hom. à l’act. seul. les formes intr. ; au moy. seul. 3 sg. impf</i>. ἐφίστατο, IL. <i>11, 644</i>.<br><span><b>Étym</b>. ἐπί, ἵ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εφιστημι - ἐφίστημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n21 fois dans 21 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (7)</li>\n<li>Actes (11)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Timothée (2)</li>\n</ul>\n</td></tr>\n</table>","G2187":"<h1>Ephraim</h1>\n<p>Strong n° 2187 <i>Prononciation [ef-rah-im']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Ephraïm (Angl. Ephraim) = « double fertilité »\n<ol><li>cité à quelques kilomètres à l'est-nord-est de Béthel, ville proche du désert</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Εφραιμ</font> &lt; עפרים - <font face=\"Georgia\">Ἐφραίμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G2188":"<h1>ephphatha</h1>\n<p>Strong n° 2188 <i>Prononciation [ef-fath-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Ephphatha = « ouvre-toi ! »\n<ol>\n<li>sois ouvert\n<ol type=\"a\">\n<li>recevoir le pouvoir d'entendre, les oreilles du sourd et les yeux de l'aveugle étant considérés comme fermés</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εφφαθα</font> &lt; אפתח - <font face=\"Georgia\">εφφαθα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Impératif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G2189":"<h1>echthra</h1>\n<p>Strong n° 2189 <i>Prononciation [ekh'-thrah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>inimitié, haine</li>\n<li>cause de l'inimitié</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔχθρα, ας (ἡ) :<br>      1</b> haine, inimitié : τινός, THC. <i>3, 10 ; 7, 57 ;</i> ANT. <i>119, 20 ;</i> AR. <i>Pax 133 ;</i> ἔς τινα, HDT. <i>1, 5 ; 5, 81, etc. ;</i> πρός τινα, ESCHL. <i>Pr. 491 ;</i> THC. <i>2, 68 ;</i> DÉM. <i>530, 7,</i> contre qqn ; εἲς ἔχθραν ἐλθεῖν τινι, DÉM. <i>534, 24 ;</i> δι' ἔχθρας γενέσθαι, AR. <i>Av. 1412 ;</i> μολεῖν, EUR. <i>Ph. 479 ; ou</i> ἀφικέσθαι τινί, EUR. <i>Hipp. 11, 64,</i> en venir à éprouver de la haine contre qqn ; ἔχθραν ἔς τινα ποιεῖσθαι, THC. <i>2, 68 ;</i> αἴρεσθαι, DÉM. <i>558, 9,</i> devenir ennemi de qqn ; ἔχθραν συμϐάλλειν τινί, EUR. <i>Med. 44, El. 906 ; ou</i> συνάπτειν τινί, EUR. <i>Her. 459,</i> engager une lutte d’inimitié avec qqn ; <i>postér</i>. ἐν ἔχθρᾳ εἶναί τινι, SPT. <i>1Esdr. 5, 49 ;</i> πρός τινα, NT. <i>Luc. 23, 12,</i> être en inimitié avec qqn ; ἔχθραν ἔχειν πρός τινα, DÉM. <i>410, 10,</i> éprouver de la haine contre qqn ; ἔχθραν λύειν, EUN. <i>Tr. 50 ; ou</i> ἐκϐάλλειν, <i>Tr. 59 ; ou</i> διαλύεσθαι, THC. <i>4, 19,</i> renoncer à (<i>litt</i>. délier <i>ou</i> dissoudre) son inimitié ; καταλλάσσεσθαι τὰς ἔχθρας, HDT. <i>7, 145 ;</i> διαλλαχθῆναι τῆς ἔχθρας, AND. <i>23, 2,</i> renoncer à ses sentiments de haine ; πρὸς ἔχθραν, DÉM. <i>274, 4 ;</i> κατ' ἔχθραν, ESCHL. <i>Suppl. 335 ;</i> AR. <i>Pax 133,</i> par haine ;<br><b>      2</b> sujet de haine <i>ou</i> d’inimitié : ἔχθρα εἰς Θεόν, NT. <i>Rom. 8, 7,</i> ce qui est un sujet d’inimitié pour Dieu, ce qui déplaît à Dieu ; <i>qqf. au pl</i>. HDT. <i>7, 145 ;</i> ESCHL. <i>Pr. 492 ;</i> THC. <i>4, 19 ;</i> XÉN. <i>Cyr. 4, 5, 32 ;</i> PLAT. <i>Ep. 317</i> c.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ἔχθρη, HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. ἔχθος, <i>cf</i>. ἐχθρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εχθρα - ἔχθρα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Romains (1)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (2)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2190":"<h1>echthros</h1>\n<p>Strong n° 2190 <i>Prononciation [ech-thros']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>haï, odieux, haïssable</li>\n<li>hostile, qui hait et s'oppose à un autre\n<ol type=\"a\">\n<li>utilisé pour l'homme dans son inimitié avec Dieu par le péché\n<ol>\n<li>opposition à Dieu par l'esprit</li>\n<li>un homme qui est hostile</li>\n<li>un certain ennemi</li>\n<li>celui qui est hostile</li>\n<li>le diable qui est le pire ennemi du gouvernement divin</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐχθρός, ά, όν :<br>      1</b> <i>pass</i>. haï, détesté, <i>en parl. de pers. et de ch. :</i> τινι, IL. <i>9, 312, etc. ;</i> OD. <i>14, 156, etc. ;</i> HÉS. <i>Th. 766 ;</i> AR. <i>Eq. 34, etc</i>. odieux à qqn ; ἐχθρὸν δέ μοί ἐστιν, <i>avec l’inf</i>. OD. <i>12, 452,</i> c’est pour moi une chose odieuse de, <i>etc. ;</i><br><b>      2</b> <i>act</i>. qui hait, ennemi de, <i>en parl. de pers., dat</i>. THC. <i>8, 45 ;</i> XÉN. <i>Ages. 6, 1, etc. ; gén</i>. PD. <i>O. 7 ;</i> ESCHL. <i>Pr. 120 ;</i> THC. <i>4, 47 ;</i> XÉN. <i>Cyn. 13, 12 ;</i> DÉM. <i>134, 14 ; en parl. de choses (langue,</i> ESCHL. <i>Ch. 309 ; colère,</i> ESCHL. <i>Eum. 937, etc</i>.) ; <i>subst</i>. ὁ ἐχθρός, ATT. l’ennemi de qqn ; <i>p. opp. à</i> τὸν φιλέοντ', HÉS. <i>O. 340 ; à</i> φίλος, THC. <i>6, 85 ;</i> XÉN. <i>Cyr. 1, 4, 25, etc</i>.<br><span>•<i> Cp</i>. ἐχθρότερος, DÉM. <i>1448, 25 ;</i> ANTH. <i>5, 161 ; 7, 640 ; 9, 289</i>. <i>• Sup</i>. ἐχθρότατος, PD. <i>N. 1, 64 ;</i> SOPH. <i>O.R. 1346 ;</i> ANTH. <i>6, 43 ; 11, 370 ; cp. et sup. irrég</i>. ἐχθίων, ἔχθιστος <i>et</i> ἐχθίστατος (<i>v. ces mots</i>).<br><span><b>Étym</b>. ἔχθος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εχθρος - ἐχθρός</font>\n<br><br>vient de 'echtho' (haïr)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n32 fois dans 32 versets de 13 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (1)</li>\n<li>Luc (8)</li>\n<li>Actes (2)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (2)</li>\n<li>Galates (1)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G2191":"<h1>echidna</h1>\n<p>Strong n° 2191 <i>Prononciation [ekh'-id-nah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une vipère, une race de vipères\n<ol type=\"a\">\n<li>adressé aux hommes rusés, malicieux, méchants</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔχιδνα, ης (ἡ)</b> vipère, HDT. <i>3, 108 ;</i> ESCHL. <i>Ch. 988, Suppl. 873 ;</i> PLAT. <i>Soph. 218</i> a ; <i>fig. en parl. d’une femme perfide,</i> ESCHL. <i>Ch. 249 ;</i> SOPH. <i>Ant. 531</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εχιδνα - ἔχιδνα</font>\n<br><br>origine incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2192":"<h1>echo</h1>\n<p>Strong n° 2192 <i>Prononciation [ekh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>avoir, c.à.d tenir, détenir\n<ol type=\"a\">\n<li>avoir à la main, avoir possession d'un esprit (émotion), considérer comme détenir</li>\n</ol>\n</li>\n<li>avoir c.à.d posséder\n<ol type=\"a\">\n<li>des choses externes, un partage de propriété, des biens etc.</li>\n<li>de ceux qui sont joints par les liens du sang ou par le mariage ou par amitié ou les impératifs de la loi, le service ou le compagnonnage</li>\n</ol>\n</li>\n<li>se trouver ou se tenir soi-même de telle ou telle manière</li>\n<li>s'attacher à une chose, adhérer à, s'accrocher à\n<ol type=\"a\">\n<li>être fermement attaché à une personne ou une chose</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔχω</b> <span>(<i>impf</i>. εἶχον ; <i>f</i>. ἕξω <i>ou</i> σχήσω ; <i>ao.2</i> ἔσχον, <i>d’où impér</i>. σχές, <i>sbj</i>. σχῶ, <i>opt</i>. σχοίην, <i>inf</i>. σχεῖν, <i>part</i>. σχών ; <i>pf</i>. ἔσχηκα ; <i>pl.q.pf</i>. ἐσχήκειν. <i>Pass. prés</i>. ἔχομαι, <i>impf</i>. εἰχόμην, <i>f</i>. ἕξομαι, <i>ao</i>. ἐσχέθην, <i>pf</i>. ἔσχημαι ; <i>voy. le moy. ci-dessous</i>)</span><br><b>A</b> porter <i>d’où :</i><br><b>   I</b> <i>propr</i>. porter : τι χερσίν, IL. <i>1, 463 ;</i> ἐν χερσίν, IL. <i>18, 105 ;</i> ESCHL. <i>fr. 51 ;</i> μετὰ χερσίν, IL. <i>11, 484 ;</i> διὰ χερῶν, ESCHL. <i>Suppl. 193 ; ou</i> διὰ χειρός, THC. <i>2, 13, 76,</i> porter qqe ch. dans les mains ; τινὰ ἐπ' ὤμων, SOPH. <i>fr. Laoc. 3, 2,</i> porter qqn sur ses épaules ; <i>en parl. de vêtements, d’armes :</i> εἷμα ἀμφ' ὤμοισι, IL. <i>18, 538,</i> avoir un vêtement autour des épaules ; παρδαλέην ὤμοισιν, IL. <i>3, 17,</i> une peau de panthère sur les épaules : τι ὤμῳ, IL. <i>14, 376 ; ou</i> ἐπὶ τὸν ὦμον, XÉN. <i>An. 6, 3, 25,</i> qqe ch. sur l’épaule ; στολὴν ἀμφὶ σῶμα, EUR. <i>Hel. 561,</i> une robe autour du corps ; κυνέην κεφαλῇ, OD. <i>24, 231,</i> avoir un casque sur la tête ; <i>abs</i>. χιτῶνας, XÉN. <i>An. 1, 5, 8 ;</i> ἀσπίδα, IL. <i>13, 157 ;</i> αἰχμήν, ESCHL. <i>Sept. 511,</i> avoir <i>ou</i> porter des tuniques, un bouclier, une lance ; <i>p. anal</i>. πολιάς, ESCHN. <i>1, 49 Baiter-Sauppe,</i> des cheveux blancs ; <i>en parl. d’animaux,</i> ζυγὸν ἀμφὶς ἔχοντες, OD. <i>3, 486,</i> ayant <i>ou</i> portant le joug autour du cou ;<br><b>   II.1</b> porter, conduire, diriger ; ἵππους, IL. <i>3, 263,</i> des chevaux ; νῆα, OD. <i>9, 279 ;</i> HDT. <i>6, 95,</i> un vaisseau ; ἅρμα HÉS. <i>Sc. 97 ;</i> δίφρον, HÉS. <i>Sc. 352,</i> un char ; τὸν ὦμον πρὸς τῷ ὤμῳ, XÉN. <i>Conv. 4, 27,</i> approcher son épaule de l’épaule de qqn ; πόδα ἐκτὸς κλαυμάτων, SOPH. <i>Ph. 1244, litt</i>. porter ses pas hors des plaintes, <i>càd</i>. passer sa vie sans danger ; <i>fig</i>. ἔχειν πόδα πημάτων ἔξω, ESCHL. <i>Pr. 264 ;</i> ἔξω πραγμάτων, EUR. <i>Her. 110,</i> se dégager de souffrances, d’embarras ; <i>d’où abs</i>. ἐκποδὼν ἔχειν ἑαυτόν, ESCHL. <i>Pr. 344 ;</i> XÉN. <i>Cyr. 6, 1, 37,</i> se dégager de ; θυμὸν ἔχειν ἐπὶ ἔργῳ, HÉS. <i>O. 442,</i> s’attacher avec ardeur à un travail ; πρός τινα τὸν νοῦν ἔχειν, THC. <i>3, 22 ; ou</i> πρός τινα τὴν γνώμην ἔχειν, THC. <i>3, 25 ;</i> πρός τι τὸν νοῦν ἔχειν, THC. <i>7, 19 ; ou</i> ἐπί τινι, ATT. porter son attention, son esprit sur qqn <i>ou</i> sur qqe ch. ; <i>abs. à l’impér</i>. ἔχε <i>au sens de</i> ἄγε, allons ! eh bien ! voyons ! <i>d’ord. avec une particule :</i> ἔχε δὴ καλῶς γὰρ λέγεις, PLAT. <i>Gorg. 460</i> a, eh bien, voyons, car tu parles bien ; <i>cf</i>. PLAT. <i>Rsp. 353</i> b, <i>etc. ; même avec un verbe au plur</i>. ἔχε δὴ ἴδωμεν, PLAT. <i>Crat. 435</i> e ; eh bien, voyons ! <i>avec</i> οὖν : ἔχε οὖν, PLAT. <i>1 Alc. 129</i> b, eh bien donc ; <i>qqf. sans particule,</i> PLAT. <i>1 Alc. 109</i> b ; <i>suivi d’un autre impér. :</i> ἔχ', ἀποκάθαιρε τὰς τραπέζας, AR. <i>Pax 1193,</i> allons ! nettoie les tables ; <i>cf</i>. AR. <i>Vesp. 1135 ; en ce sens avec la particule</i> νυν ; ἔχε νυν, ἄλειψον τὸν τράχηλον τουτῳί, AR. <i>Eq. 490,</i> allons ! graisse-lui le cou ; <i>cf. Eq. 493 ; ou avec</i> δή : ἔχε δή μοι τόδε εἰπέ, PLAT. <i>Ion 535</i> b, allons ! dis-moi ceci ; <i>p. suite, intr. en appar. (s.-e</i>. ἑαυτόν, νῆας <i>ou</i> ἵππους) <i>intr</i>. se porter, se diriger (<i>litt</i>. diriger ses chevaux, ses vaisseaux) ; Πύλονδ' ἔχον, OD. <i>3, 182,</i> je me dirigeais vers Pylos ; νέες ἔσχον (<i>s.-e</i>. ἑαυτὰς) εἰς τὴν Ἀργολίδα χώρην, HDT. <i>6, 92,</i> la flotte se dirigea vers l’Argolide ; ἐς Φειὰν σχόντες, THC. <i>2, 25,</i> s’étant dirigés vers Phéia ; πρὶν τῇ Δήλῳ ἔσχον, THC. <i>3, 29,</i> avant de se diriger vers Dèlos ; ὑψόσε, OD. <i>19, 38,</i> en haut ; ἔκτοσθε, IL. <i>10, 263,</i> au dehors ; ὁδοὶ ἐπὶ τὸν ποταμὸν ἔχουσαι, HDT. <i>1, 180,</i> routes qui se dirigent vers le fleuve ; ἔγχος ἔσχε δι' ὤμου, IL. <i>13, 520,</i> la javeline se dirigea (<i>litt</i>. se porta) à travers l’épaule, s’y enfonça ; <i>fig</i>. τὰ ἐς Ὅμηρον ἔχοντα, HDT. <i>2, 53,</i> ce qui se rapporte à Homère ; ἐχθρῆς παλαιῆς ἐχούσης ἐς Ἀθηναίους, HDT. <i>5, 81,</i> une vieille haine se portant sur les Athéniens ; ἐπί τινι ἔχειν, HDT. <i>6, 49,</i> se porter contre qqn, l’attaquer ; <i>souv. avec un adv</i>. se porter de telle <i>ou</i> telle manière, être dans telle disposition, tel état : εὖ ἔχειν, OD. <i>24, 245 ;</i> PLAT. <i>Rsp. 330</i> a, <i>etc. ;</i> καλῶς ἔχειν, SOPH. <i>El. 816, etc</i>. être en bon état, se bien porter ; εὖ σχήσει, SOPH. <i>Aj. 684,</i> tout ira bien ; οὕτως ἔχει (<i>s.-e</i>. τὰ πράγματα) XÉN. <i>Cyr. 2, 1, 8, etc. ;</i> AR. <i>Pl. 110, etc</i>. il en est ainsi ; οὕτως ἐχόντων, XÉN. <i>An. 3, 2, 10 ; ou</i> ὡς οὕτως ἐχόντων, HDT. <i>8, 144 ; ou</i> ὡς ὧδ' ἐχόντων, HDT. <i>1, 126 ;</i> SOPH. <i>Aj. 981,</i> les affaires étant ainsi (<i>lat</i>. cum res ita se habeant) ; κατεκλίθη ὥσπερ εἶχε χαμαί, XÉN. <i>Hell. 4, 1, 30,</i> il se coucha comme il était (<i>càd</i>. tout habillé) par terre ; <i>avec un rég</i>. οὕτως ἔχει μοι, SOPH. <i>O.C. 599,</i> il en va ainsi pour moi ; οὕτως ἐμοὶ ἔχει περὶ τῆς οἰκονομίας, XÉN. <i>Œc. 2, 12,</i> ainsi en est-il pour moi du gouvernement de la maison ; ἔχειν <i>avec un adv. équivaut à</i> εἶναι <i>avec l’adj. corresp. ;</i> ἔχει μοι ἀναγκαίως, HDT. <i>9, 27,</i> il m’est nécessaire ; ἀκρατῶς ἔχειν πρὸς τὰς ἡδονάς, PLAT. <i>Leg. 710</i> a, se livrer sans mesure aux plaisirs ; οὕτως ἔχειν πρός τινα, ISOCR. <i>200</i> e, être dans ces dispositions à l’égard de qqn ; πρὸς τὸ φιλοκερδεῖς εἶναι μετρίως ἔχουσι, XÉN. <i>Œc. 12, 16,</i> ils sont modérés dans leur désir de gagner ; <i>avec un gén. :</i> εὖ σώματος ἔχει, PLAT. <i>Rsp. 404</i> d, il se porte bien ; πῶς ἔχεις δόξης τοῦ τοιοῦδε πέρι ; PLAT. <i>Rsp. 456</i> d, quel est ton avis là-dessus ? ὡς τάχους εἶχε, HDT. <i>8, 107 ;</i> THC. <i>2, 90,</i> aussi vite qu’il pouvait ; <i>ou</i> entre parenthèses : ὀργῇ, ὡς εἶχε, ἐλθὼν παρὰ τὸν Ἀστυάγεα, HDT. <i>1, 114,</i> étant venu irrité, comme il était (<i>càd</i>. sur le champ) vers Astyage ; <i>en ce sens ἔχω s’emploie qqf. avec un part. ao. :</i> ἀδελφὴν τὴν ἐμὴν γήμας ἔχεις ; SOPH. <i>O.R. 577,</i> n’est-ce pas ma sœur que tu as épousée ? Κορίνθιους δήσαντες εἶχον, THC. <i>1, 30,</i> ils enchaînèrent les Corinthiens et les retinrent en leur pouvoir ; <i>cf</i>. HÉS. <i>O. 42 ;</i> HDT. <i>1, 37, etc. ;</i> PLAT. <i>Crat. 404</i> c ; <i>qqf. avec un part. pf. :</i> ὦν πολλὰ χρήματα ἔχομεν ἡρπακότες, XÉN. <i>An. 1, 3, 14,</i> auxquels nous avons ravi un riche butin ; <i>cf</i>. SOPH. <i>O.R. 701, Ph. 596 ; rar. avec un part. prés. :</i> τὸν θανόντα καταστένουσ' ἔχεις, EUR. <i>Tr. 318,</i> tu pleures celui qui est mort ;<br><b>      2</b> <i>p. suite,</i> entraîner par son poids, <i>d’où</i> peser, <i>d’où</i> valoir (<i>cf. la même relat. d’idées au mot</i> ἄγω) : ἔχειν δραχμὰς δέκα, DS. <i>11, 26,</i> valoir dix drachmes ; ἔχ. δραχμὰς ἑπτακισχιλίας, APP. <i>1, 94 Schweigh</i>. valoir sept mille drachmes ;<br><b>      3</b> <i>p. anal. en parl. de mesures,</i> avoir (en longueur, en hauteur, <i>etc</i>.) : ἔχειν τὸ ὕψος δύο καὶ ἡμίσους πήχεων, PTOL. ÉVERG. (ATH. <i>375</i> d) avoir une hauteur de deux coudées et demie ; τὸν κύκλον ἔχει τοῦ τείχους τριακοσίων ὀγδοήκοντα πέντε σταδίων, STR. <i>16, 1, 5 Kram</i>. ce mur a une circonférence de 385 stades ;<br><b>B</b> s’attacher à, <i>d’où :</i><br><b>   I</b> saisir, s’emparer de, prendre, SOPH. <i>Ph. 1118 ;</i> ἔχ. τινὰ χειρός, IL. <i>4, 154 ;</i> ποδός, IL. <i>16, 763,</i> saisir qqn par la main, par le pied ; ἔχ. τινὰ μέσον, AR. <i>Nub. 1047,</i> saisir qqn par le milieu du corps ; <i>au pass</i>. ἔχομαι μέσος, AR. <i>Ach. 571,</i> je suis retenu par le milieu du corps ; <i>avec un suj. de chose :</i> ὕπνος οὐκ ἔχε Δία, IL. <i>2, 2,</i> le sommeil ne tenait pas Zeus ; φόϐος μ' ἔχει, ESCHL. <i>Ag. 1243,</i> la crainte me saisit ; τὸν δ' ἕως ἔχεν ἥϐη, HH. <i>Ven. 226,</i> tant qu’il était jeune ; ἔχει βέλος ὀξὺ γυναῖκα, IL. <i>11, 269,</i> un trait aigu pénètre la femme, <i>en parl. des douleurs de l’enfantement ; avec double acc</i>. ἦ ῥά σε οἶνος ἔχει φρένας, OD. <i>18, 391,</i> certes le vin, <i>càd</i>. l’ivresse, s’est emparé de ton esprit ; φόϐος μ' ἔχει φρένας, ESCHL. <i>Suppl. 379,</i> la crainte possède mon esprit ; <i>fig</i>. ἔχειν φρεσίν, IL. <i>2, 33 ;</i> garder dans son esprit ; ἔχ. νῷ, PLAT. <i>Euthyphr. 2,</i> se mettre dans l’esprit ; <i>abs</i>. se rendre maître de qqe ch. par l’intelligence, saisir, comprendre (<i>cf</i>. tenere) : ἔχετε τὸ πρᾶγμα, SOPH. <i>Ph. 789,</i> vous connaissez la chose, <i>càd</i>. vous voyez mon état ; ἔχεις τι ; AR. <i>Nub. 732,</i> comprends-tu qqe chose ? <i>cf</i>. SOPH. <i>Ant. 9, Tr. 318 ;</i> EUR. <i>Or. 1120 ;</i><br><b>   II</b> retenir, <i>càd. :</i><br><b>      1</b> tenir ferme, contenir, maintenir : σάρκας τε καὶ ὀστέα ἶνες ἔχουσι, OD. <i>13, 219,</i> les nerfs retiennent, <i>càd</i>. maintiennent, tiennent ensemble les chairs et les os ;<br><b>      2</b> réprimer, arrêter : οὐδ' ἔσχεν ὀστέον, IL. <i>16, 740,</i> l’os n’arrêta point (le coup), <i>càd</i>. ne résista point ; ἔχειν ἵππους, IL. <i>4, 302,</i> retenir des chevaux ; ἔχειν τινά, IL. <i>13, 51,</i> retenir qqn ; χεῖρας ἔχων Ἀχιλῆος, IL. <i>18, 33,</i> tenant les mains d’Achille ; ἔχειν πόδα, EUR. <i>I.T. 1159,</i> retenir ses pas, s’arrêter ; ἔχειν μῦθον, OD. <i>15, 445,</i> retenir sa parole ; ὄμμ' ἔχειν, SOPH. <i>Aj. 192, litt</i>. tenir son regard caché, <i>càd</i>. rester enfermé ; ἔχειν τινά τινος, IL. <i>2, 275,</i> écarter qqn de qqe ch. ; ἀσκὸς δύο ἄνδρας ἕξει τοῦ μὴ καταδῦναι, XÉN. <i>An. 3, 5, 11,</i> une outre préservera deux hommes de tomber à l’eau ; <i>cf</i>. HDT. <i>1, 158 ;</i> EUR. <i>Andr. 686 ; avec</i> τὸ μή <i>et l’inf</i>. ESCHL. <i>Eum. 691,</i> empêcher qqn de, <i>etc. ; p. suite, intr. en appar. (s.-e</i>. ἑαυτόν) s’arrêter, se fixer ; οὐδέ οἱ ἔγχος ἔχ' ἀτρέμας, IL. <i>13, 557,</i> sa lance ne restait pas immobile ; σχὲς οὗπερ εἶ, SOPH. <i>O.C. 1169,</i> reste où tu es, comme tu es ; σχές, arrête, arrête-toi, EUR. <i>Hec. 962, Hipp. 1353, I.A. 1467 ;</i> ἔχ' ἡρέμα, PLAT. <i>Crat. 399</i> e, tiens-toi tranquille ; <i>abs. avec une prép</i>. τοὺς κατὰ τὴν Ἀσίαν ἔχοντας, XÉN. <i>Cyr. 4, 2, 2,</i> ceux qui habitent la région de l’Asie ;<br><b>   III</b> tenir, <i>càd. :</i><br><b>      1</b> acquérir, obtenir (non avoir) : σχοῦσα, SOPH. <i>El. 551,</i> quand tu auras acquis (non quand tu auras eu) ; ὧν αὐτὸς ἔσχε στέφανον εὐκλείας, SOPH. <i>Aj. 465,</i> les récompenses qu’il a obtenues comme une couronne de gloire ;<br><b>      2</b> <i>p. suite,</i> avoir à sa disposition, posséder, avoir : ἔχ. οὐσίας, XÉN. <i>Hell. 5, 2, 7 ;</i> χρήματα, XÉN. <i>Cyr. 3, 3, 3, etc</i>. posséder des richesses, des biens, <i>etc. ; abs</i>. ὁ ἔχων, SOPH. <i>Aj. 157 ;</i> EUR. <i>Alc. 57,</i> celui qui possède, le riche ; <i>joint à</i> πλουτῶν, DÉM. <i>1123, 25 ;</i> οἱ οὐκ ἔχοντες, EUR. <i>Suppl. 240,</i> ceux qui ne possèdent pas, les pauvres ; κακὸν τὸ μὴ 'χειν, EUR. <i>Ph. 405,</i> c’est chose malheureuse de ne rien posséder ; <i>avec double rég</i>. ἔχ. κάλλος ἀπὸ θεῶν, HH. <i>Ven. 77,</i> avoir reçu des dieux la beauté ; ἔχ. τι ἔκ τινος, SOPH. <i>O.C. 1618 ;</i> παρά τινος, SOPH. <i>Aj. 663 ;</i> ὑπό τινος, XÉN. <i>An. 7, 6, 33 ;</i> ὑπό τινι, HH. <i>Ap. 191,</i> posséder qqe ch. de la main de qqn ; <i>fig</i>. ἔχ. τέχνην, HÉS. <i>Th. 770 ;</i> EUR. <i>I.T. 53 ;</i> XÉN. <i>Mem. 3, 10, 1 ;</i> PLAT. <i>Pol. 296</i> b ; <i>ou</i> ἐπιστήμην, SOPH. <i>Ph. 1057 ;</i> PLAT. <i>Euthyd. 273</i> e, posséder un art, une science ; ἔχ. ἵππων δμῆσιν, IL. <i>17, 476,</i> posséder l’art de dompter les chevaux ; <i>en gén. en parl. de toutes les qualités physiques et morales :</i> ἔχ. ἡλικίαν, XÉN. <i>Cyr. 1, 6, 34,</i> avoir un certain âge ; ἔχ. ἥϐην, PLAT. <i>Prot. 309</i> b, être jeune ; ἔχ. γῆρας, OD. <i>24, 250,</i> être vieux ; ἔχειν αἰσχύνην, EUR. <i>Andr. 243, etc</i>. éprouver de la honte ; θαῦμα ἔχω, SOPH. <i>El. 897, etc</i>. je m’étonne, j’admire ; ἔχειν ὀργήν, SOPH. <i>Ph. 1293, etc</i>. éprouver de la colère ; ἔχειν ἄλγεα, IL. <i>5, 895, etc</i>. éprouver des souffrances ; ἔχειν πένθος μετὰ φρεσί, IL. <i>24, 105 ; ou</i> ἔχειν πένθος φρεσί, OD. <i>7, 219,</i> avoir la douleur dans l’âme : τιμὴν ἔχειν παρὰ πᾶσι, PLUT. <i>Sol. 29,</i> être honoré par tous ; δόξαν ἔχ. EUR. <i>Or. 235,</i> avoir de la gloire ; ἔχ. φθόνον παρὰ τοῖς δυνατοῖς, PLUT. <i>Them. 29,</i> exciter l’envie des puissants ; ἔχω <i>et son rég. forment ainsi une locut. équivalant à un verbe simple :</i> ποθὴν ἔχ. τινός, IL. <i>6, 362</i> = ποθεῖν, regretter ; κότον ἔχ. IL. <i>13, 517</i> = κοτεῖσθαι, éprouver du ressentiment ; ἔχ. ἔγκλημά τινι, SOPH. <i>Ph. 322</i> = ἐγκαλεῖν, accuser qqn ; ἔχ. οἶκτον, SOPH. <i>Aj. 521</i> = οἰκτίρειν, éprouver de la pitié ; <i>cf</i>. στοναχὰς ἔχειν, SOPH. <i>Aj. 203</i> = στενάζειν ; γόους ἔχειν, SOPH. <i>Aj. 319</i> = γοᾶσθαι ; παρουσίαν ἔχειν, SOPH. <i>Aj. 540</i> = παρεῖναι ; μνήμην ἔχειν, SOPH. <i>O.C. 509</i> = μεμνῆσθαι ; συγγνώμην ἔχειν, SOPH. <i>Ph. 1319</i> = συγγιγνώσκειν, <i>etc. ; avec une prép</i>. δι' ὀργῆς ἔχ. τινά, THC. <i>2, 37 ;</i> ἐν ὀργῇ ἔχ. τινά, THC. <i>2, 18,</i> être irrité contre qqn, <i>etc</i>. (<i>v</i>. διά, ἐν, <i>etc.) ; invers. au pass</i>. ἔχεσθαι ἄλγεσι, OD. <i>8, 182,</i> être en proie aux souffrances ; κωκυτῷ καὶ οἰμωγῇ, IL. <i>22, 409,</i> être en proie aux lamentations et aux gémissements ; νόσῳ, PLAT. <i>Ep. 331</i> c ; νούσῳ, HPC. <i>1142</i> h, être malade ; μανίαις, PLAT. <i>Leg. 881</i> b, être pris d’accès de folie ; λιμῷ, LUC. <i>Ep. sat. 3, 31,</i> souffrir de la faim ; ὀργῇ, HDT. <i>1, 141,</i> être possédé par la colère ; <i>avec une prép</i>. ἔχεσθαι ὑπὸ τοῦ ὕδρωπος, HPC. <i>89</i> c, être atteint d’hydropisie ; ἔχεσθαι ἐν ξυμφοραῖς, PLAT. <i>Rsp. 395</i> e, être dans le malheur ; ἔχεσθαι ὑπὸ ἐπιθυμίας, PLAT. <i>Rsp. 390</i> c, être possédé de désir ; <i>avec une prop. subord</i>. οὐκ ἔχω τὶ φῶ, ESCHL. <i>Ch. 89 ;</i> SOPH. <i>O.C. 318 ; ou</i> ὅ τι χρὴ λέγειν, XÉN. <i>Cyr. 1, 4, 24,</i> je ne sais que dire ; τὰ ἐπιτήδεια οὐκ εἶχον ὁπόθεν λαμϐάνοιεν, XÉN. <i>An. 3, 5, 3,</i> ils ne savaient où se procurer des vivres ; <i>de même avec les conj</i>. πῶς, ὅπως, LUC. <i>Philops. 35 ; avec</i> ποῖ, SOPH. <i>Tr. 705 ; avec</i> ὅπῃ, PLAT. <i>Phæd. 107</i> a, <i>etc. ; avec un inf</i>. οὐδὲν ἀντειπεῖν ἔχω, ESCHL. <i>Pr. 51,</i> je n’ai rien à répondre ; πόλλ' ἂν λέγειν ἔχοιμι, SOPH. <i>Ph. 1047,</i> j’aurais beaucoup à dire ; <i>cf</i>. IL. <i>7, 217 ; 21, 242 ;</i> OD. <i>18, 364 ;</i> XÉN. <i>Cyr. 5, 5, 19 ; avec</i> μή <i>et l’inf</i>. EUR. <i>Hipp. 658 (cf. ci-dessus</i> II, 2, ἔχειν τὸ μή <i>et l’inf.) ; à la fois avec l’inf. et avec</i> ὅπως <i>suivi du sbj</i>. SOPH. <i>Aj. 429 ; avec</i> ὅπως μή, PLAT. <i>Rsp. 368</i> b ;<br><b>      3</b> avoir avec soi <i>ou</i> auprès de soi : τοὺς μὲν βελτίστους ἔχ. μεθ' ἑαυτοῦ, XÉN. <i>Cyr. 1, 4, 17,</i> avoir les meilleurs avec soi ; <i>cf</i>. XÉN. <i>Cyr. 4, 2, 29, etc. ;</i> ἔχ. γυναῖκα, XÉN. <i>Cyr. 7, 2, 26,</i> avoir une femme ; <i>abs</i>. avoir pour femme, IL. <i>3, 53, etc. ;</i> OD. <i>4, 569, etc. ;</i> HDT. <i>3, 31 ;</i> XÉN. <i>Lac. 1, 7, etc. ; au pass</i>. τοῦ περ θυγάτηρ ἔχεθ' Ἕκτορι, IL. <i>6, 398,</i> dont la fille était la femme d’Hector ; <i>de même</i> avoir pour maîtresse, THC. <i>6, 57 ;</i> ANTH. <i>5, 186 ;</i> ἔχω Λαΐδα, ἀλλ' οὐκ ἔχομαι, ARISTIPP. (DL. <i>2, 75</i>), je possède Laïs, mais elle ne me possède pas ;<br><b>      4</b> avoir en soi, contenir, renfermer : τεῖχος νῆας ἐντὸς ἔχον, IL. <i>12, 8,</i> mur qui enferme des navires dans son enceinte ; ὅσσους Κρήτη ἐντὸς ἔχει, HH. <i>Ap. 30,</i> tous ceux que renferme la Crète ; θηρῶν οὓς ὅδ' ἔχει χῶρος, SOPH. <i>Ph. 1147,</i> des bêtes que renferme ce pays ; <i>cf</i>. HH. <i>Merc. 251 ;</i> XÉN. <i>Cyn. 5, 24 ;</i><br><b>      5</b> avoir pour résidence, occuper, habiter : Ὄλυμπον, IL. <i>5, 890,</i> l’Olympe ; Ὀλύμπια δώματα, HÉS. <i>O. 127,</i> les demeures de l’Olympe ; οἶκον, IL. <i>7, 68 ;</i> OD. <i>6, 183,</i> une maison ; χῶρον, ESCHL. <i>Eum. 24,</i> un pays ; <i>particul. en parl. des dieux protecteurs d’une contrée, des héros,</i> THC. <i>2, 74 ;</i> XÉN. <i>Cyr. 8, 3, 24 ;</i> ὀρέων κάρηνα καὶ πηγάς, OD. <i>6, 123,</i> habiter les sommets des montagnes et les sources, <i>en parl. des nymphes ; en parl. d’animaux :</i> ἔχ. τὰ ὄρη, XÉN. <i>Cyn. 5, 2,</i> habiter les montagnes (<i>cf. ci-dessus au sens intr</i>. se fixer, résider, II, 2) ;<br><b>      6</b> <i>en gén</i>. occuper, <i>en parl. d’une place assignée, d’un poste :</i> ἔχειν τὸ δεξιόν, XÉN. <i>An. 1, 2, 15,</i> occuper la droite ; ἔχ. τὸ κέρας ἄκρον, THC. <i>3, 107,</i> occuper l’extrémité de l’aile ; ἐπ' ἀριστερὰ ἔχ. τι, OD. <i>3, 171 ; ou</i> ἐπ' ἀριστερὰ χειρὸς ἔχειν, OD. <i>5, 277,</i> avoir qqe ch. à sa gauche, <i>càd</i>. être à la droite de qqe ch. ; ἐν δεξιᾷ, ἐν ἀριστερᾷ ἔχ. THC. <i>3, 106,</i> avoir à sa droite, à sa gauche ;<br><b>      7</b> avoir sous sa direction, gouverner, administrer : πατρώϊα ἔργα, OD. <i>2, 22,</i> diriger les travaux paternels, <i>càd</i>. cultiver les champs paternels ; Θήϐας, EUR. <i>H.f. 4,</i> avoir Thèbes sous son pouvoir ; κῆπον, OD. <i>4, 737,</i> cultiver un champ ; ἀγέλας, XÉN. <i>Cyr. 7, 3, 7,</i> soigner des troupeaux ; πύλαι ἃς ἔχον Ὧραι, IL. <i>5, 749,</i> les portes dont les Heures avaient la garde ;<br><b>      8</b> avoir, choisir <i>ou</i> prendre à titre de : ὄμνυμ' ἔγωγε, Ζῆν ἔχων ἐπώμοτον, SOPH. <i>Tr. 1188,</i> je le jure, prenant Zeus à témoin de mon serment ;<br><b>      9</b> tenir pour, regarder comme : Ὀρφέα ἄνακτ' ἔχων, EUR. <i>Hipp. 953,</i> regardant Orphée comme son maître ; ἔχ. τι ἐν ἡδονῇ, ἐν αἰσχύνῃ, διὰ σπουδῆς (<i>v</i>. ἐν, διά) :<br><b>      10</b> ἔχω <i>s’emploie explétiv. au part. prés</i>. ληρεῖς ἔχων, AR. <i>Av. 341 ;</i> ἔχων ληρεῖς, PLAT. <i>Gorg. 497</i> a, tu plaisantes ; φλυαρεῖς ἔχων, PLAT. <i>Gorg. 490</i> e ; ἔχων φλυαρεῖς, PLAT. <i>Euthyd. 295</i> c, tu dis des sottises ; <i>cf</i>. PLAT. <i>Phædr. 236</i> e ; AR. <i>Th. 852, Ran. 202, etc. ; de même au part. neutre avec</i> ἐστί : ἐστὶν ἔχον = ἔχει, HDT. <i>1, 86 ;</i> ἐστὶν ἀναγκαίως ἔχον = ἔχει ἀναγκαίως, ESCHL. <i>Ch. 237 ;</i> AR. <i>Pax 334 ; dans la locut</i>. τὸ νῦν ἔχον, maintenant, LUC. <i>Cat. 13 ;</i> M. TYR. <i>1, p. 469 ;</i><br><b><i>Moy</i>. ἔχομαι</b> <span>(<i>f</i>. ἕξομαι <i>ou</i> σχήσομαι, <i>ao.2</i> ἐσχόμην, <i>pf</i>. ἔσχημαι)</span><br><b>A</b> porter, <i>d’où :</i><br><b>   I</b> porter sur soi, tenir sur soi : ἄντα παρειάων σχομένη κρήδεμνα, OD. <i>1, 334,</i> tenant son voile contre ses joues ;<br><b>   II</b> lever, tendre : ἀσπίδα πρόσθε σχόμενος, IL. <i>12, 294, 298 ; ou</i> σάκος, IL. <i>20, 262,</i> tenant devant lui son bouclier ;<br><b>   III</b> supporter : οὐρανὸν εὐρύν, HÉS. <i>Th. 746,</i> le vaste ciel (sur ses épaules) ;<br><b>B</b> tenir en arrière de, retenir : τινὸς σχέσθαι χέρα, EUR. <i>Rhes. 174,</i> se retenir de frapper qqn ;<br><b>C</b> s’attacher à, <i>càd. :</i><br><b>   I</b> se saisir de, prendre : τινος, qqe ch. ESCHL. <i>Sept. 97 ; ou</i> qqn (pour l’attirer à soi) PLUT. <i>M. 772</i> c ;<br><b>   II</b> <i>p. suite,</i> tenir : τινος, XÉN. <i>Cyn. 10, 11 ; Eq. 7, 5 ; 12, 5,</i> qqe ch. (un filet, des rênes, <i>etc</i>.) ; καί μοι ἕπου ἐχόμενος τῆς χλαμύδος, LUC. <i>Tim. 30,</i> et suis-moi en me tenant par ma chlamyde ; εἰπόμην δ' ἐγὼ κατόπιν ἐχόμενος αὐτοῦ, LUC. <i>Nec. 11,</i> je le suivais, le tenant par derrière ; <i>en parl. des suppliants :</i> ἔχεσθαι (γούνων) IL. <i>1, 512,</i> tenir (les genoux de qqn) ; <i>fig</i>. ἔχεσθαι ὁδοῦ, HDN <i>2, 11, 1</i> se mettre en route ; ἔχ. ἔργου, HDT. <i>2, 121 ;</i> THC. <i>1, 78 ; 2, 2 ;</i> XÉN. <i>Hell. 7, 2, 19,</i> se mettre à une œuvre, à une entreprise ; ἔχ. πολέμου, THC. <i>6, 88 ; 8, 3,</i> entreprendre une guerre ; ἔχ. μάχης, SOPH. <i>O.C. 424,</i> engager un combat ; τῆς γνώμης τῆς αὐτῆς ἔχομαι, THC. <i>1, 140,</i> je m’en tiens au même avis ; ἔχ. τοῦ αὐτοῦ λόγου, THC. <i>5, 49,</i> s’en tenir au même langage ;<br><b>   III</b> suivre immédiatement : ὑμᾶς χρὴ ἕπεσθαι ἐχομένους ὅτι μάλιστα τῶν ἁρμάτων, XÉN. <i>Cyr. 7, 1, 9,</i> il vous faut suivre vous tenant le plus près possible des chars ; <i>particul. en parl. de situations géographiques :</i> ὄρος ἐχόμενον τῆς Ῥοδόπης, THC. <i>2, 96,</i> montagne qui se rattache au Rhodope ; ἡ ἐχομένη νῆσος, ISOCR. <i>60</i> c, l’île voisine, <i>en parl. de Salamine ; en parl. de pers</i>. ἐχόμενοι τῶν μεταξὺ Μαντινείας καὶ Τεγέας ὀρῶν, XÉN. <i>Hell. 6, 5, 16,</i> les populations contiguës aux montagnes entre Mantinée et Tégée ; <i>abs</i>. οἱ ἐχόμενοι, HDT. <i>1, 134,</i> les voisins (<i>litt</i>. ceux qui tiennent, qui sont contigus à d’autres) ; τὰ τούτων ἐχόμενα, XÉN. <i>Œc. 6, 1 ; ou</i> τὰ ἐχόμενα τούτοις, PLAT. <i>Gorg. 494</i> e, ce qui s’y rattache ; ἐν τοῖς ἐχομένοις, ARSTT. <i>H.A. 5, 11,</i> dans la suite (de l’ouvrage, du raisonnement, <i>etc</i>.) ; τοῦ ἐχομένου ἔτους, THC. <i>6, 3,</i> l’année suivante ; τὰ τῶν σιτίων ἐχόμενα, HDT. <i>3, 25,</i> ce qui se rattache aux vivres ; ὅσα σιτίων ἢ ποτῶν ἐχόμενά ἐστιν, HPC. <i>524, 53,</i> tout ce qui concerne le manger <i>ou</i> le boire ; ἃ διδασκάλων εἴχετο, PLAT. <i>Prot. 319</i> e, ce qui dépendait de maîtres ;<br><b>   IV</b> <i>p. suite,</i> dépendre de : νίκης πείρατ' ἔχονται ἐν ἀθανάτοισι θεοῖσιν, IL. <i>7, 102,</i> la victoire finale dépend des dieux immortels ;<br><b>   V</b> se tenir ferme, se fixer, <i>d’où</i> s’arrêter, être en suspens : ἐπὶ ξυροῦ ἀκμῆς, HDT. <i>6, 11,</i> sur le tranchant du rasoir, <i>en parl. d’événements qui vont se décider ;</i><br><b>   VI</b> se tenir en arrière, <i>d’où :</i><br><b>      1</b> s’abstenir de : σχέσθαι μάχης, IL. <i>3, 84 ; 9, 655 ;</i> PLUT. <i>Rom. 30,</i> s’abstenir de combattre ;<br><b>      2</b> renoncer à : τιμωρίης, HDT. <i>6, 85,</i> renoncer à une vengeance ; <i>abs</i>. IL. <i>9, 235 ;</i> A. RH. <i>3, 654 ; avec</i> τὸ μή <i>et l’inf</i>. cesser de faire qqe ch. A. RH. <i>1, 328</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Les temps de</i> ἔχω <i>se rattachent au th</i>. σεχ, <i>degré zéro</i> σχ, <i>d’où impf</i>. εἶχον <i>de</i> *ἔεχον, <i>p</i>. *ἐ-σεχ-ον ; <i>prés</i>. ἕχει, CIA. <i>4, 373</i> b (<i>commenc. du 6<sup>e</sup> siècle av. J.C</i>.) ; ἕχον, CIA. <i>4, 170, 7 (422 av. J.C</i>.) ; <i>166, 6 (413 av. J.C</i>.) ; <i>cf</i>. καθέχω ; <i>v. Meisterh. p. 66, 2 ; fut</i>. σχ-ήσω <i>ao.2</i> ἔ-σχον, <i>pf</i>. ἔ-σχη-κα, <i>etc. — Act. prés. ind. 2 sg. poét</i>. ἔχεισθα, THGN. <i>1316 ;</i> SAPPH. <i>21 Bgk ; 3 pl. dor</i>. ἔχοντι, PD. <i>P. 5, 82 Bgk ; impér. 3 pl</i>. ἐχόντων, HDT. <i>3, 155 ; sbj. 2 sg</i>. ἔχῃσθα, IL. <i>19, 180, 3 sg</i>. ἔχῃσι, OD. <i>20, 85 ; duel</i> ἔχητον, <i>2<sup>e</sup> pers</i>. IL. <i>17, 445 ; 3<sup>e</sup> pers</i>. OD. <i>6, 183 ; inf. épq</i>. ἐχέμεν, IL. <i>13, 2 ;</i> HÉS. <i>Sc. 369 ;</i> THGN. <i>9, 24. — Impf. épq</i>. ἔχον, IL. <i>9, 1 ;</i> HÉS. <i>Th. 466 ;</i> PD. <i>O. 9, 61 ; éol</i>. ἦχον, SAPPH. <i>29 Bgk. — Impf. itér</i>. ἔχεσκον, IL. <i>13, 257 ;</i> HÉS. <i>Th. 533 ;</i> HDT. <i>6, 12. — Fut. inf. épq</i>. ἐξέμεν, IL. <i>5, 473 ;</i> HÉS. <i>Th. 394. Du fut</i>. σχήσω, <i>2 sg. épq</i>. σχήσεισθα, HH. <i>Cer. 366. Au sens de</i> « avoir », <i>on ne rencontre dans les inscr. att. que le fut</i>. ἕξω (<i>non</i> σχήσω) : CIA. <i>1, 40, 28 (424 av. J.C</i>.) ; <i>2, 482, 56 (39/32 av. J.C.) ; v. Meisterh. p. 144. — Ao.1 poét. réc</i>. ἔσχα, CIA. <i>3, 1363, 5 (époque impériale</i>) ; KE. <i>120 (v. Meisterh. p. 147, 8). — Ao.2</i> ἔσχον, <i>d’où impér</i>. σχές, <i>sbj</i>. σχῶ, <i>opt</i>. σχοίην, <i>inf</i>. σχεῖν, <i>épq</i>. σχέμεν, IL. <i>8, 254. Ao.2 poét</i>. ἔσχεθον, IL. <i>12, 184 ; ou</i> σχέθον, OD. <i>10, 95 ;</i> PD. <i>fr. 65 ; 3 duel</i> ἐσχεθέτην, IL. <i>12, 461 ; impér</i>. σχέθε, OD. <i>8, 537 ; sbj</i>. σχέθω, <i>opt</i>. σχέθοιμι ; <i>inf</i>. σχεθεῖν, <i>épq</i>. σχεθέειν, IL. <i>23, 466, ou</i> σχεθέμεν, PD. <i>O. 1, 71 ; part</i>. σχεθών. — <i>Pass. prés. impér. 2 sg. poét</i>. ἔχεο, IL. <i>16, 501, etc. Impf. 3 pl</i>. εἴχοντο, IL. <i>22, 409 ; d’ord. dans Hom. sans augment :</i> ἐχόμην, OD. <i>9, 435, etc. ;</i> ἔχετο, IL. <i>6, 398, etc. ;</i> OD. <i>5, 429, etc. ; f. réc</i>. σχεθήσομαι, GAL. <i>4, 221 ; d’ord. f. moy</i>. σχήσομαι <i>au sens pass</i>. IL. <i>17, 639 ; ou</i> ἕξομαι, EUR. <i>Or. 516 ; 3 sg</i>. ἕξεται, IL. <i>9, 102. Ao.2, 3 sg. épq</i>. σχέτο, IL. <i>7, 248 ; 21, 345 ; impér</i>. σχέο, IL. <i>21, 379 ; sbj. 3 pl</i>. σχῶνται, OD. <i>13, 151 ; opt. 3 pl. ion</i>. σχοίατο, IL. <i>2, 98 ; inf</i>. σχέσθαι, OD. <i>4, 422. Ao. réc</i>. ἐσχέθην, ARR. <i>An. 5, 7 ; 6, 11. Pf. réc</i>. ἔσχημαι, PAUS. <i>4, 21 ;</i> AQU. <i>Esai. 62, 4. — Formes alexandr. : 3 pl. impf. act</i>. εἴχοσαν, ANTH. <i>5, 209 ; 3 pl. ao.2 act</i>. ἔσχοσαν, SCYMN. <i>695</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *seǵ<sup>h</sup>-, avoir, tenir.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εχω - ἔχω</font>\n<br><br>incluant une variante de 'scheo' (skheh'-o), utilisé seulement à certains temps), verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n711 fois dans 626 versets de 27 livres bibliques (NT)\n<ul>\n<li>Matthieu (72)</li>\n<li>Marc (71)</li>\n<li>Luc (78)</li>\n<li>Jean (88)</li>\n<li>Actes (44)</li>\n<li>Romains (25)</li>\n<li>1 Corinthiens (49)</li>\n<li>2 Corinthiens (22)</li>\n<li>Galates (5)</li>\n<li>Ephésiens (9)</li>\n<li>Philippiens (10)</li>\n<li>Colossiens (6)</li>\n<li>1 Thessaloniciens (9)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (14)</li>\n<li>2 Timothée (6)</li>\n<li>Tite (2)</li>\n<li>Philémon (4)</li>\n<li>Hébreux (39)</li>\n<li>Jacques (10)</li>\n<li>1 Pierre (5)</li>\n<li>2 Pierre (5)</li>\n<li>1 Jean (28)</li>\n<li>2 Jean (4)</li>\n<li>3 Jean (2)</li>\n<li>Jude (2)</li>\n<li>Apocalypse (101)</li>\n</ul>\n</td></tr>\n</table>","G2193":"<h1>heos</h1>\n<p>Strong n° 2193 <i>Prononciation [heh'-oce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>jusqu'à, jusqu'à ce que</li>\n<li>aussi longtemps que</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ἕως</b>, <i>gén</i>. <b>ἕω</b>, <i>dat</i>. <b>ἕῳ</b>, <i>acc</i>. <b>ἕω (ἡ) :<br>      1</b> l’aurore, le point du jour, ESCHL. <i>Ag. 265 ;</i> EUR. <i>Ion 1158, El. 102, etc. ;</i> πρὸ ἕω, THC. <i>4, 103 ;</i> πρὸ τῆς ἕω, THC. <i>4, 31,</i> avant l’aurore ; ἐπειδὴ ἕως ἔμελλε γίγνεσθαι, THC. <i>4, 67,</i> comme l’aurore était sur le point de paraître ; ἐπὶ τὴν ἕω, THC. <i>2, 84 ;</i> εἰς τὴν ἐπιοῦσαν ἕω, XÉN. <i>An. 1, 7, 1,</i> vers le lever de l’aurore ; πρὸς πρώτην ἕω, SOPH. <i>O.C. 477,</i> vers la naissance de l’aurore ; ἅμα ἕῳ, THC. <i>1, 48 ; 2, 90, etc. ;</i> ἅμα τῇ ἕῳ, THC. <i>3, 96 ; 4, 72, etc</i>. au point du jour ; ἐπειδὴ ἕως ἐγένετο, XÉN. <i>An. 2, 4, 24,</i> lorsque l’aurore eut paru ; μέχρι ἕως ἐγένετο, PLAT. <i>Conv. 220</i> d, jusqu’à ce que l’aurore eût paru ; ἐξ ἕω μέχρι τῆς ἑτέρας ἕω, PLAT. <i>Leg. 807</i> d, de l’aurore jusqu’à l’aurore suivante ; ἡ Ἕως, l’Aurore personnifiée, EUR. <i>Hipp. 455, etc. ;</i><br><b>      2</b> l’orient, XÉN. <i>Cyr. 8, 5, 3 ; Hell. 5, 4, 49 ;</i> PLUT. <i>Luc. 27</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Acc</i>. ἕω, CIA. <i>2, 794 d, 41 (356 av. J.C.), v. Meisterh. p. 101, 20</i>.<br><span><b>Étym</b>. <i>att. c</i>. ἠώς ; <i>cf</i>. αὔως, ἀώς, ἠώς.</span><br><br>\n➁ <b>ἕως</b>, <i>épq</i>. <b>εἵως :<br>A <i>conj</i>.<br>   I</b> jusqu’à ce que :<br><b>      1</b> <i>avec le sbj. accompagné de</i> ἄν (<i>homér</i>. κε) <i>lorsque la chose est indiquée comme future ou conditionnelle :</i> μαχήσομαι εἵως κε τέλος πολέμοιο κιχείω, IL. <i>3, 291,</i> je combattrai jusqu’à ce que je parvienne à la fin de la guerre ; <i>cf</i>. IL. <i>24, 183 ;</i> ESCHL. <i>Pr. 810 ;</i> DÉM. <i>135, 1 ; qqf. sans</i> ἄν : ἕως μάθῃς, SOPH. <i>Aj. 555,</i> jusqu’à ce que tu aies appris ; <i>cf</i>. SOPH. <i>Ph. 764 ;</i> PLAT. <i>Eryx. 392</i> c ; NT. <i>Luc. 17, 8 ;</i><br><b>      2</b> <i>avec l’opt. à la place de l’ind. dans le discours indir. :</i> ἐκέλευεν πορεύεσθαι ἡσύχως, ἕως ἄγγελος ἔλθοι, XÉN. <i>Cyr. 5, 3, 53,</i> il commandait d’avancer tranquillement, jusqu’à ce que le messager fût arrivé ; <i>à la place du sbj. après un temps historique (impf., ao</i>.) OD. <i>5, 386 ; 9, 376 ;</i> THC. <i>3, 95, 102 ; l’opt. est qqf. accompagné de</i> ἄν, SOPH. <i>Tr. 684 ;</i> PLAT. <i>Phæd. 101</i> d ; ISOCR. <i>361</i> e ; <i>de</i> κε, OD. <i>2, 78 ;</i><br><b>      3</b> <i>rar. avec l’inf. :</i> οὐ πρότερον ἀνέῳξαν τὰς πύλας ἢ ἕως (= πρὶν) ἡμέραν λαμπρὰν γενέσθαι, DH. <i>9, 15,</i> ils n’ouvrirent pas les portes avant qu’il ne fît grand jour ; <i>cf</i>. HDT. <i>4, 42 ;</i> GEOP. <i>3, 5, 3 ;</i><br><b>   II</b> tandis que, pendant que, tant que, aussi longtemps que :<br><b>      1</b> <i>avec l’ind. lorsque la chose est indiquée comme présente,</i> OD. <i>17, 358, 390 ;</i> εἵως πολεμίζομεν, OD. <i>13, 315,</i> tant que nous faisons la guerre ; <i>en ce sens, sans verbe :</i> ἕως ἔτι ἐλπίς, THC. <i>8, 40,</i> tant qu’il y avait de l’espoir ; ἕως ἔτι σοι σχολή, XÉN. <i>Cyr. 7, 1, 18,</i> tandis qui tu en as encore le temps ; ἕως ἔτι τὸ πέλαγος οἷόν τε περαιοῦσθαι, THC. <i>7, 47,</i> pendant qu’on pouvait encore traverser la mer ; <i>en ce sens, il a pour corrélatifs</i> τέως, <i>épq</i>. τείως, OD. <i>4, 90 ;</i> τόφρα, IL. <i>18, 15 ;</i> OD. <i>12, 328 ;</i> τόφρα δέ, IL. <i>10, 507, etc. ;</i> δέ, IL. <i>1, 193 ;</i> OD. <i>4, 120 ;</i><br><b>      2</b> <i>avec</i> ἄν <i>et le sbj. en parl. d’un événement futur :</i> ἕως ἂν αἴθῃ πῦρ, ESCHL. <i>Ag. 1435,</i> aussi longtemps qu’(Égisthe) allumera le feu (à mon foyer) ;<br><b>      3</b> <i>avec l’opt. avec idée de répétition,</i> PLAT. <i>Theæt. 155</i> a ;<br><b>   III</b> afin que, <i>c</i>. ὅφρα, <i>avec l’opt</i>. OD. <i>4, 800 ; 6, 80 ; 19, 367 ;</i><br><b>B</b> <i><b>adv.-prép</b>. avec idée de lieu ou de temps :</i><br><b>   I</b> jusque :<br><b>      1</b> <i>avec le gén</i>. jusqu’à ce point, jusqu’à ce moment : ἕως οὗ, HDT. <i>2, 103 ;</i> NT. <i>Matth. 1, 24 ;</i> ἕως ὅτου, NT. <i>Matth. 5, 25,</i> jusqu’à ce que ;<br><b>      2</b> <i>avec une prép</i>. ἕως εἰς, POL. <i>1, 11, 14 ;</i> SPT. <i>Lev. 23, 14 ; 1 Macc. 2, 58 ;</i> NT. <i>Luc. 24, 50 ;</i> ἕως πρός, ANTH. <i>5, 201 ;</i> SPT. <i>Gen. 38, 1 ;</i> ἕως ἐπί (<i>var</i>. ὡς) NT. <i>Ap. 17, 14,</i> jusque vers, jusqu’à ;<br><b>      3</b> <i>avec une conj</i>. ἕως ὅτε <i>avec l’ind</i>. jusqu’au moment où, XÉN. <i>Cyr. 5, 1, 25, dout., mais us. chez les écriv. réc</i>. SPT. <i>Neh. 2, 16,</i> NT. <i>Marc. 9, 19 ; Luc. 9, 41 ;</i><br><b>      4</b> <i>avec un adv</i>. ἕως πότε ; NT. <i>Matth. 17, 17 ; Joh. 10, 24,</i> jusques à quand ? ἕως ὀψέ, THC. <i>3, 108,</i> jusqu’à un temps éloigné ; ἕως ἄρτι, NT. <i>Joh. 2, 10,</i> jusqu’à présent ; <i>et avec idée de lieu,</i> ἕως ὧδε, NT. <i>Luc. 23, 5,</i> jusqu’ici ; ἕως ἄνω, NT. <i>Joh. 2, 7,</i> jusqu’en haut ; ἕως κάτω, NT. <i>Marc. 15, 38,</i> jusqu’en bas ;<br><b>   II</b> pendant un certain temps, quelque temps, IL. <i>12, 142 ; 13, 143, etc. ;</i> OD. <i>2, 148 ;</i> HDT. <i>8, 74 (conj</i>. τέως) ; <i>d’où</i> continuellement, OD. <i>3, 126</i>.<br><span><b><span class=\"arrow\"></span></b> ἕως <i>dissyll. seul</i>. OD. <i>2, 78 ; d’ord. monosyll</i>. IL. <i>17, 127 ;</i> OD. <i>2, 148, etc. ; spondée sous la forme</i> εἵως, IL. <i>3, 291 ; 11, 342, etc. ; trochée sous la forme</i> εἷος, IL. <i>10, 507 ;</i> OD. <i>4, 90, etc. Dor</i>. ἇς <i>pour</i> *ἇος, *ἇϝος = ἕως, PD. <i>O. 11, 53 ;</i> AR. <i>Lys. 173. Éol</i>. ἆς, THCR. <i>Idyl. 29, 20. Dans les inscr. att</i>. ἕως, <i>sans exemple comme prépos. (v. Meisterh. p. 178, 31) se rencontre comme conj. avec</i> ἄν <i>et le sbj. ao</i>. CIA. <i>1, 37, frg. f, g, k, 24 (425 av. J.C.) etc. ; une seule fois avec le sbj. prés. Mitt. 4, 200, 11 (325 av. J.C</i>.) ; <i>v. Meisterh. ibid. ; on ne le rencontre sans</i> ἄν <i>avec le sbj. ao. qu’une fois,</i> CIA. <i>2, 624, 18 (1<sup>re</sup> moitié du 2<sup>e</sup> siècle</i>) ; <i>v. Meisterh. ibid</i>.<br><span><b>Étym</b>. <i>p. proto-grec</i> *ἆϝος, <i>de indo-europ</i>. *ieh₂uot, aussi longtemps que, jusqu’à ce que ; <i>cf. sscr</i>. yā́vat, aussi longtemps que.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εως - ἕως</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Conjonction</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n148 fois dans 139 versets de 15 livres bibliques (NT)\n<ul>\n<li>Matthieu (48)</li>\n<li>Marc (15)</li>\n<li>Luc (28)</li>\n<li>Jean (13)</li>\n<li>Actes (21)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (6)</li>\n<li>2 Corinthiens (3)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (3)</li>\n<li>Jacques (2)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G2194":"<h1>Zaboulon</h1>\n<p>Strong n° 2194 <i>Prononciation [dzab-oo-lone']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Zabulon (Angl. Zebulun) = « une habitation »\n<ol>\n<li>le dixième des fils de Jacob</li>\n<li>la tribu de Zabulon</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ζαβουλων</font> &lt; זבלון - <font face=\"Georgia\">Ζαβουλών</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2195":"<h1>Zakchaios</h1>\n<p>Strong n° 2195 <i>Prononciation [dzak-chah'-ee-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Zachée (Angl. Zacchaeus) = « pur »\n<ol><li>un collecteur principal d'impôts</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ζακχαιος</font> &lt; זכי - <font face=\"Georgia\">Ζακχαῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (3)</li>\n</ul>\n</td></tr>\n</table>","G2196":"<h1>Zara</h1>\n<p>Strong n° 2196 <i>Prononciation [dzar-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Zara = « un lever (comme le soleil) »\n<ol><li>le fils de Juda, ancêtre de Christ</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ζαρα</font> &lt; זרח - <font face=\"Georgia\">Ζάρα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G2197":"<h1>Zacharias</h1>\n<p>Strong n° 2197 <i>Prononciation [dzakh-ar-ee'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Zacharie (Angl. Zacharias) = « l'Eternel se souvient »\n<ol>\n<li>le père de Jean-Baptiste</li>\n<li>fils de Barachie, qui fut tué par les Juifs entre l'autel et le temple</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ζαχαρίας, ου (ὁ)</b> Zakharias (Zacharie) <i>n. d’h. hébreu</i>, NT. <i>Luc. 1, 5 ; Matth. 23, 35, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Voc</i>. -ία, NT. <i>Luc. 1, 13</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ζαχαριας</font> &lt; זכריה - <font face=\"Georgia\">Ζαχαρίας</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (10)</li>\n</ul>\n</td></tr>\n</table>","G2198":"<h1>zao</h1>\n<p>Strong n° 2198 <i>Prononciation [dzah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>vivre, respirer, être parmi les vivants (non mort)</li>\n<li>vivre une vraie vie\n<ol type=\"a\">\n<li>avoir la vraie vie, celle digne de ce nom</li>\n<li>actif, béni, destiné au royaume de Dieu</li>\n</ol>\n</li>\n<li>vivre c.à.d passer sa vie, manière de vivre et d'agir</li>\n<li>eau de vie, avoir un pouvoir vital en soi</li>\n<li>métaph. être en pleine vigueur\n<ol type=\"a\">\n<li>être frais, fort, efficace</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ζάω-ῶ</b> <i>ou mieux</i> <b>ζήω-ῶ</b> <span>(<i>avec contract. en</i> η, <i>d’où prés</i>. ζῶ, ζῇς, ζῇ ; <i>impér</i>. ζῆ, <i>opt</i>. ζῴην ; <i>inf</i>. ζῆν ; <i>impf</i>. ἔζων, ἔζης, ἔζη, ἐζῶμεν, ἐζῆτε, ἔζων ; <i>fut</i>. ζήσω <i>ou</i> ζήσομαι ; <i>ao</i>. ἔζησα, <i>pf</i>. ἔζηκα, <i>pl.q.pf</i>. ἐζήκειν ; <i>ttef. au lieu de</i> ἔζησα, ἔζηκα, ἐζήκειν, <i>les Attiques emploient d’ord. les ao. pf. et pl.q.pf. de</i> βιόω)</span><br><b>   I <i>intr.</i></b> vivre, <i>d’où :</i><br><b>      1</b> être en vie, <i>p. opp. à</i> θνῄσκω, IL. <i>23, 70 ;</i> OD. <i>11, 302 ;</i> HDT. <i>1, 31, etc. en parl. des hommes, des animaux, etc</i>. OD. <i>10, 72, etc. ; en parl. des plantes</i>, ARSTT. <i>Nic. 1, 7, 12 ;</i> οἱ ζῶντες, OD. <i>10, 72</i>, les vivants, <i>càd. d’ord</i>. les hommes ; <i>souv. joint à des synonymes :</i> εἶναί τε καὶ ζῆν. PLAT. <i>Rsp. 369</i> d, être et vivre ; ζώντων καὶ ὄντων, DÉM. <i>248, 25</i>, vivants et bien vivants (<i>cf</i>. DÉM. <i>953 ;</i> LIB. <i>4, 40</i>) ; ζῶν καὶ βλέπων, ESCHL. <i>Ag. 677</i>, vivant et voyant le jour ; ζῶντος καὶ ἐπὶ χθονὶ δερκομένοιο, IL. <i>1, 88</i>, vivant et voyant la lumière sur la terre ; <i>avec un acc. de temps :</i> ζ. ὀλίγα ἔτεα, HDT. <i>3, 22</i>, vivre peu d’années ; <i>cf</i>. HH. <i>Ven. 222 ;</i> ζήτω ὁ βασιλεύς, SPT. <i>1Reg. 10, 24</i>, vive le roi ! longue vie au roi ! <i>cf</i>. SPT. <i>Dan. 2, 4 ; de même dans diverses formules :</i> ζῶ ἐγὼ καὶ ζῶν τὸ ὄνομά μου, SPT. <i>Num. 14, 21</i>, aussi vrai que je vis et que mon nom est vivant ; ζῇ Κύριος καὶ ζῇ ἡ ψυχή σου, SPT. <i>1Reg. 25, 26</i>, aussi vrai que le Seigneur vit et que vit ton âme ; <i>cf</i>. SPT. <i>Judith 2, 12 ; subst</i>. τὸ ζῆν, ESCHL. <i>Pr. 681 ;</i> PLAT. <i>Phæd. 77</i> e, la vie (<i>cf</i>. ζωή), <i>et sans art. :</i> εἰς ἕτερον ζῆν, PLAT. <i>Ax. 365</i> d, dans une autre vie ;<br><b>      2</b> soutenir sa vie, se faire vivre : ἐπιπονώτατα, XÉN. <i>Cyr. 7, 5, 67</i>, avec beaucoup de peine ; τινι, OD. <i>17, 423 ; 19, 79 ; cf</i>. DÉM. <i>1390, 11 ;</i> ἀπό τινος, HDT. <i>1, 216, etc. ;</i> AR. <i>Pax 850 ;</i> ἔκ τινος, XÉN. <i>Hell. 3, 2, 11 ;</i> AR. <i>Eccl. 591 ;</i> DÉM. <i>1309, 26</i>, vivre de qqe ch. ; <i>avec un part. :</i> ζῶσιν ἐργαζόμενοι, ARSTT. <i>Pol. 4, 6, 2</i>, ils vivent en travaillant ;<br><b>      3</b> vivre, passer sa vie : εὖ ζῆν, SOPH. <i>Ph. 505 ;</i> κακῶς, SOPH. <i>O.C. 799</i>, avoir une vie heureuse, malheureuse ; ζῆν αἰσχρῶς, SOPH. <i>El. 989 ;</i> ISOCR. <i>22</i> b, vivre honteusement ; <i>avec un acc. de manière :</i> ζ. βίον μοχθηρόν, SOPH. <i>El. 599</i>, vivre d’une vie misérable ; <i>ou avec le dat. :</i> ζ. ἀϐλαϐεῖ βίῳ, SOPH. <i>El. 650</i>, passer sa vie sans éprouver de dommage ; ἐκ τῶν ἄλλων ὧν ἔζης, DÉM. <i>559, 1</i>, d’après toutes les autres choses que tu as faites dans ta vie ;<br><b>      4</b> <i>fig. en parl. de choses</i>, être dans toute sa force : ἄτης θύελλαι ζῶσι, ESCHL. <i>Ag. 849</i>, les tempêtes du malheur sont dans toute leur force ; ζῶσα φλόξ, EUR. <i>Bacch. 8</i>, flamme vivante ; ἀεὶ ζῇ ταῦτα (νόμιμα) SOPH. <i>Ant. 457</i>, ces lois sont toujours vivantes ; χρόνος ζῶν καὶ παρών, SOPH. <i>fr. 1169</i>, temps vivant et présent ;<br><b>   II <i>tr.</i></b> faire vivre, donner la vie à, vivifier, SPT. <i>Ps. 118, 40, 50, 93 ; 142 ; 149 ; 154 ; Ezech. 13, 22</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. impér. 2 sg</i>. ζῆ, SOPH. <i>fr. 181 ;</i> EUR. <i>I.T. 687 ; postér</i>., ζῆθι, ANTH. <i>10, 43 ;</i> CIA. <i>3, 1355 (époque impériale</i>) ; <i>v. Meisterh. p. 139, § 63 ;</i> SPT. <i>Dan. 2, 4. Impf. 1 sg</i>. ἔζων, SOPH. <i>El. 323 ;</i> AR. <i>Ran. 1072 ; 2 sg</i>. ἔζης, ESCHL. <i>Ch. 360 ;</i> SOPH. <i>fr. 603 Dind. ; etc. 3 sg</i>. ἔζη, ESCHL. <i>Ch. 360 ;</i> SOPH. <i>Aj. 1060 ; 1 pl</i>. ἐζῶμεν, PLAT. <i>Ep. 347 ; 2 pl</i>. ἐζῆτε, XÉN. <i>Cyr. 7, 2, 26 ; 3 pl</i>. ἔζων, PLAT. <i>Leg. 679</i> c ; AR. <i>Vesp. 709. Fut</i>. ζήσω, AR. <i>Pl. 263 ;</i> PLAT. <i>Rsp. 465</i> d ; <i>ou</i> ζήσομαι, HPC. <i>247, 27 ;</i> DÉM. <i>794, 20 ;</i> ARSTT. <i>Pol. 7, 6, 7. Ao</i>. ἔζησα, HPC. <i>36, 16 ;</i> ANTH. <i>7, 470. Pf</i>. ἔζηκα, ARSTT. <i>Metaph. 8, 6, 8 ;</i> DH. <i>5, 68</i>.<br><span><b>Étym</b>. ζώω ; ζάω <i>est une forme construite par des anciens grammairiens</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ζαω - ζάω</font>\n<br><br>verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n140 fois dans 124 versets de 20 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Marc (3)</li>\n<li>Luc (8)</li>\n<li>Jean (17)</li>\n<li>Actes (12)</li>\n<li>Romains (22)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (9)</li>\n<li>Galates (9)</li>\n<li>Philippiens (2)</li>\n<li>Colossiens (2)</li>\n<li>1 Thessaloniciens (5)</li>\n<li>1 Timothée (3)</li>\n<li>2 Timothée (2)</li>\n<li>Tite (1)</li>\n<li>Hébreux (12)</li>\n<li>Jacques (2)</li>\n<li>1 Pierre (7)</li>\n<li>1 Jean (1)</li>\n<li>Apocalypse (14)</li>\n</ul>\n</td></tr>\n</table>","G2199":"<h1>Zebedaios</h1>\n<p>Strong n° 2199 <i>Prononciation [dzeb-ed-ah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Zébédée (Angl. Zebedee) = « l'Eternel a donné »\n<ol><li>pêcheur de Galilée, le père des apôtres Jacques le Majeur et de Jean, et le mari de Salomé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ζεβεδαιος</font> &lt; זבדי - <font face=\"Georgia\">Ζεβεδαῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 11 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Marc (4)</li>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>"};
